// Doorwarden is an on-chain security checklist and review registry for
// Gno realms: the bouncer at the tavern door. Builders (or reviewers)
// submit a per-check verdict for a realm path; Doorwarden scores it
// against a canonical list of Gno security pitfalls and publishes the
// result on a public leaderboard.
//
// A review is encoded as one character per checklist item, in order:
// 'P' = pass, 'F' = fail, 'N' = not applicable.
package doorwarden

import (
	"strconv"
	"strings"
)

// Check is one item of the canonical security checklist.
type Check struct {
	ID       string
	Title    string
	Severity string
	Weight   int
	Guidance string
}

// Review is one reviewer's verdict on one realm path.
type Review struct {
	RealmPath string
	Reviewer  string
	Results   string
	Note      string
	Score     int
	Seq       int
}

const (
	maxPathLen  = 128
	maxNoteLen  = 280
	maxBoardOut = 25
	maxRecent   = 10
)

// checks is the canonical Doorwarden checklist. Order matters: review
// result strings are positional against this list.
var checks = []Check{
	{ID: "caller-auth", Title: "Caller authentication", Severity: "Critical", Weight: 3,
		Guidance: "State-changing crossing functions derive caller identity from cur.Previous() and authorize explicitly; never trust caller-supplied addresses or tx-origin style assumptions."},
	{ID: "payment-guard", Title: "Payment verification", Severity: "Critical", Weight: 3,
		Guidance: "Functions that credit value verify the coins actually sent (denom and amount) in the same call and require a direct user call; never credit on promised payment."},
	{ID: "render-sanitize", Title: "Render output safety", Severity: "High", Weight: 2,
		Guidance: "Render() treats its path argument and all stored user strings as attacker-controlled; markdown metacharacters are escaped before output."},
	{ID: "bounds-dos", Title: "Bounds and DoS resistance", Severity: "High", Weight: 2,
		Guidance: "All inputs are length-capped, loops over user-grown state are bounded or paginated, and storage growth per call is priced in."},
	{ID: "cross-realm-trust", Title: "Cross-realm trust", Severity: "High", Weight: 2,
		Guidance: "Calls from other realms are not trusted by pkgpath or arguments alone; pointers to mutable realm state are never returned to callers."},
	{ID: "arithmetic", Title: "Arithmetic safety", Severity: "Medium", Weight: 1,
		Guidance: "Arithmetic is bounds-checked; division by zero and overflow paths are handled explicitly."},
	{ID: "init-admin", Title: "Initialization and admin", Severity: "Medium", Weight: 1,
		Guidance: "Deployment-time state (owner/admin) is set correctly, and realm immutability is planned for with explicit versioning."},
	{ID: "tests", Title: "Test coverage", Severity: "Medium", Weight: 1,
		Guidance: "The realm ships _test.gno tests covering crossing functions, authorization failures, and invalid inputs."},
}

var (
	reviews       []Review
	reviewedPaths []string
	bestScores    []int // parallel to reviewedPaths
	reviewCounts  []int // parallel to reviewedPaths
	seq           int
)

// CheckCount returns the number of checklist items. A valid results
// string has exactly this many characters.
func CheckCount() int {
	return len(checks)
}

// ScoreResults scores a results string against the checklist.
// 'P' earns the check's weight, 'F' earns nothing, 'N' excludes the
// check. The score is a rounded percentage; a review with no
// applicable checks scores 0. Panics on malformed input.
func ScoreResults(results string) int {
	score, _ := scoreOf(results)
	return score
}

func scoreOf(results string) (int, int) {
	if len(results) != len(checks) {
		panic("results must have exactly " + strconv.Itoa(len(checks)) + " characters, one per check")
	}
	earned := 0
	possible := 0
	for i := 0; i < len(results); i++ {
		switch results[i] {
		case 'P', 'p':
			earned += checks[i].Weight
			possible += checks[i].Weight
		case 'F', 'f':
			possible += checks[i].Weight
		case 'N', 'n':
		default:
			panic("results may only contain P, F or N")
		}
	}
	if possible == 0 {
		return 0, 0
	}
	return (earned*100 + possible/2) / possible, possible
}

// Verdict maps a score to the door verdict.
func Verdict(score int) string {
	switch {
	case score >= 90:
		return "Tavern-ready"
	case score >= 70:
		return "Mostly sound"
	case score >= 40:
		return "Needs work"
	default:
		return "Turned away"
	}
}

// SubmitReview records (or updates) the caller's review of a realm
// path. One review per reviewer per path: resubmitting replaces the
// previous verdict. Returns a one-line summary.
func SubmitReview(cur realm, realmPath string, results string, note string) string {
	if !validPkgPath(realmPath) {
		panic("realmPath must be a gno.land/r/ or gno.land/p/ package path")
	}
	if len(note) > maxNoteLen {
		panic("note exceeds " + strconv.Itoa(maxNoteLen) + " characters")
	}
	score, possible := scoreOf(results)
	reviewer := cur.Previous().Address().String()
	seq++

	idx := findReview(realmPath, reviewer)
	if idx >= 0 {
		reviews[idx].Results = results
		reviews[idx].Note = note
		reviews[idx].Score = score
		reviews[idx].Seq = seq
	} else {
		reviews = append(reviews, Review{
			RealmPath: realmPath,
			Reviewer:  reviewer,
			Results:   results,
			Note:      note,
			Score:     score,
			Seq:       seq,
		})
	}
	recomputePath(realmPath)

	verdict := Verdict(score)
	if possible == 0 {
		verdict = "No applicable checks"
	}
	return realmPath + " scored " + strconv.Itoa(score) + "/100 - " + verdict +
		" (review #" + strconv.Itoa(seq) + ")"
}

// BestScore returns the highest review score for a realm path, or -1
// if the path has never been reviewed.
func BestScore(realmPath string) int {
	for i, p := range reviewedPaths {
		if p == realmPath {
			return bestScores[i]
		}
	}
	return -1
}

// ReviewCount returns how many distinct reviewers have reviewed a
// realm path.
func ReviewCount(realmPath string) int {
	for i, p := range reviewedPaths {
		if p == realmPath {
			return reviewCounts[i]
		}
	}
	return 0
}

// TotalReviews returns the number of reviews ever submitted,
// counting updates.
func TotalReviews() int {
	return seq
}

func findReview(realmPath string, reviewer string) int {
	for i, r := range reviews {
		if r.RealmPath == realmPath && r.Reviewer == reviewer {
			return i
		}
	}
	return -1
}

func recomputePath(realmPath string) {
	best := -1
	count := 0
	for _, r := range reviews {
		if r.RealmPath == realmPath {
			count++
			if r.Score > best {
				best = r.Score
			}
		}
	}
	for i, p := range reviewedPaths {
		if p == realmPath {
			bestScores[i] = best
			reviewCounts[i] = count
			return
		}
	}
	reviewedPaths = append(reviewedPaths, realmPath)
	bestScores = append(bestScores, best)
	reviewCounts = append(reviewCounts, count)
}

func validPkgPath(path string) bool {
	if len(path) > maxPathLen {
		return false
	}
	if !strings.HasPrefix(path, "gno.land/r/") && !strings.HasPrefix(path, "gno.land/p/") {
		return false
	}
	for i := 0; i < len(path); i++ {
		c := path[i]
		ok := (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') ||
			(c >= '0' && c <= '9') || c == '/' || c == '.' || c == '_' || c == '-'
		if !ok {
			return false
		}
	}
	return true
}

// sanitize strips markdown metacharacters from user-controlled text
// before it reaches Render output.
func sanitize(s string) string {
	out := ""
	for i := 0; i < len(s); i++ {
		switch s[i] {
		case '`', '*', '_', '[', ']', '(', ')', '<', '>', '#', '|', '\\', '~', '\n', '\r':
			out += " "
		default:
			out += s[i : i+1]
		}
	}
	return out
}

// Render serves the realm's public pages: "" (home), "checks",
// "leaderboard" and "reviews".
func Render(path string) string {
	switch path {
	case "checks":
		return renderChecks()
	case "leaderboard":
		return renderLeaderboard()
	case "reviews":
		return renderReviews()
	default:
		return renderHome()
	}
}

func renderHome() string {
	out := "# Doorwarden\n\n"
	out += "The bouncer for your realm. Doorwarden scores Gno realms against a canonical " +
		"security checklist and publishes the verdict on-chain.\n\n"
	out += "Submit a review with SubmitReview: one character per check below, in order - " +
		"P (pass), F (fail), N (not applicable).\n\n"
	out += "## The checklist\n\n"
	out += checklistTable()
	out += "\nPages: checks (full guidance), leaderboard (best scores), reviews (latest verdicts).\n"
	return out
}

func checklistTable() string {
	out := "| # | Check | Severity | Weight |\n|---|---|---|---|\n"
	for i, c := range checks {
		out += "| " + strconv.Itoa(i+1) + " | " + c.ID + " - " + c.Title + " | " +
			c.Severity + " | " + strconv.Itoa(c.Weight) + " |\n"
	}
	return out
}

func renderChecks() string {
	out := "# Doorwarden checklist\n\n"
	for i, c := range checks {
		out += "## " + strconv.Itoa(i+1) + ". " + c.ID + " - " + c.Title + "\n\n"
		out += "Severity: " + c.Severity + " | Weight: " + strconv.Itoa(c.Weight) + "\n\n"
		out += c.Guidance + "\n\n"
	}
	return out
}

func renderLeaderboard() string {
	out := "# Doorwarden leaderboard\n\n"
	if len(reviewedPaths) == 0 {
		return out + "No realms reviewed yet. Be the first to face the door.\n"
	}
	order := sortedPaths()
	out += "| Realm | Best score | Verdict | Reviews |\n|---|---|---|---|\n"
	shown := 0
	for _, i := range order {
		if shown >= maxBoardOut {
			break
		}
		out += "| " + sanitize(reviewedPaths[i]) + " | " + strconv.Itoa(bestScores[i]) +
			" | " + Verdict(bestScores[i]) + " | " + strconv.Itoa(reviewCounts[i]) + " |\n"
		shown++
	}
	return out
}

func sortedPaths() []int {
	order := make([]int, len(reviewedPaths))
	for i := range order {
		order[i] = i
	}
	for i := 0; i < len(order); i++ {
		for j := i + 1; j < len(order); j++ {
			a, b := order[i], order[j]
			if bestScores[b] > bestScores[a] ||
				(bestScores[b] == bestScores[a] && reviewedPaths[b] < reviewedPaths[a]) {
				order[i], order[j] = b, a
			}
		}
	}
	return order
}

func renderReviews() string {
	out := "# Latest reviews\n\n"
	if len(reviews) == 0 {
		return out + "No reviews yet.\n"
	}
	shown := 0
	for i := len(reviews) - 1; i >= 0 && shown < maxRecent; i-- {
		r := reviews[i]
		out += "- " + sanitize(r.RealmPath) + " - " + strconv.Itoa(r.Score) + "/100 (" +
			Verdict(r.Score) + ") by " + sanitize(r.Reviewer)
		if r.Note != "" {
			out += ": " + sanitize(r.Note)
		}
		out += "\n"
		shown++
	}
	return out
}

package doorwarden

import (
	"strings"
	"testing"
)

func TestScoreAllPass(cur realm, t *testing.T) {
	if got := ScoreResults("PPPPPPPP"); got != 100 {
		t.Fatalf("expected 100, got %d", got)
	}
}

func TestScoreMixed(cur realm, t *testing.T) {
	// Weights are 3,3,2,2,2,1,1,1 (total 15). Six passes earn 13,
	// so 13/15 rounds to 87.
	if got := ScoreResults("PPPPPPFF"); got != 87 {
		t.Fatalf("expected 87, got %d", got)
	}
	if got := ScoreResults("FFFFFFFF"); got != 0 {
		t.Fatalf("expected 0, got %d", got)
	}
}

func TestScoreNA(cur realm, t *testing.T) {
	if got := ScoreResults("NNNNNNNN"); got != 0 {
		t.Fatalf("expected 0 for all-N/A, got %d", got)
	}
	if got := ScoreResults("PNNNNNNN"); got != 100 {
		t.Fatalf("expected 100 for single applicable pass, got %d", got)
	}
}

func TestVerdict(cur realm, t *testing.T) {
	cases := []struct {
		score int
		want  string
	}{
		{100, "Tavern-ready"},
		{90, "Tavern-ready"},
		{70, "Mostly sound"},
		{40, "Needs work"},
		{39, "Turned away"},
		{0, "Turned away"},
	}
	for _, c := range cases {
		if got := Verdict(c.score); got != c.want {
			t.Fatalf("Verdict(%d): expected %q, got %q", c.score, c.want, got)
		}
	}
}

func TestSubmitReviewFlow(cur realm, t *testing.T) {
	path := "gno.land/r/example/vault"
	out := SubmitReview(cross(cur), path, "PPPPPPPP", "solid work")
	if !strings.Contains(out, "100/100") {
		t.Fatalf("unexpected summary: %s", out)
	}
	if got := BestScore(path); got != 100 {
		t.Fatalf("expected best score 100, got %d", got)
	}
	if got := ReviewCount(path); got != 1 {
		t.Fatalf("expected 1 review, got %d", got)
	}

	// Same reviewer resubmits: verdict updates, count does not grow.
	SubmitReview(cross(cur), path, "FFFFFFFF", "found a hole")
	if got := BestScore(path); got != 0 {
		t.Fatalf("expected best score 0 after update, got %d", got)
	}
	if got := ReviewCount(path); got != 1 {
		t.Fatalf("expected review count to stay 1, got %d", got)
	}
	if got := BestScore("gno.land/r/example/never-reviewed"); got != -1 {
		t.Fatalf("expected -1 for unreviewed path, got %d", got)
	}
}

func TestInvalidResultsPanics(cur realm, t *testing.T) {
	defer func() {
		if recover() == nil {
			t.Fatalf("expected panic for short results string")
		}
	}()
	ScoreResults("PP")
}

func TestValidPkgPath(cur realm, t *testing.T) {
	// SubmitReview panics on invalid paths; a panic inside a crossing
	// call cannot be recovered by the caller, so the validation helper
	// is tested directly.
	if validPkgPath("not-a-pkgpath") {
		t.Fatalf("expected invalid path to be rejected")
	}
	if validPkgPath("gno.land/r/bad path/with spaces") {
		t.Fatalf("expected path with spaces to be rejected")
	}
	if !validPkgPath("gno.land/r/example/vault") {
		t.Fatalf("expected realm path to be accepted")
	}
	if !validPkgPath("gno.land/p/example/lib") {
		t.Fatalf("expected package path to be accepted")
	}
}

func TestSanitize(cur realm, t *testing.T) {
	if got := sanitize("a*b`c[d]"); got != "a b c d " {
		t.Fatalf("unexpected sanitize output: %q", got)
	}
}

func TestRender(cur realm, t *testing.T) {
	home := Render("")
	if !strings.Contains(home, "Doorwarden") || !strings.Contains(home, "caller-auth") {
		t.Fatalf("home render missing expected content")
	}
	if !strings.Contains(Render("checks"), "Payment verification") {
		t.Fatalf("checks render missing expected content")
	}
	SubmitReview(cross(cur), "gno.land/r/example/vault", "PPPPPPPP", "")
	if !strings.Contains(Render("leaderboard"), "gno.land/r/example/vault") {
		t.Fatalf("leaderboard missing reviewed realm")
	}
	if !strings.Contains(Render("reviews"), "100/100") {
		t.Fatalf("reviews render missing expected content")
	}
}

package counter

import "strconv"

var counter int

func Increment(_ realm) int {
	counter++
	return counter
}

func Render(_ string) string {
	return "Count: " + strconv.Itoa(counter)
}

package competition

import (
	"chain"
	"chain/banker"
	"chain/runtime"
	"chain/runtime/unsafe"
	"encoding/hex"
	"strconv"
	"strings"
	"time"
)

const (
	denom = "ugnot"
	ruleset = "strait-run-v1"
	maxScore = 30200
	attemptCap = 3
	weekSeconds int64 = 7 * 24 * 60 * 60
	firstMonday int64 = 4 * 24 * 60 * 60
	maxCoin int64 = 9223372036854775807
)

var (
	admin address
	verifier address
	treasury address
	paused bool
	firstSeason int64
	nextSnapshot int64
	seasonRules = make(map[int64][10]int64)
	seasons = make(map[int64]*Season)
	duels = make(map[int64]*Duel)
	duelReferences = make(map[string]bool)
	pilotDuels = make(map[address][]int64)
	catalog = make(map[int64]*Cosmetic)
	purchases = make(map[string]*Purchase)
	nextDuelID int64 = 1
	nextCosmeticID int64 = 1
	retainedClaimable int64
)

func init(cur realm) {
	admin = cur.Previous().Address()
}

func Configure(cur realm, signer, retainedRecipient address, start int64) {
	runtime.AssertOriginCall()
	requireAdmin(cur)
	now := time.Now().Unix()
	require(firstSeason == 0 && start >= weekID(now)+1 && start < weekID(now)+53, "publish a future opening week")
	require(signer.IsValid() && signer != admin && retainedRecipient.IsValid(), "invalid verifier or treasury")
	firstSeason, nextSnapshot = start, start
	verifier, treasury = signer, retainedRecipient
}

func SetVerifier(cur realm, signer address) {
	runtime.AssertOriginCall()
	requireAdmin(cur)
	require(signer.IsValid() && signer != admin, "invalid verifier")
	verifier = signer
}

func PauseEntries(cur realm, stop bool) {
	runtime.AssertOriginCall()
	requireAdmin(cur)
	paused = stop
}

func PublishShares(cur realm, id int64, csv string) {
	runtime.AssertOriginCall()
	requireAdmin(cur)
	now := weekID(time.Now().Unix())
	require(firstSeason > 0 && id >= firstSeason && id > now && id < now+53, "only a future season can be configured")
	require(len(csv) <= 50, "invalid share length")
	_, published := seasonRules[id]
	require(!published, "shares already published")
	parts := strings.Split(csv, ",")
	require(len(parts) == 10, "ten shares required")
	var shares [10]int64
	var total int64
	for i, part := range parts {
		value, err := strconv.ParseInt(part, 10, 64)
		require(err == nil && value > 0 && value <= 10000, "invalid share")
		shares[i] = value
		total += value
	}
	require(total == 10000, "shares must sum to 10000")
	seasonRules[id] = shares
}

func ClaimTreasury(cur realm) int64 {
	runtime.AssertOriginCall()
	caller := paidCaller(cur, 0)
	require(caller == treasury, "treasury only")
	amount := retainedClaimable
	retainedClaimable = 0
	pay(cur, caller, amount)
	return amount
}

func requireAdmin(cur realm) {
	require(paidCaller(cur, 0) == admin, "admin only")
}

// The public entry point must assert the origin before calling this helper.
func paidCaller(cur realm, amount int64) address {
	require(cur.IsCurrent(), "invalid realm frame")
	previous := cur.Previous()
	require(previous.IsUserCall(), "direct wallet call required")
	checkPayment(unsafe.OriginSend(), amount)
	return previous.Address()
}

func checkPayment(sent chain.Coins, amount int64) {
	if amount == 0 {
		require(len(sent) == 0, "unexpected payment")
		return
	}
	require(amount > 0 && len(sent) == 1 && sent[0].Denom == denom && sent[0].Amount == amount, "exact ugnot payment required")
}

func pay(cur realm, recipient address, amount int64) {
	if amount > 0 {
		banker.NewBanker(banker.BankerTypeRealmSend, cur).SendCoins(cur.Address(), recipient, chain.Coins{{Denom: denom, Amount: amount}})
	}
}

func require(condition bool, message string) {
	if !condition {
		panic(message)
	}
}

func checkedAdd(a, b int64) int64 {
	require(a >= 0 && b >= 0 && a <= maxCoin-b, "amount overflow")
	return a + b
}

func basisPoints(amount, share int64) int64 {
	return amount/10000*share + amount%10000*share/10000
}

func weekID(timestamp int64) int64 {
	return (timestamp-firstMonday)/weekSeconds
}

func weekStart(id int64) int64 {
	return firstMonday + id*weekSeconds
}

func decimal(value int64) string {
	return strconv.FormatInt(value, 10)
}

func validHex(value string, size int) bool {
	if len(value) != size || strings.ToLower(value) != value {
		return false
	}
	_, err := hex.DecodeString(value)
	return err == nil
}

package competition

import (
	"chain/runtime"
	"crypto/ed25519"
	"encoding/hex"
	"strings"
	"time"
)

var duelVerifierKey string

func SetDuelVerifier(cur realm, publicKey string) {
	runtime.AssertOriginCall()
	requireAdmin(cur)
	require(validHex(publicKey, 64), "invalid Ed25519 key")
	duelVerifierKey = publicKey
}

const joinWindow int64 = 24*60*60
const runWindow int64 = 24*60*60

type Duel struct {
	ID int64
	Creator address
	Rival address
	Stake int64
	Seed int64
	JoinDeadline int64
	RunDeadline int64
	Joined bool
	CreatorScore *ScoreSubmission
	RivalScore *ScoreSubmission
	SettledAt int64
	Outcome string
	Winner address
	Fee int64
	CreatorCredit int64
	RivalCredit int64
	CreatorClaimed bool
	RivalClaimed bool
}

func CreateDuel(cur realm, rival address, stake int64, reference string) int64 {
	runtime.AssertOriginCall()
	creator := paidCaller(cur, stake)
	require(!paused && duelVerifierKey != "" && firstSeason > 0 && weekID(time.Now().Unix()) >= firstSeason, "duel entries paused or unavailable")
	require(rival.IsValid() && rival != creator, "choose a different pilot")
	require(stake > 0 && stake <= maxCoin/2 && validHex(reference, 32), "invalid stake or reference")
	key := string(creator)+":"+reference
	require(!duelReferences[key], "duel already created")
	id := nextDuelID
	nextDuelID = checkedAdd(id, 1)
	now := time.Now().Unix()
	duels[id] = &Duel{ID: id, Creator: creator, Rival: rival, Stake: stake,
		Seed: seasonSeed(id), JoinDeadline: now+joinWindow}
	duelReferences[key] = true
	pilotDuels[creator] = append(pilotDuels[creator], id)
	pilotDuels[rival] = append(pilotDuels[rival], id)
	return id
}

func JoinDuel(cur realm, id int64) {
	runtime.AssertOriginCall()
	d := mustDuel(id)
	pilot := paidCaller(cur, d.Stake)
	now := time.Now().Unix()
	require(!paused && d.SettledAt == 0 && !d.Joined && now < d.JoinDeadline, "duel closed to deposits")
	require(pilot == d.Rival, "invited rival only")
	d.Joined = true
	d.RunDeadline = now+runWindow
}

func SubmitDuel(cur realm, id, seed int64, version string, score int, digest string, expiry int64, signature string) {
	runtime.AssertOriginCall()
	pilot := paidCaller(cur, 0)
	d := mustDuel(id)
	require(d.Joined && d.SettledAt == 0 && (pilot == d.Creator || pilot == d.Rival), "duel unavailable to this pilot")
	now := time.Now().Unix()
	checkEvidence(now, expiry, d.RunDeadline, d.Seed, seed, version, score, digest)
	message := duelMessage(runtime.ChainID(), cur.PkgPath(), pilot, id, seed, version, score, digest, expiry)
	require(validProof(duelVerifierKey, message, signature), "invalid verifier signature")
	submission := &ScoreSubmission{Seed: seed, Score: score, Digest: digest, Proof: signature, VerifierKey: duelVerifierKey, ExpiresAt: expiry, AcceptedAt: now}
	if pilot == d.Creator {
		require(d.CreatorScore == nil, "creator already submitted")
		d.CreatorScore = submission
	} else {
		require(pilot == d.Rival && d.RivalScore == nil, "rival unavailable or already submitted")
		d.RivalScore = submission
	}
}

func duelMessage(chainID, pkgPath string, pilot address, id, seed int64, version string, score int, digest string, expiry int64) string {
	return strings.Join([]string{"altair-duel-v1", chainID, pkgPath, string(pilot),
		decimal(id), decimal(seed), version, decimal(int64(score)), digest, decimal(expiry)}, "|")
}

func validProof(publicKey, message, signature string) bool {
	if !validHex(publicKey, 64) || !validHex(signature, 128) {
		return false
	}
	key, _ := hex.DecodeString(publicKey)
	proof, _ := hex.DecodeString(signature)
	return ed25519.Verify(key, []byte(message), proof)
}

func SettleDuel(cur realm, id int64) {
	runtime.AssertOriginCall()
	paidCaller(cur, 0)
	now := time.Now().Unix()
	d := mustDuel(id)
	if d.settle(now) && d.Fee > 0 {
		recordRevenue(now, 0, d.Fee)
	}
}

func (d *Duel) settle(now int64) bool {
	if d.SettledAt != 0 {
		return false
	}
	a, b := d.CreatorScore, d.RivalScore
	switch {
	case !d.Joined:
		require(now >= d.JoinDeadline, "rival can still join")
		d.Outcome = "unmatched-refund"
		d.CreatorCredit = d.Stake
	case (a == nil || b == nil) && now < d.RunDeadline:
		panic("pilot can still submit")
	case a == nil && b == nil:
		d.Outcome = "no-show-refund"
		d.CreatorCredit, d.RivalCredit = d.Stake, d.Stake
	case a != nil && b != nil && a.Score == b.Score:
		d.Outcome = "tie-refund"
		d.CreatorCredit, d.RivalCredit = d.Stake, d.Stake
	default:
		pot := checkedAdd(d.Stake, d.Stake)
		d.Fee = pot/10
		d.Outcome = "winner"
		if a == nil || b == nil {
			d.Outcome = "forfeit"
		}
		if a != nil && (b == nil || a.Score > b.Score) {
			d.Winner, d.CreatorCredit = d.Creator, pot-d.Fee
		} else {
			d.Winner, d.RivalCredit = d.Rival, pot-d.Fee
		}
	}
	d.SettledAt = now
	return true
}

func ClaimDuel(cur realm, id int64) int64 {
	runtime.AssertOriginCall()
	pilot := paidCaller(cur, 0)
	d := mustDuel(id)
	amount := d.claim(pilot)
	pay(cur, pilot, amount)
	return amount
}

func (d *Duel) claim(pilot address) int64 {
	require(d.SettledAt > 0, "duel settlement required")
	if pilot == d.Creator {
		if d.CreatorClaimed || d.CreatorCredit == 0 {
			return 0
		}
		d.CreatorClaimed = true
		return d.CreatorCredit
	}
	require(pilot == d.Rival, "participants only")
	if d.RivalClaimed || d.RivalCredit == 0 {
		return 0
	}
	d.RivalClaimed = true
	return d.RivalCredit
}

func mustDuel(id int64) *Duel {
	d := duels[id]
	require(d != nil, "duel not found")
	return d
}

package competition

import (
	"chain/runtime"
	"strings"
	"time"

	"gno.land/p/nt/avl/v0"
)

type ScoreSubmission struct {
	Seed int64
	Score int
	Digest string
	Verifier address
	VerifierKey string
	Proof string
	ExpiresAt int64
	AcceptedAt int64
}

type WeeklyPilot struct {
	Attempts int
	Flights [attemptCap]ScoreSubmission
	Best ScoreSubmission
	Prize int64
	Rank int
	Claimed bool
}

type Season struct {
	ID int64
	Seed int64
	Shares [10]int64
	FinalizedAt int64
	Snapshot int64
	CarryIn int64
	CarryOut int64
	Reserved int64
	Claimed int64
	Revenue RevenueLedger
	pilots map[address]*WeeklyPilot
	ranking *avl.Tree
}

func defaultShares() [10]int64 {
	return [10]int64{3000, 1800, 1300, 1000, 800, 600, 500, 400, 300, 300}
}

func sharesFor(id int64) [10]int64 {
	if shares, exists := seasonRules[id]; exists {
		return shares
	}
	return defaultShares()
}

func newSeason(id int64, shares [10]int64) *Season {
	return &Season{
		ID: id, Seed: seasonSeed(id), Shares: shares,
		pilots: make(map[address]*WeeklyPilot), ranking: avl.NewTree(),
	}
}

func seasonSeed(id int64) int64 {
	return (id%4294967296*1664525 + 1013904223) % 4294967296
}

func getSeason(id int64) *Season {
	if s := seasons[id]; s != nil {
		return s
	}
	s := newSeason(id, sharesFor(id))
	seasons[id] = s
	return s
}

func (s *Season) record(pilot address, submission ScoreSubmission) {
	require(s.FinalizedAt == 0, "season finalized")
	p := s.pilots[pilot]
	if p == nil {
		p = &WeeklyPilot{}
		s.pilots[pilot] = p
	}
	for i := 0; i < p.Attempts; i++ {
		require(p.Flights[i].Digest != submission.Digest, "replay already used")
	}
	require(p.Attempts < attemptCap, "all three flights used")
	p.Flights[p.Attempts] = submission
	p.Attempts++
	if p.Attempts == 1 || submission.Score > p.Best.Score {
		if p.Attempts > 1 {
			s.ranking.Remove(scoreKey(pilot, p.Best))
		}
		p.Best = submission
		s.ranking.Set(scoreKey(pilot, submission), pilot)
	}
}

func scoreKey(pilot address, submission ScoreSubmission) string {
	score := decimal(int64(maxScore-submission.Score))
	timestamp := decimal(submission.AcceptedAt)
	return strings.Repeat("0", 5-len(score)) + score + ":" +
		strings.Repeat("0", 20-len(timestamp)) + timestamp + ":" + string(pilot)
}

func (s *Season) pilotRank(pilot address, p *WeeklyPilot) int {
	key := scoreKey(pilot, p.Best)
	low, high := 0, s.ranking.Size()
	for low < high {
		mid := low+(high-low)/2
		candidate, _ := s.ranking.GetByIndex(mid)
		if candidate < key {
			low = mid+1
		} else {
			high = mid
		}
	}
	return low+1
}

func checkEvidence(now, expiry, deadline, expectedSeed, seed int64, version string, score int, digest string) {
	require(now < deadline && now < expiry && expiry <= deadline, "submission expired")
	require(seed == expectedSeed && version == ruleset, "wrong mission seed or ruleset")
	require(score >= 0 && score <= maxScore && validHex(digest, 64), "invalid score or replay digest")
}

// The verifier's Gno transaction is the signed attestation. The pilot
// authorizes the replay off chain and pays no Gno transaction fees.
func SubmitWeekly(cur realm, pilot address, id, seed int64, version string, score int, digest string, expiry int64) {
	runtime.AssertOriginCall()
	signer := paidCaller(cur, 0)
	require(signer == verifier && pilot.IsValid(), "verified pilot required")
	now := time.Now().Unix()
	require(!paused && firstSeason > 0 && id >= firstSeason && id == weekID(now), "season closed to entries")
	checkEvidence(now, expiry, weekStart(id+1), seasonSeed(id), seed, version, score, digest)
	getSeason(id).record(pilot, ScoreSubmission{Seed: seed, Score: score, Digest: digest, Verifier: signer, ExpiresAt: expiry, AcceptedAt: now})
}

func FinalizeWeek(cur realm, id int64) {
	runtime.AssertOriginCall()
	paidCaller(cur, 0)
	now := time.Now().Unix()
	require(firstSeason > 0 && id >= firstSeason && id < weekID(now), "week is still open")
	if id < nextSnapshot {
		return
	}
	require(id == nextSnapshot, "finalize previous week first")
	s := getSeason(id)
	s.snapshot(now)
	getSeason(id+1).CarryIn = s.CarryOut
	nextSnapshot++
}

func (s *Season) snapshot(now int64) {
	require(s.FinalizedAt == 0, "already finalized")
	s.Snapshot = checkedAdd(s.CarryIn, s.Revenue.Allocation)
	for i := 0; i < len(s.Shares) && i < s.ranking.Size(); i++ {
		_, entry := s.ranking.GetByIndex(i)
		p := s.pilots[entry.(address)]
		p.Rank = i+1
		p.Prize = basisPoints(s.Snapshot, s.Shares[i])
		s.Reserved = checkedAdd(s.Reserved, p.Prize)
	}
	s.CarryOut = s.Snapshot-s.Reserved
	s.FinalizedAt = now
}

func ClaimPrize(cur realm, id int64) int64 {
	runtime.AssertOriginCall()
	pilot := paidCaller(cur, 0)
	s := seasons[id]
	require(s != nil && s.FinalizedAt != 0, "snapshot required")
	amount := s.claim(pilot)
	pay(cur, pilot, amount)
	return amount
}

func (s *Season) claim(pilot address) int64 {
	p := s.pilots[pilot]
	require(p != nil && p.Rank > 0 && p.Prize > 0, "no prize for this address")
	if p.Claimed {
		return 0
	}
	p.Claimed = true
	s.Claimed = checkedAdd(s.Claimed, p.Prize)
	require(s.Claimed <= s.Reserved, "claims exceed snapshot")
	return p.Prize
}

package competition

import (
	"chain/runtime"
	"time"
)

var equipped = make(map[address]int64)

type Cosmetic struct {
	ID int64
	Style string
	Price int64
	StartsAt int64
	EndsAt int64
	Enabled bool
}

type Purchase struct {
	Buyer address
	Item int64
	Amount int64
	Denom string
	PurchasedAt int64
}

type RevenueLedger struct {
	Shop int64
	DuelFees int64
	Deductions int64
	Realized int64
	Allocation int64
	Retained int64
}

func ListCosmetic(cur realm, style string, price, startsAt, endsAt int64) int64 {
	runtime.AssertOriginCall()
	requireAdmin(cur)
	require(firstSeason > 0 && startsAt >= weekStart(firstSeason) && startsAt > time.Now().Unix() &&
		endsAt > startsAt && price > 0, "invalid cosmetic schedule or price")
	require(style == "azure" || style == "ember" || style == "frost", "unknown presentation-only livery")
	id := nextCosmeticID
	nextCosmeticID = checkedAdd(id, 1)
	catalog[id] = &Cosmetic{ID: id, Style: style, Price: price, StartsAt: startsAt, EndsAt: endsAt, Enabled: true}
	return id
}

func DisableCosmetic(cur realm, id int64) {
	runtime.AssertOriginCall()
	requireAdmin(cur)
	item := catalog[id]
	require(item != nil, "cosmetic not found")
	item.Enabled = false
}

func BuyCosmetic(cur realm, id int64) {
	runtime.AssertOriginCall()
	item := catalog[id]
	require(item != nil, "cosmetic not found")
	buyer := paidCaller(cur, item.Price)
	now := time.Now().Unix()
	require(!paused && item.available(now), "cosmetic unavailable")
	key := purchaseKey(buyer, id)
	// Rejection rolls back the incoming coin transfer, even after a lost client response.
	require(purchases[key] == nil, "cosmetic already owned")
	purchases[key] = &Purchase{Buyer: buyer, Item: id, Amount: item.Price, Denom: denom, PurchasedAt: now}
	recordRevenue(now, item.Price, 0)
}

func EquipCosmetic(cur realm, id int64) {
	runtime.AssertOriginCall()
	pilot := paidCaller(cur, 0)
	require(id == 0 || purchases[purchaseKey(pilot, id)] != nil, "cosmetic is not owned")
	equipped[pilot] = id
}

func (item *Cosmetic) available(now int64) bool {
	return item.Enabled && now >= item.StartsAt && now < item.EndsAt
}

func purchaseKey(pilot address, id int64) string {
	return string(pilot)+":"+decimal(id)
}

func recordRevenue(now, sale, fee int64) {
	id := weekID(now)
	require(firstSeason > 0 && id >= firstSeason && id >= nextSnapshot, "revenue week unavailable")
	ledger := &getSeason(id).Revenue
	previous := ledger.Retained
	ledger.record(sale, fee)
	retainedClaimable = checkedAdd(retainedClaimable, ledger.Retained-previous)
}

func (ledger *RevenueLedger) record(sale, fee int64) {
	ledger.Shop = checkedAdd(ledger.Shop, sale)
	ledger.DuelFees = checkedAdd(ledger.DuelFees, fee)
	ledger.Realized = checkedAdd(ledger.Shop, ledger.DuelFees)-ledger.Deductions
	ledger.Allocation = ledger.Realized/2
	ledger.Retained = ledger.Realized-ledger.Allocation
}

package competition

import (
	"strconv"
	"strings"
	"time"
)

const pageSize = 20

// Render emits bounded, pipe-delimited records for the Altair browser.
func Render(path string) string {
	require(len(path) < 150, "view path too long")
	parts := strings.Split(strings.Trim(path, "/"), "/")
	if len(parts) == 1 && parts[0] == "" {
		return "# Altair\n\nStrait Run weekly league and native ugnot economy.\n"
	}
	now := time.Now().Unix()
	switch parts[0] {
	case "status":
		require(len(parts) == 1, "invalid status path")
		return row("status", decimal(now), decimal(weekID(now)), decimal(firstSeason), decimal(nextSnapshot), strconv.FormatBool(paused), ruleset, denom, duelVerifierKey,
			string(verifier), string(treasury), decimal(retainedClaimable))
	case "weekly":
		require(len(parts) == 4, "invalid weekly path")
		return renderWeekly(viewID(parts[1]), viewOffset(parts[2]), parts[3])
	case "duel":
		require(len(parts) == 2, "invalid duel path")
		if d := duels[viewID(parts[1])]; d != nil {
			return renderDuel(d)
		}
	case "duels":
		require(len(parts) == 3, "invalid duel history path")
		pilot := viewPilot(parts[1])
		ids := pilotDuels[pilot]
		start := viewOffset(parts[2])
		var result string
		for i := start; i < len(ids) && i-start < pageSize; i++ {
			result += renderDuel(duels[ids[len(ids)-1-i]])
		}
		return result
	case "livery":
		require(len(parts) == 2, "invalid livery path")
		pilot := viewPilot(parts[1])
		if item := catalog[equipped[pilot]]; item != nil {
			return row("livery", decimal(item.ID), item.Style)
		}
	case "shop":
		require(len(parts) == 3, "invalid shop path")
		return renderShop(viewOffset(parts[1]), viewPilot(parts[2]), now)
	default:
		panic("unknown Altair view")
	}
	return ""
}

func renderWeekly(id int64, offset int, pilot string) string {
	if firstSeason == 0 || id < firstSeason || id > weekID(time.Now().Unix())+52 {
		return ""
	}
	s := seasons[id]
	if s == nil {
		s = newSeason(id, sharesFor(id))
	}
	revenue := s.Revenue
	carryPending := id > nextSnapshot
	projectedPool := checkedAdd(s.CarryIn, revenue.Allocation)
	var result = row("weekly", decimal(id), decimal(weekStart(id)), decimal(weekStart(id+1)), decimal(s.Seed),
		decimal(s.FinalizedAt), decimal(projectedPool), decimal(s.Snapshot), decimal(s.CarryIn), decimal(s.CarryOut),
		decimal(revenue.Shop), decimal(revenue.DuelFees), decimal(revenue.Deductions), decimal(revenue.Realized),
		decimal(revenue.Allocation), decimal(revenue.Retained), decimal(s.Reserved), decimal(s.Claimed),
		decimal(int64(s.ranking.Size())), strconv.FormatBool(carryPending))
	for i, share := range s.Shares {
		result += row("share", decimal(int64(i+1)), decimal(share))
	}
	for i := offset; i < s.ranking.Size() && i-offset < pageSize; i++ {
		_, entry := s.ranking.GetByIndex(i)
		owner := entry.(address)
		result += renderPilot(s.pilots[owner], owner, "pilot", i+1)
	}
	owner := viewPilot(pilot)
	if p := s.pilots[owner]; p != nil {
		result += renderPilot(p, owner, "self", s.pilotRank(owner, p))
	}
	return result
}

func renderPilot(p *WeeklyPilot, owner address, kind string, rank int) string {
	if p.Rank > 0 {
		rank = p.Rank
	}
	result := row(kind, string(owner), decimal(int64(rank)), decimal(int64(p.Attempts)), decimal(int64(p.Best.Score)),
		decimal(p.Best.AcceptedAt), decimal(p.Prize), strconv.FormatBool(p.Claimed))
	if kind == "pilot" {
		return result
	}
	for i := 0; i < p.Attempts; i++ {
		result += renderScore("flight", string(owner), p.Flights[i])
	}
	return result
}

func renderScore(kind, owner string, score ScoreSubmission) string {
	return row(kind, owner, decimal(score.Seed), decimal(int64(score.Score)), score.Digest,
		string(score.Verifier), decimal(score.ExpiresAt), decimal(score.AcceptedAt), score.VerifierKey, score.Proof)
}

func renderDuel(d *Duel) string {
	result := row("duel", decimal(d.ID), string(d.Creator), string(d.Rival), decimal(d.Stake), decimal(d.Seed),
		decimal(d.JoinDeadline), decimal(d.RunDeadline), strconv.FormatBool(d.Joined), decimal(d.SettledAt),
		d.Outcome, string(d.Winner), decimal(d.Fee), decimal(d.CreatorCredit), decimal(d.RivalCredit),
		strconv.FormatBool(d.CreatorClaimed), strconv.FormatBool(d.RivalClaimed))
	if d.CreatorScore != nil {
		result += renderScore("duel-flight", string(d.Creator), *d.CreatorScore)
	}
	if d.RivalScore != nil {
		result += renderScore("duel-flight", string(d.Rival), *d.RivalScore)
	}
	return result
}

func renderShop(offset int, pilot address, now int64) string {
	var result string
	for i := int64(offset)+1; i < nextCosmeticID && i-int64(offset) <= pageSize; i++ {
		item := catalog[i]
		result += row("item", decimal(item.ID), item.Style, decimal(item.Price), decimal(item.StartsAt),
			decimal(item.EndsAt), strconv.FormatBool(item.available(now)), strconv.FormatBool(equipped[pilot] == i))
		if p := purchases[purchaseKey(pilot, i)]; p != nil {
			result += row("purchase", decimal(i), string(p.Buyer), decimal(p.Amount), p.Denom, decimal(p.PurchasedAt))
		}
	}
	return result
}

func viewPilot(raw string) address {
	if raw == "-" {
		return ""
	}
	pilot := address(raw)
	require(pilot.IsValid(), "invalid pilot address")
	return pilot
}

func viewID(raw string) int64 {
	id, err := strconv.ParseInt(raw, 10, 64)
	require(err == nil && id > 0, "invalid record id")
	return id
}

func viewOffset(raw string) int {
	offset, err := strconv.ParseInt(raw, 10, 32)
	require(err == nil && offset >= 0, "invalid page offset")
	return int(offset)
}

func row(fields ...string) string {
	return strings.Join(fields, "|")+"\n"
}

package whisper

import (
	"crypto/sha256"
	"encoding/binary"
	"errors"

	"gno.land/p/g1jkstuy23a8e44jvdjajc5gjjry9vwevmkvmdak/assurance/v2"
)

const (
	DomainAgentBus = "arobi-whisper-agent-bus-v1"

	// Standard cross-shell / cross-environment / cross-harness message kinds.
	AgentKindTaskDispatch    = "task_dispatch"
	AgentKindWarrantDelegate = "warrant_delegate"
	AgentKindEvidenceReceipt = "evidence_receipt"
	AgentKindStatusReply     = "status_reply"
	AgentKindHandoff         = "handoff"
	AgentKindHaltSignal      = "halt_signal"
	AgentKindCapabilityLease = "capability_lease"
	AgentKindMemorySync      = "memory_sync"
	AgentKindPeerClaim       = "peer_claim"
	AgentKindPeerHandoff     = "peer_handoff"
	AgentKindPeerDone        = "peer_done"
	AgentKindPeerHalt        = "peer_halt"
)

// AgentBusRoute describes the authenticated routing metadata for an encrypted cross-shell,
// cross-environment, or cross-harness agent/Familiar packet carried inside a Whisper SealedEnvelope.
// Plaintext prompts, code, and secrets stay encrypted inside SealedEnvelope.CiphertextB64.
type AgentBusRoute struct {
	FromHarness           string // e.g. "ullumii", "gnosh.ai", "shell", "mcp", "gno-realm", "local-llm"
	FromEnv               string // e.g. "linux-docker", "windows-pwsh", "wsl", "cloud-worker"
	FromAgentID           string
	ToHarness             string
	ToEnv                 string
	ToAgentID             string
	Kind                  string // AgentKind*
	CorrelationID         string
	ParentWarrantDigest   string // optional 64-hex digest linking to gno.land/p/g1jkstuy23a8e44jvdjajc5gjjry9vwevmkvmdak/assurance/v2
	EvidenceRootHex       string // optional 64-hex RFC 6962 accumulator root
	CapabilityDigestHex   string // optional 64-hex Familiar CapabilityToken digest
	MemoryRecallDigestHex string // optional 64-hex MemoryRecallProof digest
}

// Validate checks routing metadata fields before hashing or sealing.
func (r AgentBusRoute) Validate() error {
	if r.FromHarness == "" || r.FromAgentID == "" {
		return errors.New("fromHarness and fromAgentID are required")
	}
	if r.ToHarness == "" || r.ToAgentID == "" {
		return errors.New("toHarness and toAgentID are required")
	}
	switch r.Kind {
	case AgentKindTaskDispatch, AgentKindWarrantDelegate, AgentKindEvidenceReceipt,
		AgentKindStatusReply, AgentKindHandoff, AgentKindHaltSignal,
		AgentKindCapabilityLease, AgentKindMemorySync,
		AgentKindPeerClaim, AgentKindPeerHandoff, AgentKindPeerDone, AgentKindPeerHalt:
	default:
		return errors.New("unsupported agent bus message kind: " + r.Kind)
	}
	if r.CorrelationID == "" || len(r.CorrelationID) > 64 {
		return errors.New("correlationID must be 1..64 characters")
	}
	if r.ParentWarrantDigest != "" {
		if _, err := assurance.ParseDigest(r.ParentWarrantDigest); err != nil {
			return errors.New("parentWarrantDigest: " + err.Error())
		}
	}
	if r.EvidenceRootHex != "" {
		if _, err := assurance.ParseDigest(r.EvidenceRootHex); err != nil {
			return errors.New("evidenceRootHex: " + err.Error())
		}
	}
	if r.CapabilityDigestHex != "" {
		if _, err := assurance.ParseDigest(r.CapabilityDigestHex); err != nil {
			return errors.New("capabilityDigestHex: " + err.Error())
		}
	}
	if r.MemoryRecallDigestHex != "" {
		if _, err := assurance.ParseDigest(r.MemoryRecallDigestHex); err != nil {
			return errors.New("memoryRecallDigestHex: " + err.Error())
		}
	}
	return nil
}

// Encode serializes AgentBusRoute into canonical length-prefixed big-endian bytes.
func (r AgentBusRoute) Encode() []byte {
	out := make([]byte, 0, 256)
	out = appendStr(out, DomainAgentBus)
	out = append(out, EncodingVersion)
	out = appendStr(out, r.FromHarness)
	out = appendStr(out, r.FromEnv)
	out = appendStr(out, r.FromAgentID)
	out = appendStr(out, r.ToHarness)
	out = appendStr(out, r.ToEnv)
	out = appendStr(out, r.ToAgentID)
	out = appendStr(out, r.Kind)
	out = appendStr(out, r.CorrelationID)
	out = appendStr(out, r.ParentWarrantDigest)
	out = appendStr(out, r.EvidenceRootHex)
	out = appendStr(out, r.CapabilityDigestHex)
	out = appendStr(out, r.MemoryRecallDigestHex)
	return out
}

// Digest returns SHA-256(Encode()) for binding route metadata to encrypted envelopes.
func (r AgentBusRoute) Digest() [32]byte {
	return sha256.Sum256(r.Encode())
}

// LeafHash returns the RFC 6962 leaf hash of this cross-harness route commitment.
func (r AgentBusRoute) LeafHash() [32]byte {
	return assurance.LeafHash(r.Encode())
}

// BindAgentEnvelopeCommitment computes SHA-256(routeDigest || payloadCommitment) so both
// the encrypted ciphertext and the cross-harness route metadata are tamper-evident together.
func BindAgentEnvelopeCommitment(route AgentBusRoute, payloadCommitmentHex string) (string, error) {
	if err := route.Validate(); err != nil {
		return "", err
	}
	pDig, err := assurance.ParseDigest(payloadCommitmentHex)
	if err != nil {
		return "", err
	}
	rDig := route.Digest()
	buf := make([]byte, 0, 8+64)
	buf = binary.BigEndian.AppendUint32(buf, 64)
	buf = append(buf, rDig[:]...)
	buf = append(buf, pDig[:]...)
	return assurance.Hex(sha256.Sum256(buf)), nil
}

// Package whisper defines the canonical E2E-encrypted envelope, handle validation,
// and DeFi escrow evidence primitives for Arobi Whisper.
//
// Wire-compatible with live Arobi Whisper (aura-genesis.org/whisper):
//   - Client generates local X25519 (encryption) + Ed25519 (optional signing) keypairs.
//   - Each message is sealed client-side with an ephemeral X25519 key + HKDF-SHA256
//     (domain "arobi-whisper-x25519-xchacha-v1") + XChaCha20-Poly1305 (24-byte nonce).
//   - Commitment = SHA-256(ciphertext_bytes || ephemeralPk_bytes || nonce_bytes).
//   - Only ciphertext, ephemeral public key, nonce, and commitment ever touch chain state.
//
// Built on gno.land/p/g1jkstuy23a8e44jvdjajc5gjjry9vwevmkvmdak/assurance/v2 for RFC 6962 / RFC 9162 Merkle evidence anchoring.
package whisper

import (
	"crypto/sha256"
	"encoding/base64"
	"encoding/binary"
	"errors"
	"strings"

	"gno.land/p/g1jkstuy23a8e44jvdjajc5gjjry9vwevmkvmdak/assurance/v2"
)

const (
	EncodingVersion uint8 = 1
	DomainEnvelope        = "arobi-whisper-gno-envelope-v1"
	// v2 (2026-11-24): the escrow record encodes FeeBps, the fee fixed when it opens (PROTOCOL.md).
	DomainEscrow          = "arobi-whisper-gno-escrow-v2"

	// MaxCiphertextB64Len bounds on-chain encrypted payload size (16 KiB base64 ~ 12 KiB ciphertext).
	MaxCiphertextB64Len = 16384
)

// EscrowStatus tracks the lifecycle of a conditional DeFi escrow attached to an encrypted message.
type EscrowStatus string

const (
	EscrowOpen     EscrowStatus = "OPEN"
	EscrowClaimed  EscrowStatus = "CLAIMED"
	EscrowRefunded EscrowStatus = "REFUNDED"
)

var reservedHandles = map[string]bool{
	"arobi": true, "admin": true, "administrator": true, "support": true,
	"help": true, "security": true, "root": true, "system": true,
	"official": true, "whisper": true, "aura": true, "arobiteam": true,
	"moderator": true, "mod": true, "staff": true, "billing": true,
	"payments": true, "noreply": true, "ullumii": true, "treasury": true,
	"gaetano": true, "possumxi": true, "gno": true, "gnoland": true,
	"jaekwon": true,
}

// ValidateKeyHex validates a 32-byte (64 lowercase hex char) X25519 or Ed25519 public key.
func ValidateKeyHex(s string) error {
	_, err := assurance.ParseDigest(s)
	if err != nil {
		return errors.New("public key must be 64 lowercase hexadecimal characters (32 bytes)")
	}
	return nil
}

// ValidateNonceHex validates a 24-byte (48 lowercase hex char) XChaCha20-Poly1305 nonce.
func ValidateNonceHex(s string) error {
	if len(s) != 48 {
		return errors.New("nonce must be 48 lowercase hexadecimal characters (24 bytes)")
	}
	for i := 0; i < len(s); i++ {
		c := s[i]
		if !((c >= '0' && c <= '9') || (c >= 'a' && c <= 'f')) {
			return errors.New("nonce must be 48 lowercase hexadecimal characters (24 bytes)")
		}
	}
	return nil
}

// ValidateCiphertextB64 verifies non-empty, bounded, canonical Base64 ciphertext.
func ValidateCiphertextB64(s string) error {
	if len(s) == 0 || len(s) > MaxCiphertextB64Len {
		return errors.New("ciphertext base64 length out of range (1..16384)")
	}
	if len(s)%4 != 0 {
		return errors.New("ciphertext must be canonical padded base64")
	}
	raw, err := base64.StdEncoding.DecodeString(s)
	if err != nil || len(raw) < 17 {
		// XChaCha20-Poly1305 carries a 16-byte Poly1305 auth tag + >= 1 byte plaintext.
		return errors.New("invalid ciphertext base64 or shorter than 16-byte AEAD tag")
	}
	if base64.StdEncoding.EncodeToString(raw) != s {
		return errors.New("ciphertext is not canonical base64")
	}
	return nil
}

// NormalizeHandle validates and normalizes a Whisper handle (3..20 lowercase a-z0-9_, no __).
func NormalizeHandle(raw string) (string, error) {
	u := strings.ToLower(strings.TrimSpace(raw))
	u = strings.TrimLeft(u, "@")
	if len(u) < 3 || len(u) > 20 {
		return "", errors.New("handle must be 3..20 characters")
	}
	if u[0] == '_' || u[len(u)-1] == '_' || strings.Contains(u, "__") {
		return "", errors.New("handle cannot start/end with underscore or contain double underscores")
	}
	for i := 0; i < len(u); i++ {
		c := u[i]
		ok := (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '_'
		if !ok {
			return "", errors.New("handle may only contain lowercase letters, digits, and single underscores")
		}
	}
	if reservedHandles[u] {
		return "", errors.New("handle is reserved: " + u)
	}
	return u, nil
}

// SealedEnvelope is one end-to-end encrypted message stored on-chain (ciphertext only).
type SealedEnvelope struct {
	ID              uint64
	ChainID         string
	Realm           string
	From            string
	To              string
	EphemeralPubHex string
	NonceHex        string
	CiphertextB64   string
	CommitmentHex   string
	TipUgnot        int64
	EscrowID        uint64
	Height          int64
	LeafIndex       uint64
}

// Encode serializes SealedEnvelope into canonical length-prefixed big-endian bytes.
func (e SealedEnvelope) Encode() []byte {
	out := make([]byte, 0, 256)
	out = appendStr(out, DomainEnvelope)
	out = append(out, EncodingVersion)
	out = binary.BigEndian.AppendUint64(out, e.ID)
	out = appendStr(out, e.ChainID)
	out = appendStr(out, e.Realm)
	out = appendStr(out, e.From)
	out = appendStr(out, e.To)
	out = appendStr(out, e.EphemeralPubHex)
	out = appendStr(out, e.NonceHex)
	ctHash := sha256.Sum256([]byte(e.CiphertextB64))
	out = append(out, ctHash[:]...)
	out = appendStr(out, e.CommitmentHex)
	out = binary.BigEndian.AppendUint64(out, uint64(e.TipUgnot))
	out = binary.BigEndian.AppendUint64(out, e.EscrowID)
	out = binary.BigEndian.AppendUint64(out, uint64(e.Height))
	return out
}

// LeafHash returns the RFC 6962 leaf hash via gno.land/p/g1jkstuy23a8e44jvdjajc5gjjry9vwevmkvmdak/assurance/v2.
func (e SealedEnvelope) LeafHash() [32]byte {
	return assurance.LeafHash(e.Encode())
}

// EscrowRecord represents a conditional GNOT escrow attached to an encrypted Whisper message.
type EscrowRecord struct {
	ID            uint64
	MessageID     uint64
	Sender        string
	Recipient     string
	AmountUgnot   int64
	FeeBps        int64  // settlement fee locked at creation time (unaffected by later SetPricing)
	HashLockHex   string // empty = open recipient claim; 64-hex = SHA-256(preimage) HTLC
	ExpiryHeight  int64
	Status        EscrowStatus
	CreatedHeight int64
	SettledHeight int64
}

// Encode serializes EscrowRecord state for RFC 6962 evidence anchoring.
func (r EscrowRecord) Encode() []byte {
	out := make([]byte, 0, 232)
	out = appendStr(out, DomainEscrow)
	out = append(out, EncodingVersion)
	out = binary.BigEndian.AppendUint64(out, r.ID)
	out = binary.BigEndian.AppendUint64(out, r.MessageID)
	out = appendStr(out, r.Sender)
	out = appendStr(out, r.Recipient)
	out = binary.BigEndian.AppendUint64(out, uint64(r.AmountUgnot))
	out = binary.BigEndian.AppendUint64(out, uint64(r.FeeBps))
	out = appendStr(out, r.HashLockHex)
	out = binary.BigEndian.AppendUint64(out, uint64(r.ExpiryHeight))
	out = appendStr(out, string(r.Status))
	out = binary.BigEndian.AppendUint64(out, uint64(r.CreatedHeight))
	out = binary.BigEndian.AppendUint64(out, uint64(r.SettledHeight))
	return out
}

// LeafHash returns the RFC 6962 leaf hash via gno.land/p/g1jkstuy23a8e44jvdjajc5gjjry9vwevmkvmdak/assurance/v2.
func (r EscrowRecord) LeafHash() [32]byte {
	return assurance.LeafHash(r.Encode())
}

// ComputeHashLock computes SHA-256(preimage) as 64 lowercase hex characters for HTLC escrows.
func ComputeHashLock(preimage string) string {
	return assurance.Hex(assurance.HashString(preimage))
}

func appendStr(out []byte, s string) []byte {
	out = binary.BigEndian.AppendUint32(out, uint32(len(s)))
	return append(out, []byte(s)...)
}

package whisper

import (
	"strconv"
