// Render serves the gnoweb explorer for Arobi Whisper.
//
// Routes:
//   /                      Directory, global RFC 6962 commitment root, escrow stats
//   /u/<handle-or-addr>    Public X25519 keycard & inbox policy
//   /inbox/<handle-or-addr> Public encrypted envelopes & commitments (zero plaintext)
//   /escrow/<id>           DeFi conditional escrow status & settlement audit
func Render(path string) string {
	clean := strings.Trim(path, "/")
	if clean == "" {
		return renderHome()
	}
	if strings.HasPrefix(clean, "u/") {
		return renderUser(strings.TrimPrefix(clean, "u/"))
	}
	if strings.HasPrefix(clean, "inbox/") {
		return renderInbox(strings.TrimPrefix(clean, "inbox/"))
	}
	if strings.HasPrefix(clean, "escrow/") {
		return renderEscrow(strings.TrimPrefix(clean, "escrow/"))
	}
	return "# Not Found\n\nUnknown path `" + clean + "`.\n\n[Back to Arobi Whisper](/r/g1jkstuy23a8e44jvdjajc5gjjry9vwevmkvmdak/whisper/v2)"
}

func renderHome() string {
	var b strings.Builder
	b.WriteString("# Arobi Whisper — End-to-End Encrypted DeFi Chat\n\n")
	b.WriteString("Client-side `X25519 + HKDF-SHA256 + XChaCha20-Poly1305` sealed boxes paired with native GNOT ")
	b.WriteString("tipping, hash-locked DeFi escrows, programmable anti-spam inbox policies, and RFC 6962 ")
	b.WriteString("evidence proofs powered by `gno.land/p/g1jkstuy23a8e44jvdjajc5gjjry9vwevmkvmdak/assurance/v2`. Plaintext never touches chain state.\n\n")

	b.WriteString("| Metric | Value |\n| --- | --- |\n")
	b.WriteString("| Free Tier | `" + strconv.FormatInt(FreePeriodCredits, 10) + "` credits, `4 KiB` max ciphertext |\n")
	b.WriteString("| Pro Subscription (30 days) | `" + strconv.FormatInt(subscriptionPriceUgnot, 10) + "ugnot` (`" + strconv.FormatInt(ProPeriodCredits, 10) + "` credits, `16 KiB` ciphertext, DeFi HTLC escrows) |\n")
	b.WriteString("| Overage / Escrow Settlement Fee | `" + strconv.FormatInt(overageFeeUgnot, 10) + "ugnot` per overage msg · `" + strconv.FormatInt(escrowFeeBps, 10) + " bps` on claimed escrows |\n")
	b.WriteString("| Registered Identities | " + strconv.FormatUint(identityCount, 10) + " |\n")
	b.WriteString("| Encrypted Messages | " + strconv.FormatUint(messageCount, 10) + " |\n")
	b.WriteString("| DeFi Escrows Created | " + strconv.FormatUint(escrowCount, 10) + " |\n")
	b.WriteString("| Total Direct Tips | `" + strconv.FormatInt(totalTips, 10) + "ugnot` |\n")
	b.WriteString("| Total Escrowed Volume | `" + strconv.FormatInt(totalEscrowed, 10) + "ugnot` |\n")
	b.WriteString("| Evidence Accumulator Leaves | " + strconv.FormatUint(evidenceAcc.Size(), 10) + " |\n")
	b.WriteString("| Global RFC 6962 Root | `" + assurance.Hex(evidenceAcc.Root()) + "` |\n\n")

	b.WriteString("## Public X25519 Key Directory\n\n")
	if identityCount == 0 {
		b.WriteString("_No identities registered yet. Call `RegisterIdentity` to publish your X25519 public key._\n")
		return b.String()
	}

	b.WriteString("| Handle | Address | Min Tip | Allowlist | Inbox | Keycard |\n")
	b.WriteString("| --- | --- | ---: | --- | ---: | --- |\n")
	// The latest 20, newest first: a page stays the same size however many identities exist. Every
	// identity also has its own keycard page at :u/<handle or address>.
	var latest []string
	identitySeq.ReverseIterate("", "", func(_ string, v any) bool {
		latest = append(latest, v.(string))
		return len(latest) >= 20
	})
	for _, addr := range latest {
		id, ok := identities.Get(addr).(*Identity)
		if !ok || id == nil {
			continue
		}
		hLabel := "_none_"
		linkKey := id.Address.String()
		if id.Handle != "" {
			hLabel = "@" + id.Handle
			linkKey = id.Handle
		}
		b.WriteString("| " + hLabel + " | `" + id.Address.String() + "` | `" +
			strconv.FormatInt(id.MinTipUgnot, 10) + "ugnot` | `" +
			strconv.FormatBool(id.AllowListOnly) + "` | " +
			"[View (" + strconv.FormatUint(id.InboxCount, 10) + ")](/r/g1jkstuy23a8e44jvdjajc5gjjry9vwevmkvmdak/whisper/v2:inbox/" + linkKey + ") | " +
			"[Keycard](/r/g1jkstuy23a8e44jvdjajc5gjjry9vwevmkvmdak/whisper/v2:u/" + linkKey + ") |\n")
	}
	return b.String()
}

func renderUser(q string) string {
	id, ok := tryResolveIdentity(q)
	if !ok {
		return "# Identity Not Found\n\nNo Whisper identity for `" + q + "`.\n\n[Back](/r/g1jkstuy23a8e44jvdjajc5gjjry9vwevmkvmdak/whisper/v2)"
	}
	var b strings.Builder
	title := id.Address.String()
	if id.Handle != "" {
		title = "@" + id.Handle + " (`" + id.Address.String() + "`)"
	}
	b.WriteString("# Whisper Keycard: " + title + "\n\n")
	if id.DisplayName != "" {
		b.WriteString("- **Display Name:** " + id.DisplayName + "\n")
	}
	b.WriteString("- **X25519 Encryption Public Key:** `" + id.EncPubHex + "`\n")
	if id.SignPubHex != "" {
		b.WriteString("- **Ed25519 Signing Public Key:** `" + id.SignPubHex + "`\n")
	}
	b.WriteString("- **Minimum Anti-Spam Tip:** `" + strconv.FormatInt(id.MinTipUgnot, 10) + "ugnot`\n")
	b.WriteString("- **Allowlist Only:** `" + strconv.FormatBool(id.AllowListOnly) + "`\n")
	b.WriteString("- **Messages Received:** `" + strconv.FormatUint(id.InboxCount, 10) + "` | **Sent:** `" + strconv.FormatUint(id.SentCount, 10) + "`\n\n")
	linkKey := id.Address.String()
	if id.Handle != "" {
		linkKey = id.Handle
	}
	b.WriteString("[Inspect Encrypted Inbox](/r/g1jkstuy23a8e44jvdjajc5gjjry9vwevmkvmdak/whisper/v2:inbox/" + linkKey + ") · [Back to Directory](/r/g1jkstuy23a8e44jvdjajc5gjjry9vwevmkvmdak/whisper/v2)\n")
	return b.String()
}

func renderInbox(q string) string {
	id, ok := tryResolveIdentity(q)
	if !ok {
		return "# Inbox Not Found\n\nNo Whisper inbox for `" + q + "`.\n\n[Back](/r/g1jkstuy23a8e44jvdjajc5gjjry9vwevmkvmdak/whisper/v2)"
	}
	var b strings.Builder
	b.WriteString("# Encrypted Inbox: `" + id.Address.String() + "`\n\n")
	b.WriteString("_All payloads below are client-sealed `XChaCha20-Poly1305` ciphertexts. Only the holder of the matching local X25519 secret key can decrypt them._\n\n")
	if id.InboxCount == 0 {
		b.WriteString("_Inbox is empty._\n\n[Back](/r/g1jkstuy23a8e44jvdjajc5gjjry9vwevmkvmdak/whisper/v2)")
		return b.String()
	}
	var recent []uint64
	id.Inbox.ReverseIterate("", "", func(_ string, v any) bool {
		recent = append(recent, v.(uint64))
		return len(recent) >= 20
	})
	for _, msgID := range recent {
		env := messages.Get(seqKey(msgID)).(*pw.SealedEnvelope)
		b.WriteString("- **Msg #" + strconv.FormatUint(env.ID, 10) + "** from `" + env.From +
			"` at height `" + strconv.FormatInt(env.Height, 10) + "` | commitment `" +
			env.CommitmentHex[:16] + "...` | tip `" + strconv.FormatInt(env.TipUgnot, 10) + "ugnot`")
		if env.EscrowID > 0 {
			eid := strconv.FormatUint(env.EscrowID, 10)
			b.WriteString(" | [Escrow #" + eid + "](/r/g1jkstuy23a8e44jvdjajc5gjjry9vwevmkvmdak/whisper/v2:escrow/" + eid + ")")
		}
		b.WriteString("\n")
	}
	b.WriteString("\n[Back to Directory](/r/g1jkstuy23a8e44jvdjajc5gjjry9vwevmkvmdak/whisper/v2)\n")
	return b.String()
}

func renderEscrow(idStr string) string {
	id, err := strconv.ParseUint(idStr, 10, 64)
	if err != nil || id == 0 || id > escrowCount {
		return "# Escrow Not Found\n\nInvalid escrow id `" + idStr + "`.\n\n[Back](/r/g1jkstuy23a8e44jvdjajc5gjjry9vwevmkvmdak/whisper/v2)"
	}
	e := escrows.Get(seqKey(id)).(*pw.EscrowRecord)
	var b strings.Builder
	b.WriteString("# Whisper DeFi Escrow #" + idStr + "\n\n")
	b.WriteString("- **Status:** `" + string(e.Status) + "`\n")
	b.WriteString("- **Linked Encrypted Message:** `#" + strconv.FormatUint(e.MessageID, 10) + "`\n")
	b.WriteString("- **Sender:** `" + e.Sender + "`\n")
	b.WriteString("- **Recipient:** `" + e.Recipient + "`\n")
	b.WriteString("- **Locked Amount:** `" + strconv.FormatInt(e.AmountUgnot, 10) + "ugnot`\n")
	if e.HashLockHex != "" {
		b.WriteString("- **HTLC Hashlock (SHA-256):** `" + e.HashLockHex + "`\n")
	} else {
		b.WriteString("- **HTLC Hashlock:** _none (recipient direct claim)_\n")
	}
	b.WriteString("- **Expiry Height:** `" + strconv.FormatInt(e.ExpiryHeight, 10) + "`\n")
	if e.SettledHeight > 0 {
		b.WriteString("- **Settled Height:** `" + strconv.FormatInt(e.SettledHeight, 10) + "`\n")
	}
	b.WriteString("\n[Back to Directory](/r/g1jkstuy23a8e44jvdjajc5gjjry9vwevmkvmdak/whisper/v2)\n")
	return b.String()
}

func tryResolveIdentity(q string) (*Identity, bool) {
	trim := strings.TrimSpace(q)
	if id, ok := identities.Get(trim).(*Identity); ok && id != nil {
		return id, true
	}
	clean := strings.ToLower(strings.TrimLeft(trim, "@"))
	if addr, ok := handles.Get(clean).(string); ok && addr != "" {
		if id, ok2 := identities.Get(addr).(*Identity); ok2 && id != nil {
			return id, true
		}
	}
	return nil, false
}

// Package whisper is the stateful Gno.land realm for Arobi Whisper — an end-to-end
// encrypted DeFi messenger with tiered subscriptions paid in GNOT (mirroring
// aura-genesis.org/whisper: Free 110 credits vs Pro 2,500 credits / 30 days),
// pay-per-message overage, native GNOT tipping, conditional HTLC/expiry escrows,
// programmable anti-spam inbox gating, and RFC 6962 cryptographic evidence proofs
// built directly on gno.land/p/g1jkstuy23a8e44jvdjajc5gjjry9vwevmkvmdak/assurance/v2.
//
// Zero plaintext or secret keys ever touch chain state. Clients seal messages locally
// using X25519 + HKDF-SHA256 + XChaCha20-Poly1305 (exact Arobi Whisper v1 wire format).
// Note: on a public chain, sender/recipient addresses, timestamps, tips, escrow amounts,
// and realm state (including operator/settlement sink) are publicly observable metadata;
// E2EE protects message plaintext only.
//
// Settlement: subscription and protocol fees are enforced on-chain in GNOT. The deployer
// becomes operator atomically inside init() during deployment (no post-deploy claim race).
// No payout address is hardcoded, printed in Render, or emitted in events.
package whisper

import (
	"chain"
	"chain/banker"
	"chain/runtime"
	"chain/runtime/unsafe"
	"strconv"
	"strings"

	"gno.land/p/g1jkstuy23a8e44jvdjajc5gjjry9vwevmkvmdak/assurance/v2"
	pw "gno.land/p/g1jkstuy23a8e44jvdjajc5gjjry9vwevmkvmdak/whisper/v2"
	"gno.land/p/nt/avl/v0"
)

const (
	denom = "ugnot"

	// Tier quotas mirroring live Arobi Whisper (aura-genesis.org/whisper).
	TierFree = "free"
	TierPro  = "pro"

	FreePeriodCredits int64 = 110
	ProPeriodCredits  int64 = 2500
	FreeMaxCipherB64  int   = 4096  // 4 KiB base64 on Free tier
	ProMaxCipherB64   int   = 16384 // 16 KiB base64 on Pro tier

	// ~30 days at ~2s/block.
	SubscriptionPeriodBlocks int64 = 1296000

	// Escrow safety bounds.
	MinEscrowUgnot     int64 = 1000
	MinEscrowTTLBlocks int64 = 5
	MaxEscrowTTLBlocks int64 = 15000000
	MaxEscrowFeeBps    int64 = 500 // hard protocol cap: never > 5%
)

// Identity binds a native Gno g1... address to local X25519/Ed25519 messaging keys,
// an optional claim-once @handle, subscription tier & credits, and anti-spam rules.
type Identity struct {
	Address          address
	EncPubHex        string // 32-byte X25519 public key (hex)
	SignPubHex       string // 32-byte Ed25519 public key (hex, optional cross-chain parity)
	Handle           string // optional claim-once handle
	DisplayName      string
	Tier             string // TierFree or TierPro
	Credits          int64
	SubExpiresHeight int64
	MinTipUgnot      int64
	AllowListOnly    bool
	Allowed          *avl.Tree // senderAddr -> bool
	Inbox            *avl.Tree // seqKey(n) -> message id, the n-th message received
	InboxCount       uint64
	Sent             *avl.Tree // seqKey(n) -> message id, the n-th message sent
	SentCount        uint64
	CreatedHeight    int64
	UpdatedHeight    int64
}

var (
	// Service pricing in ugnot (configurable by operator; zero hardcoded payout wallets).
	subscriptionPriceUgnot int64 = 25000000 // 25 GNOT per 30-day Pro period
	overageFeeUgnot        int64 = 10000    // 0.01 GNOT pay-per-message when credits == 0
	escrowFeeBps           int64 = 100      // 1.00% settlement fee on claimed DeFi escrows

	// Operator and settlement sink. Render and events do not print them; on a public chain
	// realm state and bank transfers remain publicly inspectable. deployer is bound once in init().
	deployer           address
	operator           address
	settlementSink     address
	accruedServiceFees int64

	// Storage whose gas per send stays flat as history grows: trees and counters, never a slice
	// appended to on every call (a slice's backing array is loaded and saved in full each time).
	identities    = avl.NewTree() // addr.String() -> *Identity
	handles       = avl.NewTree() // handle -> addr.String()
	identityCount uint64          // identities ever registered
	identitySeq   = avl.NewTree() // seqKey(n) -> addr.String(), in registration order

	messages     = avl.NewTree() // seqKey(id) -> *pw.SealedEnvelope
	messageCount uint64
	escrows      = avl.NewTree() // seqKey(id) -> *pw.EscrowRecord
	escrowCount  uint64

	// Append-only RFC 6962 accumulator over every message envelope & escrow transition.
	evidenceAcc   assurance.LedgerAccumulator // grows with every message across transactions: leaves in a tree
	totalTips     int64
	totalEscrowed int64
)

// ── Operator & Settlement Configuration ──────────────────────────────────────

// init binds the deploying account as deployer and operator atomically inside the
// deployment transaction itself, closing any post-deploy operator front-running window.
func init() {
	initOperatorFromDeployment()
}

func initOperatorFromDeployment() {
	deployer = unsafe.OriginCaller()
	operator = deployer
}

// Operator returns the current operator address.
func Operator() address { return operator }

// TransferOperator transfers operator control to a new address (operator only).
func TransferOperator(cur realm, next address) {
	mustOperator(cur)
	if !next.IsValid() {
		panic("invalid operator address")
	}
	operator = next
}

// SetSettlementSink privately sets an optional direct settlement sink for service fees
// (operator only; never exposed in Render() or public chain events).
func SetSettlementSink(cur realm, sink address) {
	mustOperator(cur)
	if sink != "" && !sink.IsValid() {
		panic("invalid settlement address")
	}
	settlementSink = sink
}

// SetPricing updates GNOT service pricing (operator only; escrowFeeBps capped at 5%).
func SetPricing(cur realm, subPriceUgnot, overageUgnot, escFeeBps int64) {
	mustOperator(cur)
	if subPriceUgnot < 0 || overageUgnot < 0 {
		panic("prices cannot be negative")
	}
	if escFeeBps < 0 || escFeeBps > MaxEscrowFeeBps {
		panic("escrowFeeBps out of range (0..500)")
	}
	subscriptionPriceUgnot = subPriceUgnot
	overageFeeUgnot = overageUgnot
	escrowFeeBps = escFeeBps
}

// CollectServiceFees withdraws ONLY accrued service fees (subscriptions, overages,
// settled escrow fees) to an operator-specified destination. Strictly isolated from
// user-locked DeFi escrows.
func CollectServiceFees(cur realm, to address) int64 {
	mustOperator(cur)
	if !to.IsValid() {
		panic("invalid destination address")
	}
	amount := accruedServiceFees
	if amount <= 0 {
		return 0
	}
	accruedServiceFees = 0
	bk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	bk.SendCoins(cur.Address(), to, chain.Coins{chain.NewCoin(denom, amount)})
	return amount
}

// ── Public Pricing Queries (no payout addresses exposed) ─────────────────────

func SubscriptionPriceUgnot() int64 { return subscriptionPriceUgnot }
func OverageFeeUgnot() int64        { return overageFeeUgnot }
func EscrowFeeBps() int64           { return escrowFeeBps }

// ── Identity, Tier & Subscription Lifecycle ──────────────────────────────────

// RegisterIdentity registers (or updates displayName/keys for) the caller's E2EE identity.
// New accounts start on the Free tier (110 credits) matching aura-genesis.org/whisper.
// Handles are strictly claim-once: once claimed, a handle cannot be changed or stolen.
func RegisterIdentity(cur realm, encPubHex, signPubHex, handle, displayName string) {
	prev := cur.Previous()
	if !prev.IsUserCall() {
		panic("register identity with a direct user call")
	}
	if err := pw.ValidateKeyHex(encPubHex); err != nil {
		panic("encPubHex: " + err.Error())
	}
	if signPubHex != "" {
		if err := pw.ValidateKeyHex(signPubHex); err != nil {
			panic("signPubHex: " + err.Error())
		}
	}
	if len(displayName) > 64 {
		panic("displayName too long (max 64)")
	}

	caller := prev.Address()
	key := caller.String()
	height := runtime.ChainHeight()

	var normHandle string
	if strings.TrimSpace(handle) != "" {
		var err error
		normHandle, err = pw.NormalizeHandle(handle)
		if err != nil {
			panic("handle: " + err.Error())
		}
	}

	if id, exists := identities.Get(key).(*Identity); exists && id != nil {
		if normHandle != "" {
			if id.Handle != "" && id.Handle != normHandle {
				panic("identity already owns @" + id.Handle + "; handles cannot be reassigned")
			}
			if id.Handle == "" {
				if handles.Has(normHandle) {
					panic("handle @" + normHandle + " is already taken")
				}
				handles.Set(normHandle, key)
				id.Handle = normHandle
			}
		}
		id.EncPubHex = encPubHex
		if signPubHex != "" {
			id.SignPubHex = signPubHex
		}
		if displayName != "" {
			id.DisplayName = displayName
		}
		id.UpdatedHeight = height
		chain.Emit("WhisperIdentityUpdated", "addr", key, "handle", id.Handle, "enc_pub", encPubHex)
		return
	}

	if normHandle != "" {
		if handles.Has(normHandle) {
			panic("handle @" + normHandle + " is already taken")
		}
		handles.Set(normHandle, key)
	}

	id := &Identity{
		Address:       caller,
		EncPubHex:     encPubHex,
		SignPubHex:    signPubHex,
		Handle:        normHandle,
		DisplayName:   displayName,
		Tier:          TierFree,
		Credits:       FreePeriodCredits,
		Allowed:       avl.NewTree(),
		Inbox:         avl.NewTree(),
		Sent:          avl.NewTree(),
		CreatedHeight: height,
		UpdatedHeight: height,
	}
	identities.Set(key, id)
	identityCount++
	identitySeq.Set(seqKey(identityCount), key)

	chain.Emit("WhisperIdentityRegistered",
		"addr", key,
		"handle", normHandle,
		"tier", TierFree,
		"credits", strconv.FormatInt(FreePeriodCredits, 10),
		"enc_pub", encPubHex,
		"height", strconv.FormatInt(height, 10),
	)
}

// Subscribe upgrades or extends the caller's Whisper identity to the Pro tier for 30 days
// (2,500 credits, 16 KiB envelopes, and DeFi HTLC escrows) by paying exact SubscriptionPriceUgnot in GNOT.
func Subscribe(cur realm) int64 {
	prev := cur.Previous()
	if !prev.IsUserCall() {
		panic("subscribe with a direct user call")
	}
	id := mustIdentity(prev.Address().String())
	paid := sentUgnot()
	if paid != subscriptionPriceUgnot {
		panic("send exact subscription price " + strconv.FormatInt(subscriptionPriceUgnot, 10) + denom +
			"; got " + strconv.FormatInt(paid, 10) + denom)
	}

	height := runtime.ChainHeight()
	baseExpiry := height
	if id.SubExpiresHeight > height {
		baseExpiry = id.SubExpiresHeight
	}
	id.Tier = TierPro
	id.SubExpiresHeight = baseExpiry + SubscriptionPeriodBlocks
	id.Credits = ProPeriodCredits
	id.UpdatedHeight = height

	settleServiceFee(cur, paid)

	chain.Emit("WhisperSubscribed",
		"addr", id.Address.String(),
		"tier", TierPro,
		"paid_ugnot", strconv.FormatInt(paid, 10),
		"credits", strconv.FormatInt(id.Credits, 10),
		"expires_height", strconv.FormatInt(id.SubExpiresHeight, 10),
	)
	return id.SubExpiresHeight
}

// EffectiveTier returns TierPro if the identity has an active subscription, else TierFree.
func EffectiveTier(addrOrHandle string) string {
	id := mustResolveIdentity(addrOrHandle)
	return effectiveTierOf(id, runtime.ChainHeight())
}

// RotateKeys rotates the caller's X25519 / Ed25519 keys without losing handle, subscription, or inbox history.
func RotateKeys(cur realm, newEncPubHex, newSignPubHex string) {
	prev := cur.Previous()
	if !prev.IsUserCall() {
		panic("rotate keys with a direct user call")
	}
	if err := pw.ValidateKeyHex(newEncPubHex); err != nil {
		panic("newEncPubHex: " + err.Error())
	}
	if newSignPubHex != "" {
		if err := pw.ValidateKeyHex(newSignPubHex); err != nil {
			panic("newSignPubHex: " + err.Error())
		}
	}
	id := mustIdentity(prev.Address().String())
	id.EncPubHex = newEncPubHex
	id.SignPubHex = newSignPubHex
	id.UpdatedHeight = runtime.ChainHeight()
	chain.Emit("WhisperKeysRotated", "addr", id.Address.String(), "enc_pub", newEncPubHex)
}

// SetInboxPolicy configures programmable DeFi anti-spam rules on the caller's inbox.
func SetInboxPolicy(cur realm, minTipUgnot int64, allowListOnly bool) {
	prev := cur.Previous()
	if !prev.IsUserCall() {
		panic("set inbox policy with a direct user call")
	}
	if minTipUgnot < 0 {
		panic("minTipUgnot cannot be negative")
	}
	id := mustIdentity(prev.Address().String())
	id.MinTipUgnot = minTipUgnot
	id.AllowListOnly = allowListOnly
	id.UpdatedHeight = runtime.ChainHeight()
	chain.Emit("WhisperInboxPolicy",
		"addr", id.Address.String(),
		"min_tip_ugnot", strconv.FormatInt(minTipUgnot, 10),
		"allowlist_only", strconv.FormatBool(allowListOnly),
	)
}

// SetAllowedSender adds or removes a sender address from the caller's inbox allowlist.
func SetAllowedSender(cur realm, senderAddr string, allowed bool) {
	prev := cur.Previous()
	if !prev.IsUserCall() {
		panic("set allowed sender with a direct user call")
	}
	id := mustIdentity(prev.Address().String())
	if allowed {
		id.Allowed.Set(senderAddr, true)
	} else {
		id.Allowed.Remove(senderAddr)
	}
	id.UpdatedHeight = runtime.ChainHeight()
}

// ── E2EE Messaging + GNOT Tipping & Tier Metering ────────────────────────────

// SendMessage delivers a client-sealed E2EE ciphertext envelope on-chain.
// Consumes 1 message credit from the sender's tier quota; if credits are exhausted,
// collects OverageFeeUgnot in GNOT automatically. Any remaining attached GNOT
// (required >= recipient.MinTipUgnot) forwards 100% straight to recipient.
func SendMessage(
	cur realm,
	toAddrOrHandle string,
	ephemeralPubHex string,
	nonceHex string,
	ciphertextB64 string,
	commitmentHex string,
) uint64 {
	prev := cur.Previous()
	if !prev.IsUserCall() {
		panic("send message with a direct user call")
	}
	sender := mustIdentity(prev.Address().String())
	recipient := mustResolveIdentity(toAddrOrHandle)
	checkCanSend(sender, recipient)
	validateEnvelopeFields(ephemeralPubHex, nonceHex, ciphertextB64, commitmentHex)

	height := runtime.ChainHeight()
	tier := effectiveTierOf(sender, height)
	maxCT := FreeMaxCipherB64
	if tier == TierPro {
		maxCT = ProMaxCipherB64
	}
	if len(ciphertextB64) > maxCT {
		panic("ciphertext exceeds " + tier + " tier payload limit (" + strconv.Itoa(maxCT) + " chars); subscribe to Pro for 16 KiB")
	}

	sent := sentUgnot()
	var serviceFee int64
	if sender.Credits > 0 {
		sender.Credits--
	} else {
		if sent < overageFeeUgnot {
			panic("message credits exhausted: subscribe to Pro or attach at least " +
				strconv.FormatInt(overageFeeUgnot, 10) + denom + " overage fee")
		}
		serviceFee = overageFeeUgnot
	}

	tip := sent - serviceFee
	if tip < recipient.MinTipUgnot {
		panic("recipient requires minimum tip of " + strconv.FormatInt(recipient.MinTipUgnot, 10) + denom +
			"; got " + strconv.FormatInt(tip, 10) + denom + " after service fee")
	}

	msgID := messageCount + 1
	env := &pw.SealedEnvelope{
		ID:              msgID,
		ChainID:         runtime.ChainID(),
		Realm:           cur.PkgPath(),
		From:            sender.Address.String(),
		To:              recipient.Address.String(),
		EphemeralPubHex: ephemeralPubHex,
		NonceHex:        nonceHex,
		CiphertextB64:   ciphertextB64,
		CommitmentHex:   commitmentHex,
		TipUgnot:        tip,
		EscrowID:        0,
		Height:          height,
	}
	leaf := env.LeafHash()
	env.LeafIndex = evidenceAcc.Append(leaf)
	recordMessage(env, sender, recipient)

	if serviceFee > 0 {
		settleServiceFee(cur, serviceFee)
	}
	if tip > 0 {
		totalTips += tip
		bk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
		bk.SendCoins(cur.Address(), recipient.Address, chain.Coins{chain.NewCoin(denom, tip)})
	}

	chain.Emit("WhisperMessage",
		"id", strconv.FormatUint(msgID, 10),
		"from", env.From,
		"to", env.To,
		"tier", tier,
		"commitment", commitmentHex,
		"tip_ugnot", strconv.FormatInt(tip, 10),
		"service_fee_ugnot", strconv.FormatInt(serviceFee, 10),
		"leaf_index", strconv.FormatUint(env.LeafIndex, 10),
		"acc_root", assurance.Hex(evidenceAcc.Root()),
	)
	return msgID
}

// ── DeFi Encrypted Conditional Escrows (Pro Tier + 1% Settlement Fee) ────────

// SendEscrowMessage sends an E2EE ciphertext envelope paired with a locked DeFi GNOT escrow.
// Requires an active Pro subscription (matching Whisper's paid tier for advanced DeFi flows).
func SendEscrowMessage(
	cur realm,
	toAddrOrHandle string,
	ephemeralPubHex string,
	nonceHex string,
	ciphertextB64 string,
	commitmentHex string,
	hashLockHex string,
	ttlBlocks int64,
) (uint64, uint64) {
	prev := cur.Previous()
	if !prev.IsUserCall() {
		panic("send escrow message with a direct user call")
	}
	sender := mustIdentity(prev.Address().String())
	height := runtime.ChainHeight()
	if effectiveTierOf(sender, height) != TierPro {
		panic("DeFi encrypted escrows require an active Pro subscription (call Subscribe with " +
			strconv.FormatInt(subscriptionPriceUgnot, 10) + denom + ")")
	}
	recipient := mustResolveIdentity(toAddrOrHandle)
	if sender.Address == recipient.Address {
		panic("cannot create escrow to self")
	}
	checkCanSend(sender, recipient)
	validateEnvelopeFields(ephemeralPubHex, nonceHex, ciphertextB64, commitmentHex)

	if hashLockHex != "" {
		if _, err := assurance.ParseDigest(hashLockHex); err != nil {
			panic("hashLockHex: " + err.Error())
		}
	}
	if ttlBlocks < MinEscrowTTLBlocks || ttlBlocks > MaxEscrowTTLBlocks {
		panic("ttlBlocks out of allowed range")
	}

	amount := sentUgnot()
	escrowAmount := amount
	if sender.Credits > 0 {
		sender.Credits--
	} else if overageFeeUgnot > 0 {
		if amount < MinEscrowUgnot+overageFeeUgnot {
			panic("out of credits: escrow send must cover overage fee (" + strconv.FormatInt(overageFeeUgnot, 10) + denom + ") plus min escrow")
		}
		settleServiceFee(cur, overageFeeUgnot)
		escrowAmount = amount - overageFeeUgnot
	}
	if escrowAmount < MinEscrowUgnot {
		panic("escrow requires at least " + strconv.FormatInt(MinEscrowUgnot, 10) + denom)
	}
	if escrowAmount < recipient.MinTipUgnot {
		panic("escrow amount below recipient min tip")
	}

	msgID := messageCount + 1
	escID := escrowCount + 1

	env := &pw.SealedEnvelope{
		ID:              msgID,
		ChainID:         runtime.ChainID(),
		Realm:           cur.PkgPath(),
		From:            sender.Address.String(),
		To:              recipient.Address.String(),
		EphemeralPubHex: ephemeralPubHex,
		NonceHex:        nonceHex,
		CiphertextB64:   ciphertextB64,
		CommitmentHex:   commitmentHex,
		TipUgnot:        0,
		EscrowID:        escID,
		Height:          height,
	}
	env.LeafIndex = evidenceAcc.Append(env.LeafHash())
	recordMessage(env, sender, recipient)

	esc := &pw.EscrowRecord{
		ID:            escID,
		MessageID:     msgID,
		Sender:        sender.Address.String(),
		Recipient:     recipient.Address.String(),
		AmountUgnot:   escrowAmount,
		FeeBps:        escrowFeeBps, // locked at creation; later SetPricing never changes open escrows
		HashLockHex:   hashLockHex,
		ExpiryHeight:  height + ttlBlocks,
		Status:        pw.EscrowOpen,
		CreatedHeight: height,
	}
	escLeafIdx := evidenceAcc.Append(esc.LeafHash())
	escrows.Set(seqKey(escID), esc)
	escrowCount = escID
	totalEscrowed += escrowAmount

	chain.Emit("WhisperEscrowCreated",
		"escrow_id", strconv.FormatUint(escID, 10),
		"msg_id", strconv.FormatUint(msgID, 10),
		"from", esc.Sender,
		"to", esc.Recipient,
		"amount_ugnot", strconv.FormatInt(escrowAmount, 10),
		"fee_bps", strconv.FormatInt(esc.FeeBps, 10),
		"hash_lock", hashLockHex,
		"expiry_height", strconv.FormatInt(esc.ExpiryHeight, 10),
		"leaf_index", strconv.FormatUint(escLeafIdx, 10),
		"acc_root", assurance.Hex(evidenceAcc.Root()),
	)
	return msgID, escID
}

// ClaimEscrow settles an open DeFi escrow to its recipient (verifying preimage if hash-locked),
// strictly before ExpiryHeight so HTLC timeout guarantees never race with RefundEscrow.
// Collects the FeeBps locked when the escrow was created; remainder forwards to recipient.
func ClaimEscrow(cur realm, escrowID uint64, preimage string) int64 {
	prev := cur.Previous()
	if !prev.IsUserCall() {
		panic("claim escrow with a direct user call")
	}
	esc := mustEscrow(escrowID)
	if esc.Status != pw.EscrowOpen {
		panic("escrow is already " + string(esc.Status))
	}
	if runtime.ChainHeight() >= esc.ExpiryHeight {
		panic("escrow expired at height " + strconv.FormatInt(esc.ExpiryHeight, 10) + "; only the sender may refund it")
	}
	caller := prev.Address()
	if caller.String() != esc.Recipient {
		panic("only recipient " + esc.Recipient + " may claim escrow")
	}
	if esc.HashLockHex != "" {
		if pw.ComputeHashLock(preimage) != esc.HashLockHex {
			panic("invalid hashlock preimage")
		}
	}

	fee := (esc.AmountUgnot * esc.FeeBps) / 10000
	if fee >= esc.AmountUgnot {
		fee = 0
	}
	payout := esc.AmountUgnot - fee

	esc.Status = pw.EscrowClaimed
	esc.SettledHeight = runtime.ChainHeight()

	leafIdx := evidenceAcc.Append(esc.LeafHash())

	bk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	bk.SendCoins(cur.Address(), caller, chain.Coins{chain.NewCoin(denom, payout)})
	if fee > 0 {
		settleServiceFee(cur, fee)
	}

	chain.Emit("WhisperEscrowClaimed",
		"escrow_id", strconv.FormatUint(esc.ID, 10),
		"recipient", esc.Recipient,
		"payout_ugnot", strconv.FormatInt(payout, 10),
		"service_fee_ugnot", strconv.FormatInt(fee, 10),
		"leaf_index", strconv.FormatUint(leafIdx, 10),
		"acc_root", assurance.Hex(evidenceAcc.Root()),
	)
	return payout
}

// RefundEscrow returns 100% of an expired, unclaimed DeFi escrow back to its sender (zero fee).
func RefundEscrow(cur realm, escrowID uint64) int64 {
	prev := cur.Previous()
	if !prev.IsUserCall() {
		panic("refund escrow with a direct user call")
	}
	esc := mustEscrow(escrowID)
	if esc.Status != pw.EscrowOpen {
		panic("escrow is already " + string(esc.Status))
	}
	caller := prev.Address()
	if caller.String() != esc.Sender {
		panic("only sender " + esc.Sender + " may refund escrow")
	}
	height := runtime.ChainHeight()
	if height < esc.ExpiryHeight {
		panic("escrow has not expired yet; unlocks at height " + strconv.FormatInt(esc.ExpiryHeight, 10))
	}

	esc.Status = pw.EscrowRefunded
	esc.SettledHeight = height
	leafIdx := evidenceAcc.Append(esc.LeafHash())

	bk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	bk.SendCoins(cur.Address(), caller, chain.Coins{chain.NewCoin(denom, esc.AmountUgnot)})

	chain.Emit("WhisperEscrowRefunded",
		"escrow_id", strconv.FormatUint(esc.ID, 10),
		"sender", esc.Sender,
		"refund_ugnot", strconv.FormatInt(esc.AmountUgnot, 10),
		"leaf_index", strconv.FormatUint(leafIdx, 10),
		"acc_root", assurance.Hex(evidenceAcc.Root()),
	)
	return esc.AmountUgnot
}

// ── Public Read & Proof Queries ──────────────────────────────────────────────

// ResolveRecipient returns the public directory record for an address or @handle.
func ResolveRecipient(addrOrHandle string) string {
	id := mustResolveIdentity(addrOrHandle)
	tier := effectiveTierOf(id, runtime.ChainHeight())
	return id.Address.String() + "|" + id.EncPubHex + "|" + id.Handle + "|" + tier + "|" +
		strconv.FormatInt(id.MinTipUgnot, 10) + "|" + strconv.FormatBool(id.AllowListOnly)
}

func Root() string            { return assurance.Hex(evidenceAcc.Root()) }
func AccumulatorSize() uint64 { return evidenceAcc.Size() }
func MessageCount() uint64    { return messageCount }
func EscrowCount() uint64     { return escrowCount }

func MessageLeafHex(msgID uint64) string {
	if msgID == 0 || msgID > messageCount {
		panic("no message " + strconv.FormatUint(msgID, 10))
	}
	return assurance.Hex(messages.Get(seqKey(msgID)).(*pw.SealedEnvelope).LeafHash())
}

func ProofForLeaf(leafIndex, treeSize uint64) string {
	proof, err := evidenceAcc.Proof(leafIndex, treeSize)
	if err != nil {
		panic(err.Error())
	}
	parts := make([]string, len(proof))
	for i, h := range proof {
		parts[i] = assurance.Hex(h)
	}
	return strings.Join(parts, ",")
}

func VerifyLeafProof(leafIndex, treeSize uint64, leafHex, proofCSV string) bool {
	if leafIndex >= treeSize || treeSize > evidenceAcc.Size() {
		return false
	}
	leaf, err := assurance.ParseDigest(leafHex)
	if err != nil {
		return false
	}
	rootAt, err := evidenceAcc.RootAt(treeSize)
	if err != nil {
		return false
	}
	var proof [][32]byte
	if strings.TrimSpace(proofCSV) != "" {
		for _, tok := range strings.Split(proofCSV, ",") {
			d, err := assurance.ParseDigest(strings.TrimSpace(tok))
			if err != nil {
				return false
			}
			proof = append(proof, d)
		}
	}
	return assurance.VerifyInclusion(leafIndex, treeSize, leaf, proof, rootAt)
}

// ── Internal Helpers ─────────────────────────────────────────────────────────

func settleServiceFee(cur realm, amount int64) {
	if amount <= 0 {
		return
	}
	if settlementSink != "" {
		bk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
		bk.SendCoins(cur.Address(), settlementSink, chain.Coins{chain.NewCoin(denom, amount)})
		return
	}
	accruedServiceFees += amount
}

func mustOperator(cur realm) {
	prev := cur.Previous()
	if !prev.IsUserCall() {
		panic("operator action requires a direct user call")
	}
	if operator == "" {
		panic("operator not initialized")
	}
	if prev.Address() != operator {
		panic("unauthorized: operator only")
	}
}

func effectiveTierOf(id *Identity, height int64) string {
	if id.Tier == TierPro && id.SubExpiresHeight > height {
		return TierPro
	}
	return TierFree
}

func mustIdentity(addr string) *Identity {
	id, ok := identities.Get(addr).(*Identity)
	if !ok || id == nil {
		panic("identity not registered for " + addr)
	}
	return id
}

func mustResolveIdentity(addrOrHandle string) *Identity {
	q := strings.TrimSpace(addrOrHandle)
	if id, ok := identities.Get(q).(*Identity); ok && id != nil {
		return id
	}
	clean := strings.ToLower(strings.TrimLeft(q, "@"))
	if targetAddr, ok := handles.Get(clean).(string); ok && targetAddr != "" {
		return mustIdentity(targetAddr)
	}
	panic("recipient not found: " + addrOrHandle)
}

func mustEscrow(id uint64) *pw.EscrowRecord {
	if id == 0 || id > escrowCount {
		panic("escrow not found: " + strconv.FormatUint(id, 10))
	}
	return escrows.Get(seqKey(id)).(*pw.EscrowRecord)
}

// recordMessage stores a sent envelope under its id and in the sender's and recipient's own lists.
func recordMessage(env *pw.SealedEnvelope, sender, recipient *Identity) {
	messages.Set(seqKey(env.ID), env)
	messageCount = env.ID
	recipient.InboxCount++
	recipient.Inbox.Set(seqKey(recipient.InboxCount), env.ID)
	sender.SentCount++
	sender.Sent.Set(seqKey(sender.SentCount), env.ID)
}

// seqKey is a sequence number in fixed-width decimal, so a tree's key order is sequence order.
func seqKey(n uint64) string {
	s := strconv.FormatUint(n, 10)
	return strings.Repeat("0", 20-len(s)) + s
}

func checkCanSend(sender, recipient *Identity) {
	if recipient.AllowListOnly && sender.Address != recipient.Address {
		if !recipient.Allowed.Has(sender.Address.String()) {
			panic("recipient only accepts messages from allowlisted senders")
		}
	}
}

func validateEnvelopeFields(ephemeralPubHex, nonceHex, ciphertextB64, commitmentHex string) {
	if err := pw.ValidateKeyHex(ephemeralPubHex); err != nil {
		panic("ephemeralPubHex: " + err.Error())
	}
	if err := pw.ValidateNonceHex(nonceHex); err != nil {
		panic("nonceHex: " + err.Error())
	}
	if err := pw.ValidateCiphertextB64(ciphertextB64); err != nil {
		panic("ciphertextB64: " + err.Error())
	}
	if _, err := assurance.ParseDigest(commitmentHex); err != nil {
		panic("commitmentHex: " + err.Error())
	}
}

func sentUgnot() int64 {
	var total int64
	for _, c := range unsafe.OriginSend() {
		if c.Amount == 0 {
			continue
		}
		if c.Denom != denom || c.Amount < 0 {
			panic("only " + denom + " is accepted")
		}
		total += c.Amount
	}
	return total
}

package competition

import (
	"chain"
	"chain/banker"
	"chain/runtime"
	"chain/runtime/unsafe"
	"encoding/hex"
	"strconv"
	"strings"
	"time"
)

const (
	denom = "ugnot"
	ruleset = "strait-run-v1"
	maxScore = 30200
	attemptCap = 3
	weekSeconds int64 = 7 * 24 * 60 * 60
	firstMonday int64 = 4 * 24 * 60 * 60
	maxCoin int64 = 9223372036854775807
)

var (
	admin address
	verifier address
	treasury address
	paused bool
	firstSeason int64
	firstSeasonOpenedAt int64
	nextSnapshot int64
	seasonRules = make(map[int64][10]int64)
	seasons = make(map[int64]*Season)
	duels = make(map[int64]*Duel)
	duelReferences = make(map[string]bool)
	pilotDuels = make(map[address][]int64)
	catalog = make(map[int64]*Cosmetic)
	purchases = make(map[string]*Purchase)
	nextDuelID int64 = 1
	nextCosmeticID int64 = 1
	retainedClaimable int64
)

func init(cur realm) {
	admin = cur.Previous().Address()
}

func Configure(cur realm, signer, retainedRecipient address, start int64) {
	runtime.AssertOriginCall()
	requireAdmin(cur)
	now := time.Now().Unix()
	current := weekID(now)
	require(firstSeason == 0 && start > 0 && start >= current && start < current+53, "publish the current or a future opening week")
	require(signer.IsValid() && signer != admin && retainedRecipient.IsValid(), "invalid verifier or treasury")
	firstSeason, nextSnapshot = start, start
	firstSeasonOpenedAt = weekStart(start)
	if start == current {
		firstSeasonOpenedAt = now
	}
	verifier, treasury = signer, retainedRecipient
}

func SetVerifier(cur realm, signer address) {
	runtime.AssertOriginCall()
	requireAdmin(cur)
	require(signer.IsValid() && signer != admin, "invalid verifier")
	verifier = signer
}

func PauseEntries(cur realm, stop bool) {
	runtime.AssertOriginCall()
	requireAdmin(cur)
	paused = stop
}

func PublishShares(cur realm, id int64, csv string) {
	runtime.AssertOriginCall()
	requireAdmin(cur)
	now := weekID(time.Now().Unix())
	require(firstSeason > 0 && id >= firstSeason && id > now && id < now+53, "only a future season can be configured")
	require(len(csv) <= 50, "invalid share length")
	_, published := seasonRules[id]
	require(!published, "shares already published")
	parts := strings.Split(csv, ",")
	require(len(parts) == 10, "ten shares required")
	var shares [10]int64
	var total int64
	for i, part := range parts {
		value, err := strconv.ParseInt(part, 10, 64)
		require(err == nil && value > 0 && value <= 10000, "invalid share")
		shares[i] = value
		total += value
	}
	require(total == 10000, "shares must sum to 10000")
	seasonRules[id] = shares
}

func ClaimTreasury(cur realm) int64 {
	runtime.AssertOriginCall()
	caller := paidCaller(cur, 0)
	require(caller == treasury, "treasury only")
	amount := retainedClaimable
	retainedClaimable = 0
	pay(cur, caller, amount)
	return amount
}

func requireAdmin(cur realm) {
	require(paidCaller(cur, 0) == admin, "admin only")
}

// The public entry point must assert the origin before calling this helper.
func paidCaller(cur realm, amount int64) address {
	require(cur.IsCurrent(), "invalid realm frame")
	previous := cur.Previous()
	require(previous.IsUserCall(), "direct wallet call required")
	checkPayment(unsafe.OriginSend(), amount)
	return previous.Address()
}

func checkPayment(sent chain.Coins, amount int64) {
	if amount == 0 {
		require(len(sent) == 0, "unexpected payment")
		return
	}
	require(amount > 0 && len(sent) == 1 && sent[0].Denom == denom && sent[0].Amount == amount, "exact ugnot payment required")
}

func pay(cur realm, recipient address, amount int64) {
	if amount > 0 {
		banker.NewBanker(banker.BankerTypeRealmSend, cur).SendCoins(cur.Address(), recipient, chain.Coins{{Denom: denom, Amount: amount}})
	}
}

func require(condition bool, message string) {
	if !condition {
		panic(message)
	}
}

func checkedAdd(a, b int64) int64 {
	require(a >= 0 && b >= 0 && a <= maxCoin-b, "amount overflow")
	return a + b
}

func basisPoints(amount, share int64) int64 {
	return amount/10000*share + amount%10000*share/10000
}

func weekID(timestamp int64) int64 {
	return (timestamp-firstMonday)/weekSeconds
}

func weekStart(id int64) int64 {
	return firstMonday + id*weekSeconds
}

func decimal(value int64) string {
	return strconv.FormatInt(value, 10)
}

func validHex(value string, size int) bool {
	if len(value) != size || strings.ToLower(value) != value {
		return false
	}
	_, err := hex.DecodeString(value)
	return err == nil
}

package competition

import (
	"chain/runtime"
	"crypto/ed25519"
	"encoding/hex"
	"strings"
	"time"
)

var duelVerifierKey string

func SetDuelVerifier(cur realm, publicKey string) {
	runtime.AssertOriginCall()
	requireAdmin(cur)
	require(validHex(publicKey, 64), "invalid Ed25519 key")
	duelVerifierKey = publicKey
}

const joinWindow int64 = 24*60*60
const runWindow int64 = 24*60*60

type Duel struct {
	ID int64
	Creator address
	Rival address
	Stake int64
	Seed int64
	JoinDeadline int64
	RunDeadline int64
	Joined bool
	CreatorScore *ScoreSubmission
	RivalScore *ScoreSubmission
	SettledAt int64
	Outcome string
	Winner address
	Fee int64
	CreatorCredit int64
	RivalCredit int64
	CreatorClaimed bool
	RivalClaimed bool
}

func CreateDuel(cur realm, rival address, stake int64, reference string) int64 {
	runtime.AssertOriginCall()
	creator := paidCaller(cur, stake)
	require(!paused && duelVerifierKey != "" && firstSeason > 0 && weekID(time.Now().Unix()) >= firstSeason, "duel entries paused or unavailable")
	require(rival.IsValid() && rival != creator, "choose a different pilot")
	require(stake > 0 && stake <= maxCoin/2 && validHex(reference, 32), "invalid stake or reference")
	key := string(creator)+":"+reference
	require(!duelReferences[key], "duel already created")
	id := nextDuelID
	nextDuelID = checkedAdd(id, 1)
	now := time.Now().Unix()
	duels[id] = &Duel{ID: id, Creator: creator, Rival: rival, Stake: stake,
		Seed: seasonSeed(id), JoinDeadline: now+joinWindow}
	duelReferences[key] = true
	pilotDuels[creator] = append(pilotDuels[creator], id)
	pilotDuels[rival] = append(pilotDuels[rival], id)
	return id
}

func JoinDuel(cur realm, id int64) {
	runtime.AssertOriginCall()
	d := mustDuel(id)
	pilot := paidCaller(cur, d.Stake)
	now := time.Now().Unix()
	require(!paused && d.SettledAt == 0 && !d.Joined && now < d.JoinDeadline, "duel closed to deposits")
	require(pilot == d.Rival, "invited rival only")
	d.Joined = true
	d.RunDeadline = now+runWindow
}

func SubmitDuel(cur realm, id, seed int64, version string, score int, digest string, expiry int64, signature string) {
	runtime.AssertOriginCall()
	pilot := paidCaller(cur, 0)
	d := mustDuel(id)
	require(d.Joined && d.SettledAt == 0 && (pilot == d.Creator || pilot == d.Rival), "duel unavailable to this pilot")
	now := time.Now().Unix()
	checkEvidence(now, expiry, d.RunDeadline, d.Seed, seed, version, score, digest)
	message := duelMessage(runtime.ChainID(), cur.PkgPath(), pilot, id, seed, version, score, digest, expiry)
	require(validProof(duelVerifierKey, message, signature), "invalid verifier signature")
	submission := &ScoreSubmission{Seed: seed, Score: score, Digest: digest, Proof: signature, VerifierKey: duelVerifierKey, ExpiresAt: expiry, AcceptedAt: now}
	if pilot == d.Creator {
		require(d.CreatorScore == nil, "creator already submitted")
		d.CreatorScore = submission
	} else {
		require(pilot == d.Rival && d.RivalScore == nil, "rival unavailable or already submitted")
		d.RivalScore = submission
	}
}

func duelMessage(chainID, pkgPath string, pilot address, id, seed int64, version string, score int, digest string, expiry int64) string {
	return strings.Join([]string{"altair-duel-v1", chainID, pkgPath, string(pilot),
		decimal(id), decimal(seed), version, decimal(int64(score)), digest, decimal(expiry)}, "|")
}

func validProof(publicKey, message, signature string) bool {
	if !validHex(publicKey, 64) || !validHex(signature, 128) {
		return false
	}
	key, _ := hex.DecodeString(publicKey)
	proof, _ := hex.DecodeString(signature)
	return ed25519.Verify(key, []byte(message), proof)
}

func SettleDuel(cur realm, id int64) {
	runtime.AssertOriginCall()
	paidCaller(cur, 0)
	now := time.Now().Unix()
	d := mustDuel(id)
	if d.settle(now) && d.Fee > 0 {
		recordRevenue(now, 0, d.Fee)
	}
}

func (d *Duel) settle(now int64) bool {
	if d.SettledAt != 0 {
		return false
	}
	a, b := d.CreatorScore, d.RivalScore
	switch {
	case !d.Joined:
		require(now >= d.JoinDeadline, "rival can still join")
		d.Outcome = "unmatched-refund"
		d.CreatorCredit = d.Stake
	case (a == nil || b == nil) && now < d.RunDeadline:
		panic("pilot can still submit")
	case a == nil && b == nil:
		d.Outcome = "no-show-refund"
		d.CreatorCredit, d.RivalCredit = d.Stake, d.Stake
	case a != nil && b != nil && a.Score == b.Score:
		d.Outcome = "tie-refund"
		d.CreatorCredit, d.RivalCredit = d.Stake, d.Stake
	default:
		pot := checkedAdd(d.Stake, d.Stake)
		d.Fee = pot/10
		d.Outcome = "winner"
		if a == nil || b == nil {
			d.Outcome = "forfeit"
		}
		if a != nil && (b == nil || a.Score > b.Score) {
			d.Winner, d.CreatorCredit = d.Creator, pot-d.Fee
		} else {
			d.Winner, d.RivalCredit = d.Rival, pot-d.Fee
		}
	}
	d.SettledAt = now
	return true
}

func ClaimDuel(cur realm, id int64) int64 {
	runtime.AssertOriginCall()
	pilot := paidCaller(cur, 0)
	d := mustDuel(id)
	amount := d.claim(pilot)
	pay(cur, pilot, amount)
	return amount
}

func (d *Duel) claim(pilot address) int64 {
	require(d.SettledAt > 0, "duel settlement required")
	if pilot == d.Creator {
		if d.CreatorClaimed || d.CreatorCredit == 0 {
			return 0
		}
		d.CreatorClaimed = true
		return d.CreatorCredit
	}
	require(pilot == d.Rival, "participants only")
	if d.RivalClaimed || d.RivalCredit == 0 {
		return 0
	}
	d.RivalClaimed = true
	return d.RivalCredit
}

func mustDuel(id int64) *Duel {
	d := duels[id]
	require(d != nil, "duel not found")
	return d
}

package competition

import (
	"chain/runtime"
	"strings"
	"time"

	"gno.land/p/nt/avl/v0"
)

type ScoreSubmission struct {
	Seed int64
	Score int
	Digest string
	Verifier address
	VerifierKey string
	Proof string
	ExpiresAt int64
	AcceptedAt int64
}

type WeeklyPilot struct {
	Attempts int
	Flights [attemptCap]ScoreSubmission
	Best ScoreSubmission
	Prize int64
	Rank int
	Claimed bool
}

type Season struct {
	ID int64
	Seed int64
	Shares [10]int64
	FinalizedAt int64
	Snapshot int64
	CarryIn int64
	CarryOut int64
	Reserved int64
	Claimed int64
	Revenue RevenueLedger
	pilots map[address]*WeeklyPilot
	ranking *avl.Tree
}

func defaultShares() [10]int64 {
	return [10]int64{3000, 1800, 1300, 1000, 800, 600, 500, 400, 300, 300}
}

func sharesFor(id int64) [10]int64 {
	if shares, exists := seasonRules[id]; exists {
		return shares
	}
	return defaultShares()
}

func newSeason(id int64, shares [10]int64) *Season {
	return &Season{
		ID: id, Seed: seasonSeed(id), Shares: shares,
		pilots: make(map[address]*WeeklyPilot), ranking: avl.NewTree(),
	}
}

func seasonSeed(id int64) int64 {
	return (id%4294967296*1664525 + 1013904223) % 4294967296
}

func getSeason(id int64) *Season {
	if s := seasons[id]; s != nil {
		return s
	}
	s := newSeason(id, sharesFor(id))
	seasons[id] = s
	return s
}

func (s *Season) record(pilot address, submission ScoreSubmission) {
	require(s.FinalizedAt == 0, "season finalized")
	p := s.pilots[pilot]
	if p == nil {
		p = &WeeklyPilot{}
		s.pilots[pilot] = p
	}
	for i := 0; i < p.Attempts; i++ {
		require(p.Flights[i].Digest != submission.Digest, "replay already used")
	}
	require(p.Attempts < attemptCap, "all three flights used")
	p.Flights[p.Attempts] = submission
	p.Attempts++
	if p.Attempts == 1 || submission.Score > p.Best.Score {
		if p.Attempts > 1 {
			s.ranking.Remove(scoreKey(pilot, p.Best))
		}
		p.Best = submission
		s.ranking.Set(scoreKey(pilot, submission), pilot)
	}
}

func scoreKey(pilot address, submission ScoreSubmission) string {
	score := decimal(int64(maxScore-submission.Score))
	timestamp := decimal(submission.AcceptedAt)
	return strings.Repeat("0", 5-len(score)) + score + ":" +
		strings.Repeat("0", 20-len(timestamp)) + timestamp + ":" + string(pilot)
}

func (s *Season) pilotRank(pilot address, p *WeeklyPilot) int {
	key := scoreKey(pilot, p.Best)
	low, high := 0, s.ranking.Size()
	for low < high {
		mid := low+(high-low)/2
		candidate, _ := s.ranking.GetByIndex(mid)
		if candidate < key {
			low = mid+1
		} else {
			high = mid
		}
	}
	return low+1
}

func checkEvidence(now, expiry, deadline, expectedSeed, seed int64, version string, score int, digest string) {
	require(now < deadline && now < expiry && expiry <= deadline, "submission expired")
	require(seed == expectedSeed && version == ruleset, "wrong mission seed or ruleset")
	require(score >= 0 && score <= maxScore && validHex(digest, 64), "invalid score or replay digest")
}

// The verifier's Gno transaction is the signed attestation. The pilot
// authorizes the replay off chain and pays no Gno transaction fees.
func SubmitWeekly(cur realm, pilot address, id, seed int64, version string, score int, digest string, expiry int64) {
	runtime.AssertOriginCall()
	signer := paidCaller(cur, 0)
	require(signer == verifier && pilot.IsValid(), "verified pilot required")
	now := time.Now().Unix()
	require(!paused && firstSeason > 0 && id >= firstSeason && id == weekID(now), "season closed to entries")
	checkEvidence(now, expiry, weekStart(id+1), seasonSeed(id), seed, version, score, digest)
	getSeason(id).record(pilot, ScoreSubmission{Seed: seed, Score: score, Digest: digest, Verifier: signer, ExpiresAt: expiry, AcceptedAt: now})
}

func FinalizeWeek(cur realm, id int64) {
	runtime.AssertOriginCall()
	paidCaller(cur, 0)
	now := time.Now().Unix()
	require(firstSeason > 0 && id >= firstSeason && id < weekID(now), "week is still open")
	if id < nextSnapshot {
		return
	}
	require(id == nextSnapshot, "finalize previous week first")
	s := getSeason(id)
	s.snapshot(now)
	getSeason(id+1).CarryIn = s.CarryOut
	nextSnapshot++
}

func (s *Season) snapshot(now int64) {
	require(s.FinalizedAt == 0, "already finalized")
	s.Snapshot = checkedAdd(s.CarryIn, s.Revenue.Allocation)
	for i := 0; i < len(s.Shares) && i < s.ranking.Size(); i++ {
		_, entry := s.ranking.GetByIndex(i)
		p := s.pilots[entry.(address)]
		p.Rank = i+1
		p.Prize = basisPoints(s.Snapshot, s.Shares[i])
		s.Reserved = checkedAdd(s.Reserved, p.Prize)
	}
	s.CarryOut = s.Snapshot-s.Reserved
	s.FinalizedAt = now
}

func ClaimPrize(cur realm, id int64) int64 {
	runtime.AssertOriginCall()
	pilot := paidCaller(cur, 0)
	s := seasons[id]
	require(s != nil && s.FinalizedAt != 0, "snapshot required")
	amount := s.claim(pilot)
	pay(cur, pilot, amount)
	return amount
}

func (s *Season) claim(pilot address) int64 {
	p := s.pilots[pilot]
	require(p != nil && p.Rank > 0 && p.Prize > 0, "no prize for this address")
	if p.Claimed {
		return 0
	}
	p.Claimed = true
	s.Claimed = checkedAdd(s.Claimed, p.Prize)
	require(s.Claimed <= s.Reserved, "claims exceed snapshot")
	return p.Prize
}

package competition

import (
	"chain/runtime"
	"time"
)

var equipped = make(map[address]int64)

type Cosmetic struct {
	ID int64
	Style string
	Price int64
	StartsAt int64
	EndsAt int64
	Enabled bool
}

type Purchase struct {
	Buyer address
	Item int64
	Amount int64
	Denom string
	PurchasedAt int64
}

type RevenueLedger struct {
	Shop int64
	DuelFees int64
	Deductions int64
	Realized int64
	Allocation int64
	Retained int64
}

func ListCosmetic(cur realm, style string, price, startsAt, endsAt int64) int64 {
	runtime.AssertOriginCall()
	requireAdmin(cur)
	now := time.Now().Unix()
	if startsAt == 0 {
		startsAt = now
	} else {
		require(startsAt > now, "invalid cosmetic schedule or price")
	}
	require(firstSeason > 0 && startsAt >= firstSeasonOpenedAt &&
		endsAt > startsAt && price > 0, "invalid cosmetic schedule or price")
	require(style == "azure" || style == "ember" || style == "frost", "unknown presentation-only livery")
	id := nextCosmeticID
	nextCosmeticID = checkedAdd(id, 1)
	catalog[id] = &Cosmetic{ID: id, Style: style, Price: price, StartsAt: startsAt, EndsAt: endsAt, Enabled: true}
	return id
}

func DisableCosmetic(cur realm, id int64) {
	runtime.AssertOriginCall()
	requireAdmin(cur)
	item := catalog[id]
	require(item != nil, "cosmetic not found")
	item.Enabled = false
}

func BuyCosmetic(cur realm, id int64) {
	runtime.AssertOriginCall()
	item := catalog[id]
	require(item != nil, "cosmetic not found")
	buyer := paidCaller(cur, item.Price)
	now := time.Now().Unix()
	require(!paused && item.available(now), "cosmetic unavailable")
	key := purchaseKey(buyer, id)
	// Rejection rolls back the incoming coin transfer, even after a lost client response.
	require(purchases[key] == nil, "cosmetic already owned")
	purchases[key] = &Purchase{Buyer: buyer, Item: id, Amount: item.Price, Denom: denom, PurchasedAt: now}
	recordRevenue(now, item.Price, 0)
}

func EquipCosmetic(cur realm, id int64) {
	runtime.AssertOriginCall()
	pilot := paidCaller(cur, 0)
	require(id == 0 || purchases[purchaseKey(pilot, id)] != nil, "cosmetic is not owned")
	equipped[pilot] = id
}

func (item *Cosmetic) available(now int64) bool {
	return item.Enabled && now >= item.StartsAt && now < item.EndsAt
}

func purchaseKey(pilot address, id int64) string {
	return string(pilot)+":"+decimal(id)
}

func recordRevenue(now, sale, fee int64) {
	id := weekID(now)
	require(firstSeason > 0 && id >= firstSeason && id >= nextSnapshot, "revenue week unavailable")
	ledger := &getSeason(id).Revenue
	previous := ledger.Retained
	ledger.record(sale, fee)
	retainedClaimable = checkedAdd(retainedClaimable, ledger.Retained-previous)
}

func (ledger *RevenueLedger) record(sale, fee int64) {
	ledger.Shop = checkedAdd(ledger.Shop, sale)
	ledger.DuelFees = checkedAdd(ledger.DuelFees, fee)
	ledger.Realized = checkedAdd(ledger.Shop, ledger.DuelFees)-ledger.Deductions
	ledger.Allocation = ledger.Realized/2
	ledger.Retained = ledger.Realized-ledger.Allocation
}

package competition

import (
	"strconv"
	"strings"
	"time"
)

const pageSize = 20

// Render emits bounded, pipe-delimited records for the Altair browser.
func Render(path string) string {
	require(len(path) < 150, "view path too long")
	parts := strings.Split(strings.Trim(path, "/"), "/")
	if len(parts) == 1 && parts[0] == "" {
		return "# Altair\n\nStrait Run weekly league and native ugnot economy.\n"
	}
	now := time.Now().Unix()
	switch parts[0] {
	case "status":
		require(len(parts) == 1, "invalid status path")
		return row("status", decimal(now), decimal(weekID(now)), decimal(firstSeason), decimal(nextSnapshot), strconv.FormatBool(paused), ruleset, denom, duelVerifierKey,
			string(verifier), string(treasury), decimal(retainedClaimable))
	case "weekly":
		require(len(parts) == 4, "invalid weekly path")
		return renderWeekly(viewID(parts[1]), viewOffset(parts[2]), parts[3])
	case "duel":
		require(len(parts) == 2, "invalid duel path")
		if d := duels[viewID(parts[1])]; d != nil {
			return renderDuel(d)
		}
	case "duels":
		require(len(parts) == 3, "invalid duel history path")
		pilot := viewPilot(parts[1])
		ids := pilotDuels[pilot]
		start := viewOffset(parts[2])
		var result string
		for i := start; i < len(ids) && i-start < pageSize; i++ {
			result += renderDuel(duels[ids[len(ids)-1-i]])
		}
		return result
	case "livery":
		require(len(parts) == 2, "invalid livery path")
		pilot := viewPilot(parts[1])
		if item := catalog[equipped[pilot]]; item != nil {
			return row("livery", decimal(item.ID), item.Style)
		}
	case "shop":
		require(len(parts) == 3, "invalid shop path")
		return renderShop(viewOffset(parts[1]), viewPilot(parts[2]), now)
	default:
		panic("unknown Altair view")
	}
	return ""
}

func renderWeekly(id int64, offset int, pilot string) string {
	if firstSeason == 0 || id < firstSeason || id > weekID(time.Now().Unix())+52 {
		return ""
	}
	s := seasons[id]
	if s == nil {
		s = newSeason(id, sharesFor(id))
	}
	revenue := s.Revenue
	carryPending := id > nextSnapshot
	projectedPool := checkedAdd(s.CarryIn, revenue.Allocation)
	opens := weekStart(id)
	if id == firstSeason {
		opens = firstSeasonOpenedAt
	}
	var result = row("weekly", decimal(id), decimal(opens), decimal(weekStart(id+1)), decimal(s.Seed),
		decimal(s.FinalizedAt), decimal(projectedPool), decimal(s.Snapshot), decimal(s.CarryIn), decimal(s.CarryOut),
		decimal(revenue.Shop), decimal(revenue.DuelFees), decimal(revenue.Deductions), decimal(revenue.Realized),
		decimal(revenue.Allocation), decimal(revenue.Retained), decimal(s.Reserved), decimal(s.Claimed),
		decimal(int64(s.ranking.Size())), strconv.FormatBool(carryPending))
	for i, share := range s.Shares {
		result += row("share", decimal(int64(i+1)), decimal(share))
	}
	for i := offset; i < s.ranking.Size() && i-offset < pageSize; i++ {
		_, entry := s.ranking.GetByIndex(i)
		owner := entry.(address)
		result += renderPilot(s.pilots[owner], owner, "pilot", i+1)
	}
	owner := viewPilot(pilot)
	if p := s.pilots[owner]; p != nil {
		result += renderPilot(p, owner, "self", s.pilotRank(owner, p))
	}
	return result
}

func renderPilot(p *WeeklyPilot, owner address, kind string, rank int) string {
	if p.Rank > 0 {
		rank = p.Rank
	}
	result := row(kind, string(owner), decimal(int64(rank)), decimal(int64(p.Attempts)), decimal(int64(p.Best.Score)),
		decimal(p.Best.AcceptedAt), decimal(p.Prize), strconv.FormatBool(p.Claimed))
	if kind == "pilot" {
		return result
	}
	for i := 0; i < p.Attempts; i++ {
		result += renderScore("flight", string(owner), p.Flights[i])
	}
	return result
}

func renderScore(kind, owner string, score ScoreSubmission) string {
	return row(kind, owner, decimal(score.Seed), decimal(int64(score.Score)), score.Digest,
		string(score.Verifier), decimal(score.ExpiresAt), decimal(score.AcceptedAt), score.VerifierKey, score.Proof)
}

func renderDuel(d *Duel) string {
	result := row("duel", decimal(d.ID), string(d.Creator), string(d.Rival), decimal(d.Stake), decimal(d.Seed),
		decimal(d.JoinDeadline), decimal(d.RunDeadline), strconv.FormatBool(d.Joined), decimal(d.SettledAt),
		d.Outcome, string(d.Winner), decimal(d.Fee), decimal(d.CreatorCredit), decimal(d.RivalCredit),
		strconv.FormatBool(d.CreatorClaimed), strconv.FormatBool(d.RivalClaimed))
	if d.CreatorScore != nil {
		result += renderScore("duel-flight", string(d.Creator), *d.CreatorScore)
	}
	if d.RivalScore != nil {
		result += renderScore("duel-flight", string(d.Rival), *d.RivalScore)
	}
	return result
}

func renderShop(offset int, pilot address, now int64) string {
	var result string
	for i := int64(offset)+1; i < nextCosmeticID && i-int64(offset) <= pageSize; i++ {
		item := catalog[i]
		result += row("item", decimal(item.ID), item.Style, decimal(item.Price), decimal(item.StartsAt),
			decimal(item.EndsAt), strconv.FormatBool(item.available(now)), strconv.FormatBool(equipped[pilot] == i))
		if p := purchases[purchaseKey(pilot, i)]; p != nil {
			result += row("purchase", decimal(i), string(p.Buyer), decimal(p.Amount), p.Denom, decimal(p.PurchasedAt))
		}
	}
	return result
}

func viewPilot(raw string) address {
	if raw == "-" {
		return ""
	}
	pilot := address(raw)
	require(pilot.IsValid(), "invalid pilot address")
	return pilot
}

func viewID(raw string) int64 {
	id, err := strconv.ParseInt(raw, 10, 64)
	require(err == nil && id > 0, "invalid record id")
	return id
}

func viewOffset(raw string) int {
	offset, err := strconv.ParseInt(raw, 10, 32)
	require(err == nil && offset >= 0, "invalid page offset")
	return int(offset)
}

func row(fields ...string) string {
	return strings.Join(fields, "|")+"\n"
}

package bs_core

import (
	"errors"
	"math/overflow"
)

// SafeAdd64 adds two int64 values and saturates at MaxInt64 on overflow.
// Used by non-panicking accounting/reputation counters.
func SafeAdd64(a, b int64) int64 {
	if b > 0 && a > (1<<63-1)-b {
		return 1<<63 - 1
	}
	if b < 0 && a < (-1<<63)-b {
		return -1 << 63
	}
	return a + b
}

// StrictAdd64 returns an error on int64 overflow/underflow.
func StrictAdd64(a, b int64) (int64, error) {
	sum, ok := overflow.Add64(a, b)
	if !ok {
		return 0, errors.New("int64 overflow")
	}
	return sum, nil
}

// CalcProtocolFee computes the 2% floor protocol fee on a positive payout.
func CalcProtocolFee(amount int64) int64 {
	if amount <= 0 {
		return 0
	}
	return (amount * ProtocolFeePct) / 100
}

// CalcDisputeFee computes the 5% floor dispute fee on a quest/slot reward.
func CalcDisputeFee(reward int64) int64 {
	if reward <= 0 {
		return 0
	}
	return (reward * DisputeFeePct) / 100
}

// StakeBounds returns the inclusive [minStake, maxStake] bounds (5%..15% of reward).
func StakeBounds(reward int64) (minStake, maxStake int64) {
	if reward <= 0 {
		return 0, 0
	}
	return (reward * MinStakePct) / 100, (reward * MaxStakePct) / 100
}

// ValidateReward checks reward >= MinRewardUgnot and prevents multiplication overflow.
func ValidateReward(reward int64) error {
	if reward < MinRewardUgnot {
		return errors.New("reward below minimum (1 GNOT / 1000000ugnot)")
	}
	// Ensure reward * 100 stays safely within int64.
	if reward > (1<<63-1)/100 {
		return errors.New("reward exceeds safe integer bound")
	}
	return nil
}

// ValidateStakeBounds enforces stake in [5%, 15%] of reward (no absolute floor).
func ValidateStakeBounds(reward, stake int64) error {
	if err := ValidateReward(reward); err != nil {
		return err
	}
	minStake, maxStake := StakeBounds(reward)
	if stake <= 0 || stake < minStake || stake > maxStake {
		return errors.New("stake must be between 5% and 15% of reward")
	}
	return nil
}

// CalcArbiterTimeoutSplit computes the exact 50/50 split on arbiter timeout
// under the global rounding rule:
//   - half = reward / 2
//   - sponsorAmt = half
//   - fee = floor(half * 2 / 100)
//   - builderNet = half - fee
//   - remainder = reward - 2*half (0 or 1 ugnot)
//   - treasuryAmt = fee + remainder
// Invariant: sponsorAmt + builderNet + treasuryAmt == reward.
func CalcArbiterTimeoutSplit(reward int64) (sponsorAmt, builderNet, treasuryAmt int64) {
	if reward <= 0 {
		return 0, 0, 0
	}
	half := reward / 2
	fee := CalcProtocolFee(half)
	rem := reward - (2 * half)
	return half, half - fee, fee + rem
}

// ValidateContestShares ensures 1..MaxContestSlots shares, each >= MinContestSlotPct,
// summing to exactly 100.
func ValidateContestShares(pcts []int) error {
	if len(pcts) < 1 || len(pcts) > MaxContestSlots {
		return errors.New("contest winner slots must be between 1 and 10")
	}
	sum := 0
	for _, p := range pcts {
		if p < MinContestSlotPct || p > 100 {
			return errors.New("each contest winner share must be between 5% and 100%")
		}
		sum += p
	}
	if sum != 100 {
		return errors.New("contest winner shares must sum to 100%")
	}
	return nil
}

// CalcContestPayouts computes exact payouts for an Open Contest with filledCount winners
// (1 <= filledCount <= len(pcts)).
//   - Filled slot i < filledCount: gross = (R * pcts[i]) / 100, fee = (gross * 2) / 100, net = gross - fee.
//   - Unfilled slot j >= filledCount: refunded to sponsor without fee: (R * pcts[j]) / 100.
//   - Remainder: R - sum_all((R * pcts[i]) / 100) -> Treasury.
// Invariant: sum(winnerNets) + sponsorRefund + treasuryTotal == reward.
func CalcContestPayouts(reward int64, pcts []int, filledCount int) (winnerNets []int64, sponsorRefund int64, treasuryTotal int64, err error) {
	if err = ValidateReward(reward); err != nil {
		return nil, 0, 0, err
	}
	if err = ValidateContestShares(pcts); err != nil {
		return nil, 0, 0, err
	}
	if filledCount < 1 || filledCount > len(pcts) {
		return nil, 0, 0, errors.New("invalid filled winner count")
	}

	winnerNets = make([]int64, filledCount)
	var allocatedGross int64
	var totalFees int64

	for i, pct := range pcts {
		gross := (reward * int64(pct)) / 100
		allocatedGross += gross
		if i < filledCount {
			fee := CalcProtocolFee(gross)
			winnerNets[i] = gross - fee
			totalFees += fee
		} else {
			sponsorRefund += gross
		}
	}

	remainder := reward - allocatedGross
	treasuryTotal = totalFees + remainder
	return winnerNets, sponsorRefund, treasuryTotal, nil
}

// CalcContestEqualSplit computes the Pull-Payment equal split when both sponsor
// and arbiter time out on an Open Contest with submitterCount > 0.
//   - fee = (R * 2) / 100
//   - dist = R - fee
//   - perSubmitter = dist / submitterCount
//   - heldEscrow = perSubmitter * submitterCount
//   - remainder = dist - heldEscrow
//   - treasuryTotal = fee + remainder
// Invariant: heldEscrow + treasuryTotal == reward.
func CalcContestEqualSplit(reward int64, submitterCount int) (perSubmitter, heldEscrow, treasuryTotal int64, err error) {
	if err = ValidateReward(reward); err != nil {
		return 0, 0, 0, err
	}
	if submitterCount <= 0 || submitterCount > MaxContestSubmissions {
		return 0, 0, 0, errors.New("invalid submitter count")
	}
	fee := CalcProtocolFee(reward)
	dist := reward - fee
	n := int64(submitterCount)
	perSubmitter = dist / n
	heldEscrow = perSubmitter * n
	rem := dist - heldEscrow
	treasuryTotal = fee + rem
	return perSubmitter, heldEscrow, treasuryTotal, nil
}

// ValidateQuestDurations validates open, work, and review durations against contract bounds.
func ValidateQuestDurations(openDur, workDur, reviewDur int64) error {
	if openDur < MinOpenDurationSec || openDur > MaxOpenDurationSec {
		return errors.New("open duration must be between 24h and 90d")
	}
	if workDur < MinWorkDurationSec || workDur > MaxWorkDurationSec {
		return errors.New("work duration must be between 24h and 30d")
	}
	if reviewDur < MinReviewDurationSec || reviewDur > MaxReviewDurationSec {
		return errors.New("review duration must be between 24h and 7d")
	}
	return nil
}

// ValidateContestDurations validates submit (open) and judging durations.
func ValidateContestDurations(submitDur, judgingDur int64) error {
	if submitDur < MinOpenDurationSec || submitDur > MaxOpenDurationSec {
		return errors.New("submit duration must be between 24h and 90d")
	}
	if judgingDur < MinJudgingDurationSec || judgingDur > MaxJudgingDurationSec {
		return errors.New("judging duration must be between 24h and 14d")
	}
	return nil
}

// ClampPageLimit normalizes pagination parameters to safe bounds.
func ClampPageLimit(page, limit int) (int, int) {
	if page < 1 {
		page = 1
	}
	if limit <= 0 {
		limit = DefaultPageLimit
	}
	if limit > MaxPageLimit {
		limit = MaxPageLimit
	}
	return page, limit
}

package bs_core

import (
	"errors"
	"strings"
)

// ValidateText checks byte length, optional emptiness, and rejects unsafe control chars.
// Newlines (\n, \r) and tabs (\t) are permitted only when allowMultiline is true.
func ValidateText(s string, maxBytes int, required bool, allowMultiline bool) error {
	trimmed := strings.TrimSpace(s)
	if required && len(trimmed) == 0 {
		return errors.New("text field is required")
	}
	if len(s) > maxBytes {
		return errors.New("text field exceeds max byte length")
	}
	for i := 0; i < len(s); i++ {
		b := s[i]
		if b == 0x7f {
			return errors.New("text contains invalid control character")
		}
		if b < 0x20 {
			if allowMultiline && (b == '\n' || b == '\r' || b == '\t') {
				continue
			}
			return errors.New("text contains disallowed control character")
		}
	}
	return nil
}

// ValidateHTTPSURL enforces an https:// URL with no whitespace, control characters,
// or Markdown/HTML link-breakout characters.
func ValidateHTTPSURL(u string) error {
	if len(u) == 0 {
		return errors.New("URL is required")
	}
	if len(u) > MaxURLBytes {
		return errors.New("URL exceeds max byte length")
	}
	if !strings.HasPrefix(u, "https://") {
		return errors.New("URL must start with https://")
	}
	rest := u[len("https://"):]
	if len(rest) < 3 || !strings.Contains(rest, ".") {
		return errors.New("URL must contain a valid host")
	}
	for i := 0; i < len(u); i++ {
		b := u[i]
		if b <= 0x20 || b >= 0x7f {
			return errors.New("URL contains invalid or whitespace character")
		}
		switch b {
		case '<', '>', '"', '\'', '(', ')', '[', ']', '`', '\\':
			return errors.New("URL contains disallowed character")
		}
	}
	return nil
}

// EscapeMarkdown neutralizes Markdown/HTML injection in gnoweb Render() output.
func EscapeMarkdown(s string) string {
	var sb strings.Builder
	sb.Grow(len(s) + 16)
	for i := 0; i < len(s); i++ {
		c := s[i]
		switch c {
		case '\\', '`', '*', '_', '{', '}', '[', ']', '(', ')', '#', '+', '-', '!', '|':
			sb.WriteByte('\\')
			sb.WriteByte(c)
		case '<':
			sb.WriteString("&lt;")
		case '>':
			sb.WriteString("&gt;")
		case '&':
			sb.WriteString("&amp;")
		default:
			sb.WriteByte(c)
		}
	}
	return sb.String()
}

// EscapeJSON escapes a string safely for embedding inside JSON double quotes.
func EscapeJSON(s string) string {
	var sb strings.Builder
	sb.Grow(len(s) + 16)
	for i := 0; i < len(s); i++ {
		c := s[i]
		switch c {
		case '\\':
			sb.WriteString(`\\`)
		case '"':
			sb.WriteString(`\"`)
		case '\n':
			sb.WriteString(`\n`)
		case '\r':
			sb.WriteString(`\r`)
		case '\t':
			sb.WriteString(`\t`)
		case '<':
			sb.WriteString(`\u003c`)
		case '>':
			sb.WriteString(`\u003e`)
		default:
			if c < 0x20 {
				sb.WriteString(" ")
			} else {
				sb.WriteByte(c)
			}
		}
	}
	return sb.String()
}

package siege_rep

import (
	"sort"
	"strconv"
	"strings"

	"gno.land/p/g1fn0l3ms5puafp37r7v67mx2msjl0ztnyq3a9yv/bs_core"
)

func Render(path string) string {
	route, query := splitPathQuery(path)

	switch {
	case route == "json/leaderboard":
		page, limit := parsePageLimit(query)
		return renderLeaderboardJSON(page, limit)
	case route == "json/guilds":
		page, limit := parsePageLimit(query)
		return renderGuildsJSON(page, limit)
	case strings.HasPrefix(route, "json/profile/"):
		addrStr := strings.TrimPrefix(route, "json/profile/")
		return renderProfileJSON(address(addrStr))
	default:
		return renderMarkdownHome()
	}
}

func renderMarkdownHome() string {
	var sb strings.Builder
	sb.WriteString("# BountySiege — Composable Reputation & Guild Registry (`siege_rep`)\n\n")
	sb.WriteString("- Authorized Core Realm: `" + bs_core.EscapeMarkdown(authorizedCorePkgPath) + "`\n")
	sb.WriteString("- Registered Guilds: `" + strconv.Itoa(len(guildOwnerList)) + "`\n")
	sb.WriteString("- Indexed Builders: `" + strconv.Itoa(len(builderAddrList)) + "`\n\n")

	sb.WriteString("## Top Builders\n\n")
	sorted := sortedBuilders()
	if len(sorted) == 0 {
		sb.WriteString("_No builder reputation recorded yet._\n\n")
	} else {
		max := len(sorted)
		if max > 10 {
			max = 10
		}
		for i := 0; i < max; i++ {
			b := sorted[i]
			sb.WriteString(strconv.Itoa(i+1) + ". `" + b.Addr.String() + "` — **" +
				strconv.FormatInt(b.TotalXP, 10) + " XP** | Completed: `" +
				strconv.FormatInt(b.CompletedCount, 10) + "` | Unique Sponsors: `" +
				strconv.FormatInt(b.UniqueSponsorsCount, 10) + "` | Earned: `" +
				strconv.FormatInt(b.TotalEarnedUgnot, 10) + " ugnot`\n")
		}
		sb.WriteString("\n")
	}

	sb.WriteString("## Registered Guilds\n\n")
	if len(guildOwnerList) == 0 {
		sb.WriteString("_No guilds registered yet._\n")
	} else {
		max := len(guildOwnerList)
		if max > 10 {
			max = 10
		}
		for i := 0; i < max; i++ {
			g := guildsByOwner[guildOwnerList[i]]
			sp := sponsorsByAddr[g.Owner]
			var paid int64
			if sp != nil {
				paid = sp.TotalPaidUgnot
			}
			sb.WriteString("- **" + bs_core.EscapeMarkdown(g.Name) + "** (`" + g.Owner.String() +
				"`) — Paid Out: `" + strconv.FormatInt(paid, 10) + " ugnot`\n")
		}
	}
	return sb.String()
}

func renderLeaderboardJSON(page, limit int) string {
	sorted := sortedBuilders()
	total := len(sorted)
	start := (page - 1) * limit
	if start > total {
		start = total
	}
	end := start + limit
	if end > total {
		end = total
	}

	var sb strings.Builder
	sb.WriteString(`{"page":` + strconv.Itoa(page) +
		`,"limit":` + strconv.Itoa(limit) +
		`,"total":` + strconv.Itoa(total) + `,"items":[`)
	for i := start; i < end; i++ {
		if i > start {
			sb.WriteString(",")
		}
		sb.WriteString(builderToJSON(sorted[i]))
	}
	sb.WriteString("]}")
	return sb.String()
}

func renderGuildsJSON(page, limit int) string {
	total := len(guildOwnerList)
	start := (page - 1) * limit
	if start > total {
		start = total
	}
	end := start + limit
	if end > total {
		end = total
	}

	var sb strings.Builder
	sb.WriteString(`{"page":` + strconv.Itoa(page) +
		`,"limit":` + strconv.Itoa(limit) +
		`,"total":` + strconv.Itoa(total) + `,"items":[`)
	for i := start; i < end; i++ {
		if i > start {
			sb.WriteString(",")
		}
		g := guildsByOwner[guildOwnerList[i]]
		sb.WriteString(guildToJSON(g, sponsorsByAddr[g.Owner]))
	}
	sb.WriteString("]}")
	return sb.String()
}

func renderProfileJSON(addr address) string {
	bp := buildersByAddr[addr]
	sp := sponsorsByAddr[addr]
	g := guildsByOwner[addr]

	var sb strings.Builder
	sb.WriteString(`{"address":"` + bs_core.EscapeJSON(addr.String()) + `","builder":`)
	if bp == nil {
		sb.WriteString(builderToJSON(&BuilderProfile{Addr: addr}))
	} else {
		sb.WriteString(builderToJSON(bp))
	}
	sb.WriteString(`,"sponsor":`)
	if sp == nil {
		sb.WriteString(sponsorToJSON(&SponsorStats{Addr: addr}))
	} else {
		sb.WriteString(sponsorToJSON(sp))
	}
	sb.WriteString(`,"guild":`)
	if g == nil {
		sb.WriteString("null")
	} else {
		sb.WriteString(guildToJSON(g, sp))
	}
	sb.WriteString("}")
	return sb.String()
}

func builderToJSON(b *BuilderProfile) string {
	var sb strings.Builder
	sb.WriteString(`{"address":"` + bs_core.EscapeJSON(b.Addr.String()) +
		`","totalXp":` + strconv.FormatInt(b.TotalXP, 10) +
		`,"completedCount":` + strconv.FormatInt(b.CompletedCount, 10) +
		`,"qualifiedCompletedCount":` + strconv.FormatInt(b.QualifiedCompletedCount, 10) +
		`,"totalEarnedUgnot":` + strconv.FormatInt(b.TotalEarnedUgnot, 10) +
		`,"uniqueSponsorsCount":` + strconv.FormatInt(b.UniqueSponsorsCount, 10) +
		`,"noShowCount":` + strconv.FormatInt(b.NoShowCount, 10) +
		`,"rejectedCount":` + strconv.FormatInt(b.RejectedCount, 10) +
		`,"lostDisputeCount":` + strconv.FormatInt(b.LostDisputeCount, 10) +
		`,"revisionExpiredCount":` + strconv.FormatInt(b.RevisionExpiredCount, 10) +
		`,"xpByCategory":{`)
	for c := bs_core.Category(0); c < bs_core.CatCount; c++ {
		if c > 0 {
			sb.WriteString(",")
		}
		sb.WriteString(`"` + c.String() + `":` + strconv.FormatInt(b.XPByCategory[c], 10))
	}
	sb.WriteString(`},"badges":[`)
	for i, bg := range b.Badges {
		if i > 0 {
			sb.WriteString(",")
		}
		sb.WriteString(`"` + bs_core.EscapeJSON(bg) + `"`)
	}
	sb.WriteString("]}")
	return sb.String()
}

func sponsorToJSON(s *SponsorStats) string {
	var avgReview int64
	if s.ReviewedCount > 0 {
		avgReview = s.TotalReviewSeconds / s.ReviewedCount
	}
	return `{"address":"` + bs_core.EscapeJSON(s.Addr.String()) +
		`","totalPaidUgnot":` + strconv.FormatInt(s.TotalPaidUgnot, 10) +
		`,"completedCount":` + strconv.FormatInt(s.CompletedCount, 10) +
		`,"reviewedCount":` + strconv.FormatInt(s.ReviewedCount, 10) +
		`,"avgReviewSeconds":` + strconv.FormatInt(avgReview, 10) +
		`,"cancelledAfterSubmitCount":` + strconv.FormatInt(s.CancelledAfterSubmitCount, 10) +
		`,"timeoutCount":` + strconv.FormatInt(s.TimeoutCount, 10) +
		`,"lateJudgingCount":` + strconv.FormatInt(s.LateJudgingCount, 10) +
		`,"lostDisputeCount":` + strconv.FormatInt(s.LostDisputeCount, 10) +
		`,"uniqueBuildersCount":` + strconv.FormatInt(s.UniqueBuildersCount, 10) + `}`
}

func guildToJSON(g *Guild, sp *SponsorStats) string {
	if sp == nil {
		sp = &SponsorStats{Addr: g.Owner}
	}
	return `{"owner":"` + bs_core.EscapeJSON(g.Owner.String()) +
		`","name":"` + bs_core.EscapeJSON(g.Name) +
		`","bio":"` + bs_core.EscapeJSON(g.CurrentBio()) +
		`","website":"` + bs_core.EscapeJSON(g.CurrentWebsite()) +
		`","createdAt":` + strconv.FormatInt(g.CreatedAt, 10) +
		`,"updatesCount":` + strconv.Itoa(len(g.History)) +
		`,"stats":` + sponsorToJSON(sp) + `}`
}

type builderSorter []*BuilderProfile

func (s builderSorter) Len() int { return len(s) }
func (s builderSorter) Swap(i, j int) { s[i], s[j] = s[j], s[i] }
func (s builderSorter) Less(i, j int) bool {
	if s[i].TotalXP != s[j].TotalXP {
		return s[i].TotalXP > s[j].TotalXP
	}
	if s[i].UniqueSponsorsCount != s[j].UniqueSponsorsCount {
		return s[i].UniqueSponsorsCount > s[j].UniqueSponsorsCount
	}
	if s[i].CompletedCount != s[j].CompletedCount {
		return s[i].CompletedCount > s[j].CompletedCount
	}
	return s[i].Addr < s[j].Addr
}

func sortedBuilders() []*BuilderProfile {
	list := make([]*BuilderProfile, 0, len(builderAddrList))
	for _, a := range builderAddrList {
		list = append(list, buildersByAddr[a])
	}
	sort.Sort(builderSorter(list))
	return list
}

func splitPathQuery(p string) (string, string) {
	idx := strings.Index(p, "?")
	if idx == -1 {
		return p, ""
	}
	return p[:idx], p[idx+1:]
}

func parsePageLimit(query string) (int, int) {
	page := 1
	limit := bs_core.DefaultPageLimit
	if query == "" {
		return bs_core.ClampPageLimit(page, limit)
	}
	parts := strings.Split(query, "&")
	for _, kv := range parts {
		eq := strings.Index(kv, "=")
		if eq <= 0 {
			continue
		}
		k := kv[:eq]
		v := kv[eq+1:]
		if k == "page" {
			if n, err := strconv.Atoi(v); err == nil {
				page = n
			}
		} else if k == "limit" {
			if n, err := strconv.Atoi(v); err == nil {
				limit = n
			}
		}
	}
	return bs_core.ClampPageLimit(page, limit)
}

package siege_rep

import (
	"chain/runtime/unsafe"
	"strings"
	"time"

	"gno.land/p/g1fn0l3ms5puafp37r7v67mx2msjl0ztnyq3a9yv/bs_core"
)

var (
	deployer              address
	realmAddr             address
	authorizedCorePkgPath string

	guildsByOwner    = map[address]*Guild{}
	guildNameTaken   = map[string]bool{}
	guildOwnerList   []address

	buildersByAddr   = map[address]*BuilderProfile{}
	builderAddrList  []address

	sponsorsByAddr   = map[address]*SponsorStats{}
	sponsorAddrList  []address

	// Anti-wash-trading & uniqueness ledgers (append-only, never deleted).
	pairXP           = map[string]*pairXPRecord{}
	uniquePairSeen   = map[string]bool{}
)

func init(cur realm) {
	deployer = cur.Previous().Address()
	if deployer == "" {
		// Fallback only hit when imported lazily by gno filetest (Context == nil);
		// on-chain AddPackage always sets OriginCaller = creator.Bech32().
		deployer = address("g1fn0l3ms5puafp37r7v67mx2msjl0ztnyq3a9yv")
	}
	realmAddr = cur.Address()
}

// InitAuthorizedCore locks the single whitelisted bountysiege realm package path.
// Callable ONCE by deployer, non-payable, direct EOA only.
func InitAuthorizedCore(cur realm, corePkgPath string) {
	if !cur.Previous().IsUserCall() {
		panic("must be called directly by EOA")
	}
	if len(unsafe.OriginSend()) != 0 {
		panic("non-payable function: do not send coins")
	}
	if cur.Previous().Address() != deployer {
		panic("unauthorized: only deployer can initialize authorized core")
	}
	if authorizedCorePkgPath != "" {
		panic("authorized core already initialized")
	}
	trimmed := strings.TrimSpace(corePkgPath)
	if !strings.HasPrefix(trimmed, "gno.land/r/") || len(trimmed) > 200 {
		panic("invalid core realm package path")
	}
	authorizedCorePkgPath = trimmed
}

// RegisterGuild creates a Guild / Sponsor Space profile owned by cur.Previous().Address().
func RegisterGuild(cur realm, name, bio, website string) {
	if !cur.Previous().IsUserCall() {
		panic("must be called directly by EOA")
	}
	if len(unsafe.OriginSend()) != 0 {
		panic("non-payable function: do not send coins")
	}
	owner := cur.Previous().Address()
	if _, exists := guildsByOwner[owner]; exists {
		panic("guild already registered for this address")
	}
	if err := bs_core.ValidateText(name, bs_core.MaxGuildNameBytes, true, false); err != nil {
		panic("invalid guild name: " + err.Error())
	}
	if err := bs_core.ValidateText(bio, bs_core.MaxGuildBioBytes, false, true); err != nil {
		panic("invalid guild bio: " + err.Error())
	}
	if website != "" {
		if err := bs_core.ValidateHTTPSURL(website); err != nil {
			panic("invalid guild website: " + err.Error())
		}
	}

	cleanName := strings.TrimSpace(name)
	lowerKey := strings.ToLower(cleanName)
	if guildNameTaken[lowerKey] {
		panic("guild name already taken")
	}

	now := time.Now().Unix()
	g := &Guild{
		Owner:     owner,
		Name:      cleanName,
		CreatedAt: now,
		History: []GuildSnapshot{
			{
				Bio:       strings.TrimSpace(bio),
				Website:   website,
				UpdatedAt: now,
			},
		},
	}
	guildsByOwner[owner] = g
	guildNameTaken[lowerKey] = true
	guildOwnerList = append(guildOwnerList, owner)
}

// UpdateGuild appends a new snapshot to the caller's Guild history.
// Append-only guarantees bytes_delta >= 0 (no storage shrink).
func UpdateGuild(cur realm, bio, website string) {
	if !cur.Previous().IsUserCall() {
		panic("must be called directly by EOA")
	}
	if len(unsafe.OriginSend()) != 0 {
		panic("non-payable function: do not send coins")
	}
	owner := cur.Previous().Address()
	g, exists := guildsByOwner[owner]
	if !exists {
		panic("guild not found for caller")
	}
	if err := bs_core.ValidateText(bio, bs_core.MaxGuildBioBytes, false, true); err != nil {
		panic("invalid guild bio: " + err.Error())
	}
	if website != "" {
		if err := bs_core.ValidateHTTPSURL(website); err != nil {
			panic("invalid guild website: " + err.Error())
		}
	}
	g.History = append(g.History, GuildSnapshot{
		Bio:       strings.TrimSpace(bio),
		Website:   website,
		UpdatedAt: time.Now().Unix(),
	})
}

//----------------------------------------
// Authorized Core Recorder Functions (Opsi A: Total / Non-Panicking beyond auth)
//----------------------------------------

func assertAuthorizedCore(_ int, rlm realm) {
	if authorizedCorePkgPath == "" || rlm.Previous().PkgPath() != authorizedCorePkgPath {
		panic("unauthorized caller realm")
	}
}

// RecordQuestCompleted records a completed Single-Claim Quest or Co-op Raid slot.
// Total function after auth check: never panics on any input.
func RecordQuestCompleted(
	cur realm,
	sponsor address,
	builder address,
	cat uint8,
	reward int64,
	reviewSecs int64,
	isRaid bool,
	isTimeout bool,
) {
	assertAuthorizedCore(0, cur)
	if sponsor == "" || builder == "" || sponsor == builder {
		return
	}
	if reward < 0 {
		reward = 0
	}
	if reviewSecs < 0 {
		reviewSecs = 0
	}
	c := bs_core.Category(cat)
	if !c.IsValid() {
		c = bs_core.CatContract
	}

	now := time.Now().Unix()
	bp := getOrCreateBuilder(builder)
	sp := getOrCreateSponsor(sponsor)

	bp.CompletedCount = bs_core.SafeAdd64(bp.CompletedCount, 1)
	bp.TotalEarnedUgnot = bs_core.SafeAdd64(bp.TotalEarnedUgnot, reward)

	sp.CompletedCount = bs_core.SafeAdd64(sp.CompletedCount, 1)
	sp.TotalPaidUgnot = bs_core.SafeAdd64(sp.TotalPaidUgnot, reward)
	if isTimeout {
		sp.TimeoutCount = bs_core.SafeAdd64(sp.TimeoutCount, 1)
	} else {
		sp.ReviewedCount = bs_core.SafeAdd64(sp.ReviewedCount, 1)
		sp.TotalReviewSeconds = bs_core.SafeAdd64(sp.TotalReviewSeconds, reviewSecs)
	}

	awardUniqueAndXP(bp, sp, sponsor, builder, c, reward, now, isRaid, false)
}

// RecordContestWinners records payouts & reputation for Open Contest winners.
// Total function after auth check: never panics on any input.
func RecordContestWinners(
	cur realm,
	sponsor address,
	winners []address,
	cat uint8,
	payouts []int64,
) {
	assertAuthorizedCore(0, cur)
	if sponsor == "" || len(winners) == 0 {
		return
	}
	c := bs_core.Category(cat)
	if !c.IsValid() {
		c = bs_core.CatContract
	}
	now := time.Now().Unix()
	sp := getOrCreateSponsor(sponsor)
	sp.CompletedCount = bs_core.SafeAdd64(sp.CompletedCount, 1)

	limit := len(winners)
	if len(payouts) < limit {
		limit = len(payouts)
	}
	for i := 0; i < limit; i++ {
		w := winners[i]
		p := payouts[i]
		if w == "" || w == sponsor {
			continue
		}
		if p < 0 {
			p = 0
		}
		bp := getOrCreateBuilder(w)
		bp.CompletedCount = bs_core.SafeAdd64(bp.CompletedCount, 1)
		bp.TotalEarnedUgnot = bs_core.SafeAdd64(bp.TotalEarnedUgnot, p)
		sp.TotalPaidUgnot = bs_core.SafeAdd64(sp.TotalPaidUgnot, p)

		awardUniqueAndXP(bp, sp, sponsor, w, c, p, now, false, true)
	}
}

