func (c *Contest) effectiveStatus(now int64) bs_core.ContestStatus {
	if c.Status == bs_core.ContestOpen && now > c.SubmitDeadline && len(c.Entries) > 0 {
		return bs_core.ContestJudging
	}
	return c.Status
}

var (
	nextContestID uint64
	contestsByID  = map[uint64]*Contest{}
	contestIDs    []uint64
)

// CreateContest creates a multi-winner Open Contest and escrows exact `reward` ugnot.
// `sharesCSV` is a comma-separated list of integer percentages summing to 100 (e.g. "50,30,20").
func CreateContest(
	cur realm,
	title, description, criteria string,
	cat uint8,
	reward int64,
	sharesCSV string,
	submitDur, judgingDur int64,
) uint64 {
	requireRolesInitialized()
	requireExactUgnot(reward, cur)

	if err := bs_core.ValidateReward(reward); err != nil {
		panic(err.Error())
	}
	if err := bs_core.ValidateContestDurations(submitDur, judgingDur); err != nil {
		panic(err.Error())
	}
	shares := parseSharesCSV(sharesCSV)
	if err := bs_core.ValidateContestShares(shares); err != nil {
		panic(err.Error())
	}
	category := bs_core.Category(cat)
	if !category.IsValid() {
		panic("invalid skill category")
	}
	if err := bs_core.ValidateText(title, bs_core.MaxTitleBytes, true, false); err != nil {
		panic("invalid title: " + err.Error())
	}
	if err := bs_core.ValidateText(description, bs_core.MaxDescBytes, true, true); err != nil {
		panic("invalid description: " + err.Error())
	}
	if err := bs_core.ValidateText(criteria, bs_core.MaxCriteriaBytes, true, true); err != nil {
		panic("invalid acceptance criteria: " + err.Error())
	}

	sponsor := cur.Previous().Address()
	now := time.Now().Unix()

	nextContestID++
	id := nextContestID
	c := &Contest{
		ID:              id,
		Sponsor:         sponsor,
		Title:           strings.TrimSpace(title),
		Description:     strings.TrimSpace(description),
		Criteria:        strings.TrimSpace(criteria),
		Category:        category,
		Reward:          reward,
		WinnerShares:    shares,
		CreatedAt:       now,
		SubmitDeadline:  now + submitDur,
		JudgingDeadline: now + submitDur + judgingDur,
		Status:          bs_core.ContestOpen,
		EscrowHeld:      reward,
		entryIdxByAddr:  map[address]int{},
	}
	c.addEvent(now, sponsor, "CREATED", "reward="+strconv.FormatInt(reward, 10)+"ugnot shares="+sharesCSV)

	contestsByID[id] = c
	contestIDs = append(contestIDs, id)
	totalActiveEscrow += reward
	return id
}

// CancelContest cancels an Open Contest ONLY while submissionCount == 0.
func CancelContest(cur realm, contestID uint64) {
	requireNonPayableEOA(0, cur)
	c := mustGetContest(contestID)
	caller := cur.Previous().Address()
	if caller != c.Sponsor {
		panic("unauthorized: only sponsor can cancel contest")
	}
	if c.Status != bs_core.ContestOpen {
		panic("contest is not Open")
	}
	if len(c.Entries) > 0 {
		panic("cannot cancel contest after submissions have been received")
	}
	refund := c.Reward
	c.Status = bs_core.ContestCancelled
	c.EscrowHeld -= refund
	totalActiveEscrow -= refund
	c.addEvent(time.Now().Unix(), caller, "CANCELLED", "refund="+strconv.FormatInt(refund, 10)+"ugnot")

	sendUgnot(c.Sponsor, refund, cur)
}

// ExpireOpenContest allows anyone to refund 100% reward (no fee) when submitDeadline
// passes with 0 submissions.
func ExpireOpenContest(cur realm, contestID uint64) {
	requireNonPayableEOA(0, cur)
	c := mustGetContest(contestID)
	if c.Status != bs_core.ContestOpen {
		panic("contest is not Open")
	}
	now := time.Now().Unix()
	if now <= c.SubmitDeadline {
		panic("submitDeadline has not elapsed yet")
	}
	if len(c.Entries) > 0 {
		panic("contest has submissions; must proceed to judging or escalation")
	}
	refund := c.Reward
	c.Status = bs_core.ContestCancelled
	c.EscrowHeld -= refund
	totalActiveEscrow -= refund
	c.addEvent(now, cur.Previous().Address(), "EXPIRED_OPEN", "refund="+strconv.FormatInt(refund, 10)+"ugnot")

	sendUgnot(c.Sponsor, refund, cur)
}

// SubmitContestEntry submits (or appends an update to) a contest entry before submitDeadline.
// No stake required; max 1 submitter entry per address, max 200 unique submitters.
func SubmitContestEntry(cur realm, contestID uint64, proofURL, note string) {
	requireNonPayableEOA(0, cur)
	c := mustGetContest(contestID)
	if c.Status != bs_core.ContestOpen {
		panic("contest is not Open for submissions")
	}
	now := time.Now().Unix()
	if now > c.SubmitDeadline {
		panic("submitDeadline has passed")
	}
	submitter := cur.Previous().Address()
	if submitter == c.Sponsor {
		panic("self-dealing forbidden: sponsor cannot submit to own contest")
	}
	if isExcludedWorkerRole(submitter) {
		panic("arbiter and treasury addresses cannot submit to contests")
	}
	if err := bs_core.ValidateHTTPSURL(proofURL); err != nil {
		panic("invalid proof URL: " + err.Error())
	}
	if err := bs_core.ValidateText(note, bs_core.MaxNoteBytes, true, true); err != nil {
		panic("invalid proof note: " + err.Error())
	}

	if idx, exists := c.entryIdxByAddr[submitter]; exists {
		// Append-only update guarantees bytes_delta >= 0
		entry := &c.Entries[idx]
		entry.Proofs = append(entry.Proofs, ProofEntry{
			URL:         proofURL,
			Note:        strings.TrimSpace(note),
			SubmittedAt: now,
			RevisionIdx: len(entry.Proofs),
		})
		c.addEvent(now, submitter, "ENTRY_UPDATED", "version="+strconv.Itoa(len(entry.Proofs)))
		return
	}

	if len(c.Entries) >= bs_core.MaxContestSubmissions {
		panic("maximum contest submissions (200) reached")
	}
	entry := ContestEntry{
		Submitter: submitter,
		Proofs: []ProofEntry{
			{
				URL:         proofURL,
				Note:        strings.TrimSpace(note),
				SubmittedAt: now,
				RevisionIdx: 0,
			},
		},
	}
	c.Entries = append(c.Entries, entry)
	c.entryIdxByAddr[submitter] = len(c.Entries) - 1
	c.addEvent(now, submitter, "ENTRY_SUBMITTED", "entries="+strconv.Itoa(len(c.Entries)))
}

// FinalizeWinners lets the sponsor select `min(len(WinnerShares), len(Entries))`
// distinct registered submitters after submitDeadline and before judgingDeadline.
func FinalizeWinners(cur realm, contestID uint64, winnersCSV string) {
	requireNonPayableEOA(0, cur)
	c := mustGetContest(contestID)
	caller := cur.Previous().Address()
	if caller != c.Sponsor {
		panic("unauthorized: only sponsor can finalize contest winners")
	}
	if c.Status != bs_core.ContestOpen {
		panic("contest cannot be finalized in current state")
	}
	now := time.Now().Unix()
	if now <= c.SubmitDeadline {
		panic("cannot finalize winners before submitDeadline")
	}
	if now > c.JudgingDeadline {
		panic("judgingDeadline has passed; contest must be escalated to arbiter")
	}
	if len(c.Entries) == 0 {
		panic("no submissions to judge; use ExpireOpenContest")
	}

	winners := parseAndValidateWinners(c, winnersCSV)
	distributeContestWinners(c, winners, caller, "FINALIZED_WINNERS", now, cur)
}

// EscalateContest allows anyone (WITHOUT dispute fee) to escalate an Open Contest
// to the arbiter if the sponsor misses judgingDeadline while submissions exist.
func EscalateContest(cur realm, contestID uint64) {
	requireNonPayableEOA(0, cur)
	c := mustGetContest(contestID)
	if c.Status != bs_core.ContestOpen {
		panic("contest cannot be escalated in current state")
	}
	now := time.Now().Unix()
	if now <= c.JudgingDeadline {
		panic("judgingDeadline has not elapsed yet")
	}
	if len(c.Entries) == 0 {
		panic("no submissions exist; use ExpireOpenContest instead")
	}

	c.LockedArbiter = arbiter
	c.DisputedAt = now
	c.DisputeDeadline = now + bs_core.ArbiterTimeoutSec
	c.Status = bs_core.ContestDisputed
	c.addEvent(now, cur.Previous().Address(), "ESCALATED", "arbiter="+arbiter.String())

	if repRecordingEnabled {
		siege_rep.RecordLateJudging(cross(cur), c.Sponsor)
	}
}

// ArbiterResolveContest lets ONLY the contest's lockedArbiter pick valid winners
// from existing submitters according to the contest's share structure.
func ArbiterResolveContest(cur realm, contestID uint64, winnersCSV, resolutionNote string) {
	requireNonPayableEOA(0, cur)
	c := mustGetContest(contestID)
	if c.Status != bs_core.ContestDisputed {
		panic("contest is not Disputed/Escalated")
	}
	caller := cur.Previous().Address()
	if caller != c.LockedArbiter {
		panic("unauthorized: only locked arbiter can resolve escalated contest")
	}
	now := time.Now().Unix()
	if now > c.DisputeDeadline {
		panic("arbiter 7-day deadline has passed; anyone may trigger ExpireContestDispute")
	}
	if err := bs_core.ValidateText(resolutionNote, bs_core.MaxNoteBytes, true, true); err != nil {
		panic("resolution note is required: " + err.Error())
	}

	winners := parseAndValidateWinners(c, winnersCSV)
	c.ResolutionNote = strings.TrimSpace(resolutionNote)
	distributeContestWinners(c, winners, caller, "ARBITER_RESOLVED_WINNERS", now, cur)
}

// ArbiterRefundContest lets ONLY the contest's lockedArbiter refund 100% reward
// to sponsor if all submissions are spam/invalid.
func ArbiterRefundContest(cur realm, contestID uint64, resolutionNote string) {
	requireNonPayableEOA(0, cur)
	c := mustGetContest(contestID)
	if c.Status != bs_core.ContestDisputed {
		panic("contest is not Disputed/Escalated")
	}
	caller := cur.Previous().Address()
	if caller != c.LockedArbiter {
		panic("unauthorized: only locked arbiter can refund escalated contest")
	}
	now := time.Now().Unix()
	if now > c.DisputeDeadline {
		panic("arbiter 7-day deadline has passed; anyone may trigger ExpireContestDispute")
	}
	if err := bs_core.ValidateText(resolutionNote, bs_core.MaxNoteBytes, true, true); err != nil {
		panic("resolution note is required: " + err.Error())
	}

	refund := c.Reward
	c.ResolutionNote = strings.TrimSpace(resolutionNote)
	c.Status = bs_core.ContestCancelled
	c.EscrowHeld -= refund
	totalActiveEscrow -= refund
	c.addEvent(now, caller, "ARBITER_REFUNDED", "refund="+strconv.FormatInt(refund, 10)+"ugnot")

	sendUgnot(c.Sponsor, refund, cur)
}

// ExpireContestDispute enables Pull-Payment equal split across all submitters
// if the arbiter also times out (> 7 days). 2% fee + integer remainder go to Treasury,
// and unclaimed shares expire after 30 days (SweepExpiredContestSplit).
func ExpireContestDispute(cur realm, contestID uint64) {
	requireNonPayableEOA(0, cur)
	c := mustGetContest(contestID)
	if c.Status != bs_core.ContestDisputed {
		panic("contest is not Disputed/Escalated")
	}
	now := time.Now().Unix()
	if now <= c.DisputeDeadline {
		panic("arbiter 7-day deadline has not elapsed yet")
	}

	per, heldEscrow, trTotal, err := bs_core.CalcContestEqualSplit(c.Reward, len(c.Entries))
	if err != nil {
		panic(err.Error())
	}

	// Checks-Effects-Interactions: only treasury portion leaves active escrow now;
	// `heldEscrow` stays locked in c.EscrowHeld for Pull-Payment claims!
	c.Status = bs_core.ContestResolvedTimeout
	c.PerSubmitterSplit = per
	c.ClaimDeadline = now + bs_core.PullPaymentClaimExpiry
	c.EscrowHeld = heldEscrow
	totalActiveEscrow -= trTotal
	treasuryBalance += trTotal
	c.addEvent(now, cur.Previous().Address(), "CONTEST_ARBITER_TIMEOUT", "per_submitter="+strconv.FormatInt(per, 10)+" treasury="+strconv.FormatInt(trTotal, 10))
}

// ClaimContestSplit lets each registered submitter pull their equal split once
// within the 30-day claim window (no loop gas limit!).
func ClaimContestSplit(cur realm, contestID uint64) {
	requireNonPayableEOA(0, cur)
	c := mustGetContest(contestID)
	if c.Status != bs_core.ContestResolvedTimeout {
		panic("contest is not in ResolvedTimeout Pull-Payment state")
	}
	now := time.Now().Unix()
	if now > c.ClaimDeadline || c.Swept {
		panic("30-day pull-payment claim window has expired")
	}
	caller := cur.Previous().Address()
	idx, ok := c.entryIdxByAddr[caller]
	if !ok {
		panic("unauthorized: caller is not a registered submitter for this contest")
	}
	entry := &c.Entries[idx]
	if entry.Claimed {
		panic("split share already claimed")
	}

	amt := c.PerSubmitterSplit
	entry.Claimed = true
	c.EscrowHeld -= amt
	totalActiveEscrow -= amt
	totalPaidOut += amt
	c.addEvent(now, caller, "SPLIT_CLAIMED", "amount="+strconv.FormatInt(amt, 10)+"ugnot")

	sendUgnot(caller, amt, cur)
}

// SweepExpiredContestSplit lets anyone sweep unclaimed Pull-Payment funds into
// treasuryBalance after the 30-day claim window expires (zero state deletions!).
func SweepExpiredContestSplit(cur realm, contestID uint64) {
	requireNonPayableEOA(0, cur)
	c := mustGetContest(contestID)
	if c.Status != bs_core.ContestResolvedTimeout {
		panic("contest is not in ResolvedTimeout state")
	}
	now := time.Now().Unix()
	if now <= c.ClaimDeadline {
		panic("30-day claim window has not expired yet")
	}
	if c.Swept || c.EscrowHeld == 0 {
		panic("no unclaimed escrow remaining to sweep")
	}

	rem := c.EscrowHeld
	c.EscrowHeld = 0
	c.Swept = true
	totalActiveEscrow -= rem
	treasuryBalance += rem
	c.addEvent(now, cur.Previous().Address(), "SPLIT_SWEPT_TO_TREASURY", "amount="+strconv.FormatInt(rem, 10)+"ugnot")
}

//----------------------------------------
// Contest Helpers (Non-crossing; rlm is NEVER param #1)
//----------------------------------------

func distributeContestWinners(c *Contest, winners []address, actor address, action string, now int64, rlm realm) {
	winnerNets, sponsorRefund, treasuryTotal, err := bs_core.CalcContestPayouts(c.Reward, c.WinnerShares, len(winners))
	if err != nil {
		panic(err.Error())
	}

	// Gross payouts for reputation tracking (each filled slot's gross award)
	grossPayouts := make([]int64, len(winners))
	var totalGrossPaid int64
	for i := range winners {
		g := (c.Reward * int64(c.WinnerShares[i])) / 100
		grossPayouts[i] = g
		totalGrossPaid += g
	}

	// Checks-Effects-Interactions: settle all ledgers BEFORE any coin send or cross-realm call.
	reward := c.Reward
	c.Status = bs_core.ContestCompleted
	c.Winners = winners
	c.WinnerPayouts = winnerNets
	c.EscrowHeld -= reward
	totalActiveEscrow -= reward
	treasuryBalance += treasuryTotal
	totalPaidOut += totalGrossPaid
	c.addEvent(now, actor, action, "winners="+strconv.Itoa(len(winners))+" sponsor_refund="+strconv.FormatInt(sponsorRefund, 10)+" treasury="+strconv.FormatInt(treasuryTotal, 10))

	for i, w := range winners {
		sendUgnot(w, winnerNets[i], rlm)
	}
	if sponsorRefund > 0 {
		sendUgnot(c.Sponsor, sponsorRefund, rlm)
	}
	if repRecordingEnabled {
		siege_rep.RecordContestWinners(cross(rlm), c.Sponsor, winners, uint8(c.Category), grossPayouts)
	}
}

func parseSharesCSV(csv string) []int {
	trimmed := strings.TrimSpace(csv)
	if trimmed == "" {
		panic("winner shares CSV is required")
	}
	parts := strings.Split(trimmed, ",")
	out := make([]int, 0, len(parts))
	for _, p := range parts {
		n, err := strconv.Atoi(strings.TrimSpace(p))
		if err != nil {
			panic("invalid integer in sharesCSV: " + p)
		}
		out = append(out, n)
	}
	return out
}

func parseAndValidateWinners(c *Contest, csv string) []address {
	trimmed := strings.TrimSpace(csv)
	if trimmed == "" {
		panic("winners CSV is required")
	}
	parts := strings.Split(trimmed, ",")
	expected := len(c.WinnerShares)
	if len(c.Entries) < expected {
		expected = len(c.Entries)
	}
	if len(parts) != expected {
		panic("must select exactly " + strconv.Itoa(expected) + " unique winners")
	}
	seen := map[address]bool{}
	winners := make([]address, 0, expected)
	for _, p := range parts {
		w := address(strings.TrimSpace(p))
		if _, ok := c.entryIdxByAddr[w]; !ok {
			panic("selected winner is not a registered submitter: " + w.String())
		}
		if seen[w] {
			panic("duplicate winner address: " + w.String())
		}
		seen[w] = true
		winners = append(winners, w)
	}
	return winners
}

func mustGetContest(id uint64) *Contest {
	c, ok := contestsByID[id]
	if !ok {
		panic("contest not found: " + strconv.FormatUint(id, 10))
	}
	return c
}

func ContestCount() int {
	return len(contestIDs)
}

package bountysiege

import (
	"strconv"
	"strings"
	"time"

	"gno.land/p/g1fn0l3ms5puafp37r7v67mx2msjl0ztnyq3a9yv/bs_core"
	"gno.land/r/g1fn0l3ms5puafp37r7v67mx2msjl0ztnyq3a9yv/siege_rep"
)

var (
	nextQuestID uint64
	questsByID  = map[uint64]*Quest{}
	questIDs    []uint64
)

// CreateQuest creates a new Single-Claim Quest and escrows exact `reward` ugnot.
func CreateQuest(
	cur realm,
	title, description, criteria string,
	cat uint8,
	reward, stake int64,
	openDur, workDur, reviewDur int64,
) uint64 {
	requireRolesInitialized()
	requireExactUgnot(reward, cur)

	if err := bs_core.ValidateStakeBounds(reward, stake); err != nil {
		panic(err.Error())
	}
	if err := bs_core.ValidateQuestDurations(openDur, workDur, reviewDur); err != nil {
		panic(err.Error())
	}
	category := bs_core.Category(cat)
	if !category.IsValid() {
		panic("invalid skill category")
	}
	if err := bs_core.ValidateText(title, bs_core.MaxTitleBytes, true, false); err != nil {
		panic("invalid title: " + err.Error())
	}
	if err := bs_core.ValidateText(description, bs_core.MaxDescBytes, true, true); err != nil {
		panic("invalid description: " + err.Error())
	}
	if err := bs_core.ValidateText(criteria, bs_core.MaxCriteriaBytes, true, true); err != nil {
		panic("invalid acceptance criteria: " + err.Error())
	}

	sponsor := cur.Previous().Address()
	now := time.Now().Unix()

	nextQuestID++
	id := nextQuestID
	q := &Quest{
		ID:               id,
		Sponsor:          sponsor,
		Title:            strings.TrimSpace(title),
		Description:      strings.TrimSpace(description),
		Criteria:         strings.TrimSpace(criteria),
		Category:         category,
		Reward:           reward,
		Stake:            stake,
		OpenDuration:     openDur,
		WorkDuration:     workDur,
		ReviewDuration:   reviewDur,
		CreatedAt:        now,
		OpenDeadline:     now + openDur,
		Status:           bs_core.QuestOpen,
		EscrowHeld:       reward,
		ActiveAttemptIdx: -1,
	}
	q.addEvent(now, sponsor, "CREATED", "reward="+strconv.FormatInt(reward, 10)+"ugnot stake="+strconv.FormatInt(stake, 10)+"ugnot")

	questsByID[id] = q
	questIDs = append(questIDs, id)
	totalActiveEscrow += reward
	return id
}

// CancelQuest cancels an Open Quest (no active claimer) and refunds 100% reward to sponsor.
// Strictly forbidden during InProgress, RevisionRequested, or UnderReview.
func CancelQuest(cur realm, questID uint64) {
	requireNonPayableEOA(0, cur)
	q := mustGetQuest(questID)
	cancelQuestCore(q, cur)
}

func cancelQuestCore(q *Quest, rlm realm) {
	caller := rlm.Previous().Address()
	if caller != q.Sponsor {
		panic("unauthorized: only sponsor can cancel quest")
	}
	if q.Status != bs_core.QuestOpen {
		panic("cannot cancel quest unless status is Open")
	}
	refund := q.Reward
	q.Status = bs_core.QuestCancelled
	q.EscrowHeld -= refund
	totalActiveEscrow -= refund
	q.addEvent(time.Now().Unix(), caller, "CANCELLED", "refund="+strconv.FormatInt(refund, 10)+"ugnot")

	sendUgnot(q.Sponsor, refund, rlm)
}

// ExpireOpenQuest allows anyone to expire an Open Quest after openDeadline,
// refunding 100% reward to sponsor without protocol fee.
func ExpireOpenQuest(cur realm, questID uint64) {
	requireNonPayableEOA(0, cur)
	q := mustGetQuest(questID)
	expireOpenQuestCore(q, cur)
}

func expireOpenQuestCore(q *Quest, rlm realm) {
	if q.Status != bs_core.QuestOpen {
		panic("quest is not Open")
	}
	now := time.Now().Unix()
	if now <= q.OpenDeadline {
		panic("openDeadline has not elapsed yet")
	}
	refund := q.Reward
	q.Status = bs_core.QuestCancelled
	q.EscrowHeld -= refund
	totalActiveEscrow -= refund
	q.addEvent(now, rlm.Previous().Address(), "EXPIRED_OPEN", "refund="+strconv.FormatInt(refund, 10)+"ugnot")

	sendUgnot(q.Sponsor, refund, rlm)
}

// ClaimQuest locks the exact anti-squatter Stake from a builder and transitions Open -> InProgress.
func ClaimQuest(cur realm, questID uint64) {
	q := mustGetQuest(questID)
	claimQuestCore(q, cur)
}

func claimQuestCore(q *Quest, rlm realm) {
	requireExactUgnot(q.Stake, rlm)
	if q.Status != bs_core.QuestOpen {
		panic("quest is not Open for claiming")
	}
	now := time.Now().Unix()
	if now > q.OpenDeadline {
		panic("quest openDeadline has passed")
	}
	builder := rlm.Previous().Address()
	if builder == q.Sponsor {
		panic("self-dealing forbidden: sponsor cannot claim own quest")
	}
	if isExcludedWorkerRole(builder) {
		panic("arbiter and treasury addresses cannot act as builders")
	}

	attempt := QuestAttempt{
		Builder:      builder,
		ClaimedAt:    now,
		WorkDeadline: now + q.WorkDuration,
		Outcome:      bs_core.AttemptActive,
	}
	q.Attempts = append(q.Attempts, attempt)
	q.ActiveAttemptIdx = len(q.Attempts) - 1
	q.Status = bs_core.QuestInProgress
	q.EscrowHeld += q.Stake
	totalActiveEscrow += q.Stake
	q.addEvent(now, builder, "CLAIMED", "stake="+strconv.FormatInt(q.Stake, 10)+"ugnot")
}

// ExpireClaim allows anyone to slash a no-show builder's stake (100% to Treasury)
// if workDeadline passes during initial InProgress (before any submission) and reopen the quest.
func ExpireClaim(cur realm, questID uint64) {
	requireNonPayableEOA(0, cur)
	q := mustGetQuest(questID)
	expireClaimCore(q, cur)
}

func expireClaimCore(q *Quest, rlm realm) {
	if q.Status != bs_core.QuestInProgress {
		panic("ExpireClaim only applies to InProgress (no-show before first submission)")
	}
	att := q.activeAttempt()
	if att == nil {
		panic("missing active attempt")
	}
	now := time.Now().Unix()
	if now <= att.WorkDeadline {
		panic("workDeadline has not elapsed yet")
	}

	builder := att.Builder
	slashed := q.Stake

	// Checks-Effects-Interactions (append-only: ActiveAttemptIdx = -1, zero deletions!)
	att.Outcome = bs_core.AttemptNoShow
	q.ActiveAttemptIdx = -1
	q.Status = bs_core.QuestOpen
	q.EscrowHeld -= slashed
	totalActiveEscrow -= slashed
	treasuryBalance += slashed
	q.addEvent(now, rlm.Previous().Address(), "EXPIRED_CLAIM", "no_show="+builder.String()+" stake_to_treasury="+strconv.FormatInt(slashed, 10))

	if repRecordingEnabled {
		siege_rep.RecordNoShow(cross(rlm), builder)
	}
}

// SubmitWork submits proof (https:// URL + note) during InProgress or RevisionRequested.
func SubmitWork(cur realm, questID uint64, proofURL, note string) {
	requireNonPayableEOA(0, cur)
	q := mustGetQuest(questID)
	submitWorkCore(q, proofURL, note, cur)
}

func submitWorkCore(q *Quest, proofURL, note string, rlm realm) {
	if q.Status != bs_core.QuestInProgress && q.Status != bs_core.QuestRevisionRequested {
		panic("quest is not accepting work submissions")
	}
	att := q.activeAttempt()
	if att == nil || rlm.Previous().Address() != att.Builder {
		panic("unauthorized: only active builder can submit work")
	}
	now := time.Now().Unix()
	if now > att.WorkDeadline {
		panic("workDeadline has passed")
	}
	if err := bs_core.ValidateHTTPSURL(proofURL); err != nil {
		panic("invalid proof URL: " + err.Error())
	}
	if err := bs_core.ValidateText(note, bs_core.MaxNoteBytes, true, true); err != nil {
		panic("invalid proof note: " + err.Error())
	}

	att.Proofs = append(att.Proofs, ProofEntry{
		URL:         proofURL,
		Note:        strings.TrimSpace(note),
		SubmittedAt: now,
		RevisionIdx: att.RevisionCount,
	})
	att.SubmittedAt = now
	att.ReviewDeadline = now + q.ReviewDuration
	q.Status = bs_core.QuestUnderReview
	q.addEvent(now, att.Builder, "SUBMITTED", "rev="+strconv.Itoa(att.RevisionCount))
}

// ApproveQuest approves the submission before reviewDeadline and pays out Reward (minus 2% fee) + 100% Stake.
func ApproveQuest(cur realm, questID uint64) {
	requireNonPayableEOA(0, cur)
	q := mustGetQuest(questID)
	approveQuestCore(q, false, cur)
}

func approveQuestCore(q *Quest, isRaid bool, rlm realm) {
	if q.Status != bs_core.QuestUnderReview {
		panic("quest is not UnderReview")
	}
	caller := rlm.Previous().Address()
	if caller != q.Sponsor {
		panic("unauthorized: only sponsor can approve quest")
	}
	att := q.activeAttempt()
	if att == nil {
		panic("missing active attempt")
	}
	now := time.Now().Unix()
	if now > att.ReviewDeadline {
		panic("reviewDeadline has passed; builder may trigger TimeoutClaim")
	}

	fee := bs_core.CalcProtocolFee(q.Reward)
	builderNet := q.Reward - fee
	totalToBuilder := builderNet + q.Stake
	released := q.Reward + q.Stake
	reviewSecs := now - att.SubmittedAt
	if reviewSecs < 0 {
		reviewSecs = 0
	}

	// Checks-Effects-Interactions
	att.Outcome = bs_core.AttemptApproved
	q.Status = bs_core.QuestCompleted
	q.EscrowHeld -= released
	totalActiveEscrow -= released
	treasuryBalance += fee
	totalPaidOut += q.Reward
	q.addEvent(now, caller, "APPROVED", "builder_net="+strconv.FormatInt(builderNet, 10)+" fee="+strconv.FormatInt(fee, 10))

	sendUgnot(att.Builder, totalToBuilder, rlm)
	if repRecordingEnabled {
		siege_rep.RecordQuestCompleted(cross(rlm), q.Sponsor, att.Builder, uint8(q.Category), q.Reward, reviewSecs, isRaid, false)
	}
}

// RequestRevision asks the builder to revise (max 2 times, only while now <= reviewDeadline).
// New deadline is strictly now + 24h.
func RequestRevision(cur realm, questID uint64, note string) {
	requireNonPayableEOA(0, cur)
	q := mustGetQuest(questID)
	requestRevisionCore(q, note, cur)
}

func requestRevisionCore(q *Quest, note string, rlm realm) {
	if q.Status != bs_core.QuestUnderReview {
		panic("quest is not UnderReview")
	}
	caller := rlm.Previous().Address()
	if caller != q.Sponsor {
		panic("unauthorized: only sponsor can request revision")
	}
	att := q.activeAttempt()
	if att == nil {
		panic("missing active attempt")
	}
	now := time.Now().Unix()
	if now > att.ReviewDeadline {
		panic("reviewDeadline has passed; cannot request revision")
	}
	if att.RevisionCount >= bs_core.MaxRevisions {
		panic("maximum revisions (2) reached; sponsor must Approve or Reject")
	}
	if err := bs_core.ValidateText(note, bs_core.MaxNoteBytes, true, true); err != nil {
		panic("revision note is required: " + err.Error())
	}

	att.RevisionCount++
	att.RevisionNotes = append(att.RevisionNotes, strings.TrimSpace(note))
	att.WorkDeadline = now + bs_core.RevisionDurationSec
	q.Status = bs_core.QuestRevisionRequested
	q.addEvent(now, caller, "REVISION_REQUESTED", "count="+strconv.Itoa(att.RevisionCount))
}

// ExpireRevision allows anyone to close a quest if the 24h revision window passes
// without re-submission. Stake returns 100% to builder (never slashed after first
// submission), reward returns to sponsor, neutral for builder reputation.
func ExpireRevision(cur realm, questID uint64) {
	requireNonPayableEOA(0, cur)
	q := mustGetQuest(questID)
	expireRevisionCore(q, cur)
}

func expireRevisionCore(q *Quest, rlm realm) {
	if q.Status != bs_core.QuestRevisionRequested {
		panic("quest is not in RevisionRequested state")
	}
	att := q.activeAttempt()
	if att == nil {
		panic("missing active attempt")
	}
	now := time.Now().Unix()
	if now <= att.WorkDeadline {
		panic("revision deadline has not elapsed yet")
	}

	reward := q.Reward
	stake := q.Stake
	builder := att.Builder
	released := reward + stake

	att.Outcome = bs_core.AttemptRevisionExpired
	q.Status = bs_core.QuestCancelled
	q.EscrowHeld -= released
	totalActiveEscrow -= released
	q.addEvent(now, rlm.Previous().Address(), "EXPIRED_REVISION", "reward_refund="+strconv.FormatInt(reward, 10)+" stake_refund="+strconv.FormatInt(stake, 10))

	sendUgnot(builder, stake, rlm)
	sendUgnot(q.Sponsor, reward, rlm)
	if repRecordingEnabled {
		siege_rep.RecordRevisionExpired(cross(rlm), builder)
	}
}

// TimeoutClaim lets the active builder claim payout (with 2% protocol fee + 100% stake)
// if the sponsor fails to review before reviewDeadline.
func TimeoutClaim(cur realm, questID uint64) {
	requireNonPayableEOA(0, cur)
	q := mustGetQuest(questID)
	timeoutClaimCore(q, false, cur)
}

func timeoutClaimCore(q *Quest, isRaid bool, rlm realm) {
	if q.Status != bs_core.QuestUnderReview {
		panic("quest is not UnderReview")
	}
	att := q.activeAttempt()
	if att == nil || rlm.Previous().Address() != att.Builder {
		panic("unauthorized: only active builder can trigger TimeoutClaim")
	}
	now := time.Now().Unix()
	if now <= att.ReviewDeadline {
		panic("reviewDeadline has not elapsed yet")
	}

	fee := bs_core.CalcProtocolFee(q.Reward)
	builderNet := q.Reward - fee
	totalToBuilder := builderNet + q.Stake
	released := q.Reward + q.Stake

	att.Outcome = bs_core.AttemptTimeoutClaimed
	q.Status = bs_core.QuestCompleted
	q.EscrowHeld -= released
	totalActiveEscrow -= released
	treasuryBalance += fee
	totalPaidOut += q.Reward
	q.addEvent(now, att.Builder, "TIMEOUT_CLAIMED", "builder_net="+strconv.FormatInt(builderNet, 10)+" fee="+strconv.FormatInt(fee, 10))

	sendUgnot(att.Builder, totalToBuilder, rlm)
	if repRecordingEnabled {
		siege_rep.RecordQuestCompleted(cross(rlm), q.Sponsor, att.Builder, uint8(q.Category), q.Reward, 0, isRaid, true)
	}
}

// RejectSubmission rejects the builder's work before reviewDeadline.
// Per Decision B3A + B5A: Stake is IMMEDIATELY refunded 100% to builder,
// and a 48-hour dispute window opens for the builder.
func RejectSubmission(cur realm, questID uint64, reason string) {
	requireNonPayableEOA(0, cur)
	q := mustGetQuest(questID)
	rejectSubmissionCore(q, reason, cur)
}

func rejectSubmissionCore(q *Quest, reason string, rlm realm) {
	if q.Status != bs_core.QuestUnderReview {
		panic("quest is not UnderReview")
	}
	caller := rlm.Previous().Address()
	if caller != q.Sponsor {
		panic("unauthorized: only sponsor can reject submission")
	}
	att := q.activeAttempt()
	if att == nil {
		panic("missing active attempt")
	}
	now := time.Now().Unix()
	if now > att.ReviewDeadline {
		panic("reviewDeadline has passed; cannot reject")
	}
	if err := bs_core.ValidateText(reason, bs_core.MaxNoteBytes, true, true); err != nil {
		panic("rejection reason is required: " + err.Error())
	}

	stake := q.Stake
	builder := att.Builder

	att.RejectionReason = strings.TrimSpace(reason)
	att.RejectDeadline = now + bs_core.DisputeWindowSec
	q.Status = bs_core.QuestRejected
	q.EscrowHeld -= stake
	totalActiveEscrow -= stake
	q.addEvent(now, caller, "REJECTED", "stake_returned="+strconv.FormatInt(stake, 10))

	sendUgnot(builder, stake, rlm)
}

// FinalizeRejection allows anyone to finalize a rejection after the 48h dispute window
// passes without dispute, refunding reward 100% to sponsor. Quest is permanently Cancelled.
func FinalizeRejection(cur realm, questID uint64) {
	requireNonPayableEOA(0, cur)
	q := mustGetQuest(questID)
	finalizeRejectionCore(q, cur)
}

func finalizeRejectionCore(q *Quest, rlm realm) {
	if q.Status != bs_core.QuestRejected {
		panic("quest is not in Rejected state")
	}
	att := q.activeAttempt()
	if att == nil {
		panic("missing active attempt")
	}
	now := time.Now().Unix()
	if now <= att.RejectDeadline {
		panic("48h dispute window has not elapsed yet")
	}

	reward := q.Reward
	att.Outcome = bs_core.AttemptRejectedFinal
	q.Status = bs_core.QuestCancelled
	q.EscrowHeld -= reward
	totalActiveEscrow -= reward
	q.addEvent(now, rlm.Previous().Address(), "FINALIZED_REJECTION", "refund="+strconv.FormatInt(reward, 10))

	sendUgnot(q.Sponsor, reward, rlm)
	if repRecordingEnabled {
		siege_rep.RecordRejected(cross(rlm), q.Sponsor, att.Builder)
	}
}

// OpenDispute lets the rejected builder open an arbiter dispute within 48h by locking
// a 5% dispute fee. Locks the current arbiter address for this dispute permanently.
func OpenDispute(cur realm, questID uint64, reason string) {
	q := mustGetQuest(questID)
	openDisputeCore(q, reason, cur)
}

func openDisputeCore(q *Quest, reason string, rlm realm) {
	disputeFee := bs_core.CalcDisputeFee(q.Reward)
	requireExactUgnot(disputeFee, rlm)
	if q.Status != bs_core.QuestRejected {
		panic("quest is not in Rejected state")
	}
	att := q.activeAttempt()
	if att == nil || rlm.Previous().Address() != att.Builder {
		panic("unauthorized: only rejected builder can open dispute")
	}
	now := time.Now().Unix()
	if now > att.RejectDeadline {
		panic("48h dispute window has elapsed")
	}
	if err := bs_core.ValidateText(reason, bs_core.MaxNoteBytes, true, true); err != nil {
		panic("dispute reason is required: " + err.Error())
	}

	att.DisputeFee = disputeFee
	att.DisputeReason = strings.TrimSpace(reason)
	att.LockedArbiter = arbiter
	att.DisputedAt = now
	att.DisputeDeadline = now + bs_core.ArbiterTimeoutSec
	q.Status = bs_core.QuestDisputed
	q.EscrowHeld += disputeFee
	totalActiveEscrow += disputeFee
	q.addEvent(now, att.Builder, "DISPUTE_OPENED", "fee="+strconv.FormatInt(disputeFee, 10)+" arbiter="+arbiter.String())
}

// ResolveDispute lets ONLY the dispute's lockedArbiter choose strictly one of two outcomes:
//   - releaseToBuilder == true  -> Reward - 2% fee + DisputeFee -> Builder; 2% fee -> Treasury
//   - releaseToBuilder == false -> Reward -> Sponsor; DisputeFee -> Treasury (never to arbiter!)
func ResolveDispute(cur realm, questID uint64, releaseToBuilder bool, resolutionNote string) {
	requireNonPayableEOA(0, cur)
	q := mustGetQuest(questID)
	resolveDisputeCore(q, releaseToBuilder, resolutionNote, false, cur)
}

func resolveDisputeCore(q *Quest, releaseToBuilder bool, resolutionNote string, isRaid bool, rlm realm) {
	if q.Status != bs_core.QuestDisputed {
		panic("quest is not Disputed")
	}
	att := q.activeAttempt()
	if att == nil {
		panic("missing active attempt")
	}
	caller := rlm.Previous().Address()
	if caller != att.LockedArbiter {
		panic("unauthorized: only the locked arbiter for this dispute can resolve it")
	}
	now := time.Now().Unix()
	if now > att.DisputeDeadline {
		panic("arbiter 7-day deadline has passed; anyone may trigger ExpireDispute")
	}
	if err := bs_core.ValidateText(resolutionNote, bs_core.MaxNoteBytes, true, true); err != nil {
		panic("resolution note is required: " + err.Error())
	}

	reward := q.Reward
	disputeFee := att.DisputeFee
	released := reward + disputeFee
	att.ResolutionNote = strings.TrimSpace(resolutionNote)
	q.EscrowHeld -= released
	totalActiveEscrow -= released

	if releaseToBuilder {
		fee := bs_core.CalcProtocolFee(reward)
		builderNet := reward - fee
		att.Outcome = bs_core.AttemptDisputeWon
		q.Status = bs_core.QuestCompleted
		treasuryBalance += fee
		totalPaidOut += reward
		q.addEvent(now, caller, "DISPUTE_RELEASE_BUILDER", "builder_net="+strconv.FormatInt(builderNet, 10)+" fee="+strconv.FormatInt(fee, 10))

		sendUgnot(att.Builder, builderNet+disputeFee, rlm)
		if repRecordingEnabled {
			siege_rep.RecordQuestCompleted(cross(rlm), q.Sponsor, att.Builder, uint8(q.Category), reward, 0, isRaid, false)
			siege_rep.RecordDisputeOutcome(cross(rlm), q.Sponsor, att.Builder, true)
		}
	} else {
		att.Outcome = bs_core.AttemptDisputeLost
		q.Status = bs_core.QuestCancelled
		treasuryBalance += disputeFee
		q.addEvent(now, caller, "DISPUTE_REFUND_SPONSOR", "refund="+strconv.FormatInt(reward, 10)+" dispute_fee_to_treasury="+strconv.FormatInt(disputeFee, 10))

		sendUgnot(q.Sponsor, reward, rlm)
		if repRecordingEnabled {
			siege_rep.RecordDisputeOutcome(cross(rlm), q.Sponsor, att.Builder, false)
		}
	}
}

// ExpireDispute allows anyone to resolve a dispute if the locked arbiter times out (> 7 days).
// Global rounding rule: Sponsor = R/2, Builder = R/2 - 2% fee + DisputeFee, Treasury = 2% fee + (R % 2).
func ExpireDispute(cur realm, questID uint64) {
	requireNonPayableEOA(0, cur)
	q := mustGetQuest(questID)
	expireDisputeCore(q, cur)
}

func expireDisputeCore(q *Quest, rlm realm) {
	if q.Status != bs_core.QuestDisputed {
		panic("quest is not Disputed")
	}
	att := q.activeAttempt()
	if att == nil {
		panic("missing active attempt")
	}
	now := time.Now().Unix()
	if now <= att.DisputeDeadline {
		panic("arbiter 7-day deadline has not elapsed yet")
	}

	reward := q.Reward
	disputeFee := att.DisputeFee
	released := reward + disputeFee
	sponsorAmt, builderNet, treasuryAmt := bs_core.CalcArbiterTimeoutSplit(reward)

	att.Outcome = bs_core.AttemptDisputeTimeout
	q.Status = bs_core.QuestResolvedTimeout
	q.EscrowHeld -= released
	totalActiveEscrow -= released
	treasuryBalance += treasuryAmt
	totalPaidOut += (reward / 2)
	q.addEvent(now, rlm.Previous().Address(), "DISPUTE_ARBITER_TIMEOUT", "sponsor="+strconv.FormatInt(sponsorAmt, 10)+" builder_net="+strconv.FormatInt(builderNet, 10)+" treasury="+strconv.FormatInt(treasuryAmt, 10))

	sendUgnot(q.Sponsor, sponsorAmt, rlm)
	sendUgnot(att.Builder, builderNet+disputeFee, rlm)
}

func mustGetQuest(id uint64) *Quest {
	q, ok := questsByID[id]
	if !ok {
		panic("quest not found: " + strconv.FormatUint(id, 10))
	}
	return q
}

func QuestCount() int {
	return len(questIDs)
}

package bountysiege

import (
	"strconv"
	"strings"
	"time"

	"gno.land/p/g1fn0l3ms5puafp37r7v67mx2msjl0ztnyq3a9yv/bs_core"
)

// Raid groups 2..4 independent role slots under a single mission page, Q&A,
// and derived parent status. Each slot runs the full Single-Claim Quest state
// machine independently, with max 1 slot per builder address per Raid.
type Raid struct {
	ID          uint64
	Sponsor     address
	Title       string
	Description string
	TotalReward int64
	CreatedAt   int64
	Slots       []*Quest
	// Tracks addresses that hold an active or completed slot in this Raid (append-only).
	slotHeldByAddr map[address]int
}

func (r *Raid) DerivedStatus() string {
	hasOpen := false
	hasActive := false
	for _, sl := range r.Slots {
		if sl.Status == bs_core.QuestOpen {
			hasOpen = true
		} else if !sl.Status.IsTerminal() {
			hasActive = true
		}
	}
	if hasOpen {
		return "open"
	}
	if hasActive {
		return "in_progress"
	}
	return "finished"
}

func (r *Raid) EscrowHeld() int64 {
	var sum int64
	for _, sl := range r.Slots {
		sum += sl.EscrowHeld
	}
	return sum
}

var (
	nextRaidID uint64
	raidsByID  = map[uint64]*Raid{}
	raidIDs    []uint64
)

// CreateRaid creates a Co-op Raid with 2..4 independent role slots and escrows
// the exact sum of all slot rewards.
//   - slotTitlesPipe: pipe-separated slot titles (e.g. "Smart Contract|Frontend UI")
//   - slotCriteriaPipe: pipe-separated acceptance criteria per slot
//   - slotCatsCSV: comma-separated Category enum ints (e.g. "0,1")
//   - slotRewardsCSV: comma-separated ugnot rewards per slot (each >= 1 GNOT)
//   - slotStakesCSV: comma-separated ugnot stakes per slot (each 5%..15% of its slot reward)
func CreateRaid(
	cur realm,
	title, description string,
	slotTitlesPipe, slotCriteriaPipe, slotCatsCSV, slotRewardsCSV, slotStakesCSV string,
	openDur, workDur, reviewDur int64,
) uint64 {
	requireRolesInitialized()

	if err := bs_core.ValidateText(title, bs_core.MaxTitleBytes, true, false); err != nil {
		panic("invalid raid title: " + err.Error())
	}
	if err := bs_core.ValidateText(description, bs_core.MaxDescBytes, true, true); err != nil {
		panic("invalid raid description: " + err.Error())
	}
	if err := bs_core.ValidateQuestDurations(openDur, workDur, reviewDur); err != nil {
		panic(err.Error())
	}

	titles := splitPipeNonEmpty(slotTitlesPipe, "slotTitles")
	criterias := splitPipeNonEmpty(slotCriteriaPipe, "slotCriteria")
	cats := parseIntCSV(slotCatsCSV, "slotCats")
	rewards := parseInt64CSV(slotRewardsCSV, "slotRewards")
	stakes := parseInt64CSV(slotStakesCSV, "slotStakes")

	n := len(titles)
	if n < bs_core.MinRaidSlots || n > bs_core.MaxRaidSlots {
		panic("Co-op Raid must have between 2 and 4 slots")
	}
	if len(criterias) != n || len(cats) != n || len(rewards) != n || len(stakes) != n {
		panic("all slot arrays must have identical length")
	}

	var totalReward int64
	for i := 0; i < n; i++ {
		if err := bs_core.ValidateText(titles[i], bs_core.MaxTitleBytes, true, false); err != nil {
			panic("invalid slot title #" + strconv.Itoa(i) + ": " + err.Error())
		}
		if err := bs_core.ValidateText(criterias[i], bs_core.MaxCriteriaBytes, true, true); err != nil {
			panic("invalid slot criteria #" + strconv.Itoa(i) + ": " + err.Error())
		}
		if !bs_core.Category(cats[i]).IsValid() {
			panic("invalid category on slot #" + strconv.Itoa(i))
		}
		if err := bs_core.ValidateStakeBounds(rewards[i], stakes[i]); err != nil {
			panic("invalid reward/stake on slot #" + strconv.Itoa(i) + ": " + err.Error())
		}
		sum, err := bs_core.StrictAdd64(totalReward, rewards[i])
		if err != nil {
			panic("total raid reward overflow")
		}
		totalReward = sum
	}

	// Enforce exact single ugnot coin equal to sum of all slot rewards!
	requireExactUgnot(totalReward, cur)

	sponsor := cur.Previous().Address()
	now := time.Now().Unix()

	nextRaidID++
	rid := nextRaidID
	slots := make([]*Quest, n)
	for i := 0; i < n; i++ {
		sl := &Quest{
			ID:               uint64(i),
			ParentRaidID:     rid,
			SlotIndex:        i,
			Sponsor:          sponsor,
			Title:            strings.TrimSpace(titles[i]),
			Description:      strings.TrimSpace(description),
			Criteria:         strings.TrimSpace(criterias[i]),
			Category:         bs_core.Category(cats[i]),
			Reward:           rewards[i],
			Stake:            stakes[i],
			OpenDuration:     openDur,
			WorkDuration:     workDur,
			ReviewDuration:   reviewDur,
			CreatedAt:        now,
			OpenDeadline:     now + openDur,
			Status:           bs_core.QuestOpen,
			EscrowHeld:       rewards[i],
			ActiveAttemptIdx: -1,
		}
		sl.addEvent(now, sponsor, "RAID_SLOT_CREATED", "raid="+strconv.FormatUint(rid, 10)+" slot="+strconv.Itoa(i)+" reward="+strconv.FormatInt(rewards[i], 10))
		slots[i] = sl
	}

	r := &Raid{
		ID:             rid,
		Sponsor:        sponsor,
		Title:          strings.TrimSpace(title),
		Description:    strings.TrimSpace(description),
		TotalReward:    totalReward,
		CreatedAt:      now,
		Slots:          slots,
		slotHeldByAddr: map[address]int{},
	}
	raidsByID[rid] = r
	raidIDs = append(raidIDs, rid)
	totalActiveEscrow += totalReward
	return rid
}

// Per-slot lifecycle functions (independent state machines reusing quest core).

func CancelRaidSlot(cur realm, raidID uint64, slotIdx int) {
	requireNonPayableEOA(0, cur)
	_, sl := mustGetRaidSlot(raidID, slotIdx)
	cancelQuestCore(sl, cur)
}

func ExpireOpenRaidSlot(cur realm, raidID uint64, slotIdx int) {
	requireNonPayableEOA(0, cur)
	_, sl := mustGetRaidSlot(raidID, slotIdx)
	expireOpenQuestCore(sl, cur)
}

func ClaimRaidSlot(cur realm, raidID uint64, slotIdx int) {
	r, sl := mustGetRaidSlot(raidID, slotIdx)
	builder := cur.Previous().Address()
	// Enforce max 1 slot per address per Raid (never deleting map keys!).
	for idx, other := range r.Slots {
		if idx == slotIdx {
			continue
		}
		if att := other.activeAttempt(); att != nil && att.Builder == builder {
			panic("builder already holds another slot in this Raid (max 1 slot per address)")
		}
		for _, a := range other.Attempts {
			if a.Builder == builder && (a.Outcome == bs_core.AttemptApproved || a.Outcome == bs_core.AttemptTimeoutClaimed || a.Outcome == bs_core.AttemptDisputeWon) {
				panic("builder already completed another slot in this Raid (max 1 slot per address)")
			}
		}
	}
	claimQuestCore(sl, cur)
	r.slotHeldByAddr[builder] = slotIdx
}

func ExpireRaidClaim(cur realm, raidID uint64, slotIdx int) {
	requireNonPayableEOA(0, cur)
	_, sl := mustGetRaidSlot(raidID, slotIdx)
	expireClaimCore(sl, cur)
}

func SubmitRaidWork(cur realm, raidID uint64, slotIdx int, proofURL, note string) {
	requireNonPayableEOA(0, cur)
	_, sl := mustGetRaidSlot(raidID, slotIdx)
	submitWorkCore(sl, proofURL, note, cur)
}

func ApproveRaidSlot(cur realm, raidID uint64, slotIdx int) {
	requireNonPayableEOA(0, cur)
	_, sl := mustGetRaidSlot(raidID, slotIdx)
	approveQuestCore(sl, true, cur)
}

func RequestRaidRevision(cur realm, raidID uint64, slotIdx int, note string) {
	requireNonPayableEOA(0, cur)
	_, sl := mustGetRaidSlot(raidID, slotIdx)
	requestRevisionCore(sl, note, cur)
}

func ExpireRaidRevision(cur realm, raidID uint64, slotIdx int) {
	requireNonPayableEOA(0, cur)
	_, sl := mustGetRaidSlot(raidID, slotIdx)
	expireRevisionCore(sl, cur)
}

func TimeoutRaidClaim(cur realm, raidID uint64, slotIdx int) {
	requireNonPayableEOA(0, cur)
	_, sl := mustGetRaidSlot(raidID, slotIdx)
	timeoutClaimCore(sl, true, cur)
}

func RejectRaidSlot(cur realm, raidID uint64, slotIdx int, reason string) {
	requireNonPayableEOA(0, cur)
	_, sl := mustGetRaidSlot(raidID, slotIdx)
	rejectSubmissionCore(sl, reason, cur)
}

func FinalizeRaidRejection(cur realm, raidID uint64, slotIdx int) {
	requireNonPayableEOA(0, cur)
	_, sl := mustGetRaidSlot(raidID, slotIdx)
	finalizeRejectionCore(sl, cur)
}

func OpenRaidDispute(cur realm, raidID uint64, slotIdx int, reason string) {
	_, sl := mustGetRaidSlot(raidID, slotIdx)
	openDisputeCore(sl, reason, cur)
}

func ResolveRaidDispute(cur realm, raidID uint64, slotIdx int, releaseToBuilder bool, resolutionNote string) {
	requireNonPayableEOA(0, cur)
	_, sl := mustGetRaidSlot(raidID, slotIdx)
	resolveDisputeCore(sl, releaseToBuilder, resolutionNote, true, cur)
}

func ExpireRaidDispute(cur realm, raidID uint64, slotIdx int) {
	requireNonPayableEOA(0, cur)
	_, sl := mustGetRaidSlot(raidID, slotIdx)
	expireDisputeCore(sl, cur)
}

//----------------------------------------
// Raid Helpers
//----------------------------------------

func mustGetRaid(id uint64) *Raid {
	r, ok := raidsByID[id]
	if !ok {
		panic("raid not found: " + strconv.FormatUint(id, 10))
	}
	return r
}

func mustGetRaidSlot(raidID uint64, slotIdx int) (*Raid, *Quest) {
	r := mustGetRaid(raidID)
	if slotIdx < 0 || slotIdx >= len(r.Slots) {
		panic("invalid raid slot index: " + strconv.Itoa(slotIdx))
	}
	return r, r.Slots[slotIdx]
}

func splitPipeNonEmpty(s, name string) []string {
	if strings.TrimSpace(s) == "" {
		panic(name + " is required")
	}
	parts := strings.Split(s, "|")
	for i := range parts {
		parts[i] = strings.TrimSpace(parts[i])
	}
	return parts
}

func parseIntCSV(csv, name string) []int {
	if strings.TrimSpace(csv) == "" {
		panic(name + " is required")
	}
	parts := strings.Split(csv, ",")
	out := make([]int, 0, len(parts))
	for _, p := range parts {
		n, err := strconv.Atoi(strings.TrimSpace(p))
		if err != nil {
			panic("invalid integer in " + name + ": " + p)
		}
		out = append(out, n)
	}
	return out
}

func parseInt64CSV(csv, name string) []int64 {
	if strings.TrimSpace(csv) == "" {
		panic(name + " is required")
	}
	parts := strings.Split(csv, ",")
	out := make([]int64, 0, len(parts))
	for _, p := range parts {
		n, err := strconv.ParseInt(strings.TrimSpace(p), 10, 64)
		if err != nil {
			panic("invalid int64 in " + name + ": " + p)
		}
		out = append(out, n)
	}
	return out
}

func RaidCount() int {
	return len(raidIDs)
}

