// TestCrashUnderwaterAndRecovery is the O14 headline: a price crash drives
// the position visibly UNDERWATER, then the feed (and the page) recover.
//
// The crash ladder respects the oracle's own 10% deviation guard at every
// step - with only one OTHER fresh source, the guard anchors on the last
// published median (oracle guards.gno, deviationReference). Every
// inequality below is the guard's exact integer form diff*1e4 <= 1000*ref,
// cross-checked offline:
//
//	start       median 45050
//	kucoin 41000: 4050*1e4 = 40.50M <= 45.05M -> median {41000,45100} = 43050
//	kraken 41050: 2000*1e4 = 20.00M <= 43.05M -> median {41000,41050} = 41025
//	kucoin 37100: 3925*1e4 = 39.25M <= 41.03M -> median {37100,41050} = 39075
//	kraken 37150: 1925*1e4 = 19.25M <= 39.08M -> median 37125 (pnl -1759 bps)
//
// Recovery climbs back the same way (each step within the guard):
//
//	kucoin 40800: 3675*1e4 = 36.75M <= 37.13M -> median {40800,37150} = 38975
//	kraken 40830: 1855*1e4 = 18.55M <= 38.98M -> median {40800,40830} = 40815
//	kucoin 44800: 3985*1e4 = 39.85M <= 40.82M -> median {44800,40830} = 42815
//	kraken 44850: 2035*1e4 = 20.35M <= 42.82M -> median {44800,44850} = 44825
//	kucoin 45000:  175*1e4 =  1.75M <= 44.83M -> median {45000,44850} = 44925
//	kraken 45100:  175*1e4 =  1.75M <= 44.93M -> median 45050 (baseline)
//
// The recovery matters beyond tidiness: the guard's fallback reference IS
// the last published median, so a crash left behind would make the next
// test's honest 45000 submission a >10% jump and get it REJECTED. Ending
// at the baseline makes the whole suite order-independent.
func TestCrashUnderwaterAndRecovery(cur realm, t *testing.T) {
	setupFeed(cur, 7000, 45000, 45100)
	testing.SetRealm(testing.NewUserRealm(bob))
	mustNotAbort(t, "opening at 45050", func() { Deposit(cross(cur), 500000000) })

	submitAs(cur, kucoinKey, "kucoin", 41000)
	submitAs(cur, krakenKey, "kraken", 41050)
	submitAs(cur, kucoinKey, "kucoin", 37100)
	submitAs(cur, krakenKey, "kraken", 37150)

	price, h := oracle.GetPrice(Asset)
	if price != 37125 || h != 7000 {
		t.Fatalf("crashed median = %d@%d, want 37125@7000", price, h)
	}

	p := getPosition(bob)
	if p == nil {
		t.Fatal("position vanished")
	}
	if got := pnlBps(p.entryPrice, price); got != -1759 { // 7925*1e4/45050
		t.Errorf("pnl = %d bps, want -1759", got)
	}
	if !isUnderwater(p.entryPrice, price) {
		t.Errorf("a -1759 bps move must be underwater at threshold %d", thresholdBps)
	}
	if got := healthPct(p.entryPrice, price); got != 82 { // 3712500/45050
		t.Errorf("health = %d%%, want 82%%", got)
	}

	page := Render("")
	if !strings.Contains(page, "UNDERWATER") {
		t.Errorf("dashboard must flag the position UNDERWATER:\n%s", page)
	}
	// 500 GNOT * $0.037125 = $18.5625 -> valueMicroUSD 18562500 -> "$18.562500".
	if !strings.Contains(page, "$18.562500") {
		t.Errorf("dashboard must show the crashed value:\n%s", page)
	}

	submitAs(cur, kucoinKey, "kucoin", 40800)
	submitAs(cur, krakenKey, "kraken", 40830)
	submitAs(cur, kucoinKey, "kucoin", 44800)
	submitAs(cur, krakenKey, "kraken", 44850)
	submitAs(cur, kucoinKey, "kucoin", 45000)
	submitAs(cur, krakenKey, "kraken", 45100)

	price, _ = oracle.GetPrice(Asset)
	if price != 45050 {
		t.Fatalf("recovered median = %d, want the baseline 45050", price)
	}
	if isUnderwater(p.entryPrice, price) {
		t.Errorf("the position must surface again at the recovered median")
	}
	page = Render("")
	if strings.Contains(page, "UNDERWATER") {
		t.Errorf("dashboard must clear UNDERWATER after recovery:\n%s", page)
	}
	if !strings.Contains(page, "ANSWERING at $0.045050") {
		t.Errorf("dashboard must answer again after recovery:\n%s", page)
	}
}

// Pure-math unit tests for the demo vault's valuation helpers. No heights,
// no oracle state - every expected value below was recomputed offline with
// independent integer arithmetic (§0.1 cross-check rule).
package demo

import (
	"testing"

	"gno.land/p/g14xvxs5ml67ggynte5rpysnq9q5cv976lrxfnlh/waag/feedmath/v0"
)

func TestPnlBps(cur realm, t *testing.T) {
	cases := []struct {
		entry, current feedmath.Price
		want           int64
	}{
		{45050, 45050, 0},                        // flat
		{45050, 49555, 1000},                     // +10% exactly: 4505*1e4/45050
		{45050, 40520, -1005},                    // 4530*1e4/45050 = 1005.5 -> truncated 1005
		{45050, 37125, -1759},                    // the crash-ladder endpoint
		{100, 99, -100},                          // small numbers stay exact
		{1000000, 1, -9999},                      // (1e6-1)*1e4/1e6 = 9999.99 -> 9999
		{1, 100000000000000, 999999999999990000}, // overflow headroom: (1e14-1)*1e4 ~ 1e18
	}
	for _, c := range cases {
		if got := pnlBps(c.entry, c.current); got != c.want {
			t.Errorf("pnlBps(%d, %d) = %d, want %d", c.entry, c.current, got, c.want)
		}
	}
}

func TestValueMicroUSD(cur realm, t *testing.T) {
	// 500 GNOT (500e6 ugnot) at $0.045050 = $22.525 = 22,525,000 micro-USD.
	if v, ok := valueMicroUSD(500000000, 45050); !ok || v != 22525000 {
		t.Errorf("valueMicroUSD(500e6, 45050) = %d, %v; want 22525000, true", v, ok)
	}
	// Smallest meaningful unit: 1 ugnot at $1.00 -> 1 micro-USD.
	if v, ok := valueMicroUSD(1, 1000000); !ok || v != 1 {
		t.Errorf("valueMicroUSD(1, 1e6) = %d, %v; want 1, true", v, ok)
	}
	// Zero inputs are not valuations.
	if _, ok := valueMicroUSD(0, 45050); ok {
		t.Error("zero amount must not value")
	}
	if _, ok := valueMicroUSD(500, 0); ok {
		t.Error("zero price must not value")
	}
	// The overflow guard: 1e9 ugnot at MaxPrice (1e14) is a 1e23 product -
	// far past int64 - so it must report "does not fit", not wrap negative.
	if _, ok := valueMicroUSD(1000000000, feedmath.MaxPrice); ok {
		t.Error("1e9 ugnot at MaxPrice must trip the overflow guard")
	}
	// Just under the guard: 1 ugnot at MaxPrice = 1e14/1e6 = 1e8 micro-USD.
	if v, ok := valueMicroUSD(1, feedmath.MaxPrice); !ok || v != 100000000 {
		t.Errorf("valueMicroUSD(1, MaxPrice) = %d, %v; want 100000000, true", v, ok)
	}
}

func TestHealthPct(cur realm, t *testing.T) {
	cases := []struct {
		entry, current feedmath.Price
		want           int64
	}{
		{45050, 45050, 100}, // flat
		{45050, 37125, 82},  // 3712500/45050 = 82.4 -> 82
		{45050, 90100, 200}, // doubled
		{45050, 40520, 89},  // 4052000/45050 = 89.9 -> 89
	}
	for _, c := range cases {
		if got := healthPct(c.entry, c.current); got != c.want {
			t.Errorf("healthPct(%d, %d) = %d, want %d", c.entry, c.current, got, c.want)
		}
	}
}

func TestIsUnderwater(cur realm, t *testing.T) {
	thresholdBps = DefaultThresholdBps // defensive: pure tests own this var here
	defer func() { thresholdBps = DefaultThresholdBps }()

	// -1005 bps breaches the default 1000 bps threshold.
	if !isUnderwater(45050, 40520) {
		t.Error("a -1005 bps move must be underwater at threshold 1000")
	}
	// -999 bps does not (4504*1e4/45050 = 999.7 -> 999).
	if isUnderwater(45050, 40546) {
		t.Error("a -999 bps move must not be underwater at threshold 1000")
	}
	// The boundary is inclusive: exactly -1000 counts as underwater, matching
	// the deviation guard's "reject only strictly greater" convention.
	if !isUnderwater(10000, 9000) {
		t.Error("exactly -1000 bps must be underwater at threshold 1000")
	}
	// No move is never underwater at the default threshold...
	if isUnderwater(45050, 45050) {
		t.Error("a flat position must not be underwater at threshold 1000")
	}
	// ...but a 0 bps threshold flags any dip at all, and even flat (<= -0).
	thresholdBps = 0
	if !isUnderwater(45050, 45050) {
		t.Error("threshold 0 must flag a flat position (pnl 0 <= -0)")
	}
	// A wider threshold unflags the -1005 move.
	thresholdBps = 2000
	if isUnderwater(45050, 40520) {
		t.Error("a -1005 bps move must not be underwater at threshold 2000")
	}
}

func TestParseFreshCount(cur realm, t *testing.T) {
	// The real header the oracle emits (oracle.gno GetSources).
	full := "asset=GNOT fresh=2/3 quorum=2\n" +
		"kucoin price=$0.045000 age=0 status=FRESH rejected=0"
	if n, ok := parseFreshCount(full); !ok || n != 2 {
		t.Errorf("parseFreshCount(real snapshot) = %d, %v; want 2, true", n, ok)
	}
	if n, ok := parseFreshCount("asset=GNOT fresh=0/3 quorum=2"); !ok || n != 0 {
		t.Errorf("fresh=0 must parse as 0/true, got %d, %v", n, ok)
	}

	bad := []string{
		"",                    // nothing at all
		"freshx=2/3",          // near-miss key must not match
		"fresh=abc/3",         // non-numeric
		"fresh=2",             // missing the /M part
		"fresh=/3",            // empty numerator
		"fresh=-1/3",          // negative count is nonsense
		"asset=GNOT quorum=2", // header without fresh=
	}
	for _, s := range bad {
		if n, ok := parseFreshCount(s); ok {
			t.Errorf("parseFreshCount(%q) = %d, true; want false", s, n)
		}
	}
}

package demo

// Render for the demo vault. Same rule as the oracle's Render: a free
// read-only query that must NEVER panic - a page that fails to load looks
// like a dead vault even when the positions are fine.
//
// The formatting helpers are deliberate copies of the oracle realm's (its
// render.gno): they are unexported there, and importing display helpers
// across a realm boundary is not worth the coupling for a v0 demo. Same
// integer-only rules (ledger O7) - no floats anywhere.

import (
	"strconv"
	"strings"

	"chain/runtime"

	"gno.land/p/g14xvxs5ml67ggynte5rpysnq9q5cv976lrxfnlh/waag/feedmath/v0"
	oracle "gno.land/r/g14xvxs5ml67ggynte5rpysnq9q5cv976lrxfnlh/waag/oracle/v0"
)

// Render builds the demo vault's public web page (ledger O17: this page IS
// the v0 frontend; no custom UI until the owner's design gate).
func Render(path string) string {
	switch path {
	case "", "/":
		return renderDashboard()
	case "help":
		return renderHelp()
	default:
		return "unknown path: " + path + "\n\ntry:\n  (nothing)  vault dashboard\n  help       how this demo consumes the feed\n"
	}
}

// safeFeedProbe is the dashboard's ONLY contact with the oracle. It pairs
// the check-then-call gate (feedAnswering, proven sufficient in the package
// doc) with a belt-and-braces recover: the probe functions call
// oracle.GetSources, which panics on a never-registered asset. The deploy
// runbook makes that state unreachable on a real chain (oracle + sources
// are registered before this realm is deployed), and the recover covers it
// everywhere else - Render degrades to "UNAVAILABLE" instead of failing.
func safeFeedProbe() (answering bool, status string, price feedmath.Price, priceAt int64) {
	defer func() {
		if recover() != nil {
			answering = false
			status = "UNAVAILABLE (oracle state could not be read)"
			price = 0
			priceAt = 0
		}
	}()
	if !feedAnswering() {
		return false, feedStatusText(), 0, 0
	}
	p, h := oracle.GetPrice(Asset)
	return true, "ANSWERING", p, h
}

func renderDashboard() string {
	height := runtime.ChainHeight()
	answering, status, price, priceAt := safeFeedProbe()

	var b strings.Builder
	b.WriteString("# The Waag - demo vault (MOCK)\n\n")
	b.WriteString("chain height: " + strconv.FormatInt(height, 10) + "\n")
	b.WriteString("admin:        " + admin.String() + "\n")
	b.WriteString("asset:        " + Asset + "\n")
	b.WriteString("oracle:       " + OraclePath + "\n")
	b.WriteString("underwater threshold: " + formatBps(thresholdBps) + " below entry\n")
	b.WriteString("\nMOCK vault: positions are test numbers. No real GNOT is held or moved.\n")

	b.WriteString("\n## Feed\n\n")
	if answering {
		b.WriteString("status: ANSWERING at " + formatUSD(price) +
			" (published at height " + strconv.FormatInt(priceAt, 10) +
			", " + strconv.FormatInt(feedmath.BlockAge(priceAt, height), 10) +
			" blocks ago)\n")
	} else {
		b.WriteString("*** FEED FROZEN *** " + status + "\n")
		b.WriteString("deposits revert while frozen; withdrawals stay open; valuations show n/a.\n")
	}

	b.WriteString("\n## Positions\n\n")
	if positions.Size() == 0 {
		b.WriteString("(no open positions)\n")
		return b.String()
	}

	totalText := "too large to sum"
	if total, ok := totalMockUGNOT(); ok {
		totalText = formatGNOT(total)
	}
	b.WriteString("open positions: " + strconv.Itoa(positions.Size()) +
		" (total mock " + totalText + ")\n\n")

	b.WriteString("| depositor | mock GNOT | entry | value now | health | status |\n")
	b.WriteString("|-----------|-----------|-------|-----------|--------|--------|\n")

	positions.Iterate("", "", func(_ string, value any) bool {
		p, isPos := value.(*position)
		if !isPos {
			return false // keep going; a malformed entry must not stop the page
		}
		valNow, health, state := "n/a", "n/a", "FROZEN"
		if answering {
			if v, fits := valueMicroUSD(p.amountUGNOT, price); fits {
				valNow = formatUSD(feedmath.Price(v))
			} else {
				valNow = "too large"
			}
			health = strconv.FormatInt(healthPct(p.entryPrice, price), 10) + "%"
			if isUnderwater(p.entryPrice, price) {
				state = "UNDERWATER"
			} else {
				state = "OK"
			}
		}
		b.WriteString("| " + p.depositor.String() +
			" | " + formatGNOT(p.amountUGNOT) +
			" | " + formatUSD(p.entryPrice) +
			" | " + valNow +
			" | " + health +
			" | " + state + " |\n")
		return false
	})

	b.WriteString("\nfrozen positions keep their entry prices as evidence; nothing is hidden or deleted while the feed is down.\n")
	return b.String()
}

// totalMockUGNOT sums open position sizes. Each size is capped at
// MaxPositionUGNOT, but the running sum is overflow-guarded anyway: a
// display helper must never be the thing that wraps around.
func totalMockUGNOT() (int64, bool) {
	total := int64(0)
	fits := true
	positions.Iterate("", "", func(_ string, value any) bool {
		p, isPos := value.(*position)
		if !isPos {
			return false
		}
		if fits && total <= maxInt64-p.amountUGNOT {
			total += p.amountUGNOT
		} else {
			fits = false
		}
		return false
	})
	return total, fits
}

func renderHelp() string {
	return `# How this demo consumes The Waag feed

MOCK vault (ledger O14): positions are test numbers valued through
` + OraclePath + `. No real GNOT is held, no borrowing, no interest.

## The check-then-call pattern (the point of this realm)

oracle.GetPrice PANICS when the feed cannot be trusted, and a panic that
crosses a realm boundary cannot be caught in production - revive() is a
test-mode builtin only. So this realm NEVER tries to catch it. It checks
first with two non-panicking reads, and only then calls:

    _, _, minFresh, paused := oracle.Config()
    fresh, _ := parseFreshCount(oracle.GetSources("GNOT"))  // header: fresh=N/M
    if !paused && fresh >= minFresh {
        price, height := oracle.GetPrice("GNOT")            // cannot panic now
    }

Why that check is sufficient is proved in this realm's package docs: if
enough sources are fresh NOW, the newest fresh submission already republished
a fresh median, so none of GetPrice's panic conditions can hold.

## What a frozen feed means here

- Deposit  REVERTS with the reason (no price, no position, no guessing).
- Withdraw is ALWAYS allowed - mock funds are never held hostage by a dead
  feed. The closing event records feed=frozen instead of a realized pnl.
- The dashboard degrades to "*** FEED FROZEN ***" plus the reason, and shows
  n/a where a live price would be. Stored positions keep their entry prices
  as evidence; nothing is hidden or deleted while the feed is down.

## Underwater rule

A position is UNDERWATER when the fed price sits at least the threshold
(default 10.00%) below its entry price. The admin retunes it with
SetThreshold(bps), range [0, 10000].

## Calling it

    gnokey maketx call -pkgpath "gno.land/r/g14xvxs5ml67ggynte5rpysnq9q5cv976lrxfnlh/waag/demo/v0" ` +
		`\
      -func Deposit -args 500000000 \
      -gas-wanted <simulate first> -gas-fee <simulate first> \
      -chainid onyx-1 -remote https://rpc.onyx.testnets.gno.land:443 test1

Deposit takes mock ugnot (500000000 = 500 GNOT); Withdraw takes no args.
Always measure gas with -simulate only first (see scripts/deploy.sh - the
empty-state simulation UNDER-sizes state-dependent calls; that trap is in
the master doc §13).

## Events

VaultPositionOpened / VaultPositionClosed / VaultThresholdChanged, emitted
via chain.Emit with everything an off-chain watcher needs - including
realized pnl_bps and whether the feed was answering at withdrawal.
`
}

// ---- formatting helpers (integer math only) --------------------------------

// formatUSD renders a scaled price as dollars, e.g. 45050 -> "$0.045050".
// A non-positive price is not a quote, so it renders as "n/a" rather than $0.
func formatUSD(p feedmath.Price) string {
	if p <= 0 {
		return "n/a"
	}
	whole := int64(p) / feedmath.Scale
	frac := int64(p) % feedmath.Scale
	return "$" + strconv.FormatInt(whole, 10) + "." + padLeft(frac, 6)
}

// formatGNOT renders mock ugnot as GNOT: 500000000 -> "500.000000 GNOT".
// ugnot uses the same 1e6 scale as feedmath prices, hence feedmath.Scale.
func formatGNOT(ugnot int64) string {
	if ugnot < 0 {
		ugnot = 0
	}
	whole := ugnot / feedmath.Scale
	frac := ugnot % feedmath.Scale
	return strconv.FormatInt(whole, 10) + "." + padLeft(frac, 6) + " GNOT"
}

// formatBps renders basis points as a percentage, e.g. 1000 -> "10.00%".
func formatBps(bps int64) string {
	whole := bps / 100
	frac := bps % 100
	if frac < 0 {
		frac = -frac
	}
	return strconv.FormatInt(whole, 10) + "." + padLeft(frac, 2) + "%"
}

// padLeft zero-pads n to width digits: fractional parts lose leading zeros
// when formatted plainly (45050 % 1e6 = 45050 must print as "045050").
func padLeft(n int64, width int) string {
	s := strconv.FormatInt(n, 10)
	for len(s) < width {
		s = "0" + s
	}
	return s
}

// Package demo is The Waag's consumer demo realm (ledger O14): a MOCK GNOT
// vault valued entirely through the oracle realm's GetPrice.
//
// What it proves, in one page of on-chain state:
//
//  1. A real protocol can consume the feed: positions are opened at the
//     published median price and marked against it as the feed updates.
//  2. The refusal design works FROM THE CONSUMER SIDE: when the feed is
//     frozen (paused, stale, or below quorum), opening a position reverts
//     with a clear reason and the dashboard renders "FEED FROZEN" instead
//     of guessing a number. This is the exact integration pattern the
//     parked lending flagship will follow.
//  3. Positions go visibly UNDERWATER when the fed price falls more than
//     the threshold (admin-tunable, default 10%) below entry.
//
// It is a DEMO: deposits are mock numbers, no real GNOT is held or moved.
// No borrowing, no interest — valuation and health display only (O14).
//
// ---- The frozen-feed pattern (verified, not guessed) ----
//
// oracle.GetPrice PANICS when the feed cannot be trusted, and a panic that
// crosses a realm boundary cannot be caught in production (revive() is a
// test-mode builtin only — §13 trap, verified against v1.8.0). So this
// realm NEVER catches; it CHECKS FIRST and only then calls:
//
//	feedAnswering() = !paused (oracle.Config) AND fresh >= quorum
//	                  (parsed from the oracle.GetSources header, whose
//	                   stable text format is that function's documented
//	                   consumer contract)
//
// Why that check is sufficient (proof sketch, oracle.gno v0): GetPrice
// panics iff paused, unpublished, below quorum, or median stale. If >=
// quorum sources are fresh NOW, let hN be the newest fresh ACCEPTED
// submission height. Every currently-fresh source was also fresh at hN
// (its accepted height lies in (hN-staleness, hN]), so the recompute at
// hN saw quorum and published the median at hN; hN is within the
// staleness window, so the median is fresh and published. Hence
// feedAnswering() true => GetPrice cannot panic. Rejected outliers never
// update a source's height, so they cannot fake freshness.
//
// PRECONDITION: asset GNOT must be registered in the oracle before this
// realm renders (GetSources panics on unknown assets, and a crossing panic
// cannot be caught). Enforced by the deploy runbook order: oracle ->
// RegisterSource x3 -> demo.
//
// Math is integer-only (ledger O7), every product is bounds-checked
// against int64 overflow, and prices are feedmath.Price (micro-USD, 1e6).
package demo

import (
	"strconv"
	"strings"

	"chain"
	"chain/runtime"

	"gno.land/p/g14xvxs5ml67ggynte5rpysnq9q5cv976lrxfnlh/waag/feedmath/v0"
	"gno.land/p/nt/avl/v0"
	oracle "gno.land/r/g14xvxs5ml67ggynte5rpysnq9q5cv976lrxfnlh/waag/oracle/v0"
)

// ---- Constants ------------------------------------------------------------

// Asset is the single feed this demo consumes. v0 is deliberately
// single-asset; the oracle itself is multi-asset.
const Asset = "GNOT"

// OraclePath is informational (rendered in help text).
const OraclePath = "gno.land/r/g14xvxs5ml67ggynte5rpysnq9q5cv976lrxfnlh/waag/oracle/v0"

// DefaultThresholdBps: a position is UNDERWATER when the fed price is this
// many basis points (or more) BELOW its entry price. 1000 bps = 10%.
const DefaultThresholdBps = int64(1000)

// MaxPositionUGNOT caps one mock position at 1000 GNOT (1e9 ugnot). The cap
// keeps amount*price products provable: see valueMicroUSD's overflow guard,
// which holds for ANY price up to feedmath.MaxPrice.
const MaxPositionUGNOT = int64(1000000000)

// Admin is the project admin key (alice) — the same literal-admin rule the
// oracle realm uses (forced decision, master doc §7).
var admin = address("g14xvxs5ml67ggynte5rpysnq9q5cv976lrxfnlh")

// ---- Events ----------------------------------------------------------------

const (
	PositionOpenedEvent   = "VaultPositionOpened"
	PositionClosedEvent   = "VaultPositionClosed"
	ThresholdChangedEvent = "VaultThresholdChanged"
)

// ---- Types & state ----------------------------------------------------------

// position is one depositor's mock vault position. Stored as a POINTER in
// the avl.Tree (same reason as the oracle's sources: tree values are `any`,
// a by-value struct would hand back copies and mutations would vanish).
type position struct {
	depositor   address
	amountUGNOT int64          // mock ugnot, (0, MaxPositionUGNOT]
	entryPrice  feedmath.Price // published median when opened
	entryHeight int64          // height at which that median was published
}

var positions avl.Tree // depositor.String() -> *position

var thresholdBps = DefaultThresholdBps

// maxInt64 for overflow guards. Written as an UNTYPED shift (1<<63 - 1, the
// same idiom as math.MaxInt64) so the constant folds to 9223372036854775807
// at arbitrary precision; the typed form int64(1)<<63 overflows int64 before
// the subtraction and gno's type checker rejects it.
const maxInt64 = 1<<63 - 1

// ---- Feed status (the check-then-call gate) ---------------------------------

// feedAnswering reports whether oracle.GetPrice(Asset) will return a price
// right now instead of panicking. See the package doc for the proof that
// !paused && fresh>=quorum is sufficient.
func feedAnswering() bool {
	_, _, minFresh, paused := oracle.Config()
	if paused {
		return false
	}
	fresh, ok := parseFreshCount(oracle.GetSources(Asset))
	if !ok {
		return false // unparseable header: assume frozen, never guess
	}
	return fresh >= minFresh
}

// feedStatusText renders the feed state as a bare human-readable reason
// ("oracle paused", "only 0 of 2 required sources fresh", ... or
// "ANSWERING"). Callers add their own framing: Deposit wraps it in a
// revert message, Render prefixes the frozen banner.
func feedStatusText() string {
	_, _, minFresh, paused := oracle.Config()
	if paused {
		return "oracle paused"
	}
	fresh, ok := parseFreshCount(oracle.GetSources(Asset))
	if !ok {
		return "unreadable source snapshot"
	}
	if fresh < minFresh {
		return "only " + strconv.Itoa(fresh) + " of " +
			strconv.Itoa(minFresh) + " required sources fresh"
	}
	return "ANSWERING"
}

// parseFreshCount extracts N from the oracle.GetSources header
// "asset=GNOT fresh=N/M quorum=Q". The header format is that function's
// documented stable contract for consumers (oracle.gno).
func parseFreshCount(snapshot string) (int, bool) {
	i := strings.Index(snapshot, "fresh=")
	if i < 0 {
		return 0, false
	}
	rest := snapshot[i+len("fresh="):]
	slash := strings.IndexByte(rest, '/')
	if slash <= 0 {
		return 0, false
	}
	n, err := strconv.Atoi(rest[:slash])
	if err != nil || n < 0 {
		return 0, false
	}
	return n, true
}

// ---- Vault operations --------------------------------------------------------

// Deposit opens a mock position for the caller at the current published
// median. It REVERTS while the feed is frozen: no price, no position — the
// consumer-side mirror of the oracle's own refusal promise.
//
// Crossing function (cur realm): the depositor is cur.Previous(), and it
// must be a direct user call — a realm calling on a user's behalf is the
// confused-deputy hole the oracle also closes.
func Deposit(cur realm, amountUGNOT int64) {
	caller := cur.Previous()
	if !caller.IsUserCall() {
		panic("vault: Deposit requires a direct user call")
	}
	if amountUGNOT <= 0 || amountUGNOT > MaxPositionUGNOT {
		panic("vault: amount must be within (0, " +
			strconv.FormatInt(MaxPositionUGNOT, 10) + "] ugnot")
	}
	who := caller.Address()
	key := who.String()
	if _, exists := positions.Get(key).(*position); exists {
		panic("vault: position already open - withdraw it first (v0 is one position per depositor)")
	}
	if !feedAnswering() {
		panic("vault: price feed unavailable (" + feedStatusText() +
			") - deposits are frozen until it answers again")
	}

	price, height := oracle.GetPrice(Asset)
	feedmath.MustValidPrice(price) // belt and braces: never store a bad entry

	positions.Set(key, &position{
		depositor:   who,
		amountUGNOT: amountUGNOT,
		entryPrice:  price,
		entryHeight: height,
	})
	chain.Emit(
		PositionOpenedEvent,
		"depositor", key,
		"asset", Asset,
		"amount_ugnot", strconv.FormatInt(amountUGNOT, 10),
		"entry_price", strconv.FormatInt(int64(price), 10),
		"height", strconv.FormatInt(runtime.ChainHeight(), 10),
	)
}

// Withdraw closes the caller's position. ALWAYS allowed, even with a frozen
// feed: mock funds are never held hostage by a dead oracle. The realized
// P&L is only computed when the feed answers; otherwise the event says so.
func Withdraw(cur realm) {
	caller := cur.Previous()
	if !caller.IsUserCall() {
		panic("vault: Withdraw requires a direct user call")
	}
	who := caller.Address()
	key := who.String()
	p, ok := positions.Get(key).(*position)
	if !ok {
		panic("vault: no open position")
	}
	positions.Remove(key)

	feedState := "frozen"
	pnl := int64(0)
	exitPrice := int64(0)
	if feedAnswering() {
		curPrice, _ := oracle.GetPrice(Asset)
		feedState = "answering"
		exitPrice = int64(curPrice)
		pnl = pnlBps(p.entryPrice, curPrice)
	}
	chain.Emit(
		PositionClosedEvent,
		"depositor", key,
		"asset", Asset,
		"amount_ugnot", strconv.FormatInt(p.amountUGNOT, 10),
		"entry_price", strconv.FormatInt(int64(p.entryPrice), 10),
		"exit_price", strconv.FormatInt(exitPrice, 10),
		"pnl_bps", strconv.FormatInt(pnl, 10),
		"feed", feedState,
	)
}

// SetThreshold retunes the underwater threshold (bps below entry).
// Admin-only, direct user calls only.
func SetThreshold(cur realm, bps int64) {
	caller := cur.Previous()
	if !caller.IsUserCall() {
		panic("vault: admin functions require a direct user call")
	}
	if caller.Address() != admin {
		panic("vault: caller is not the admin")
	}
	if bps < 0 || bps > feedmath.BpsScale {
		panic("vault: threshold must be within [0, 10000] bps")
	}
	thresholdBps = bps
	chain.Emit(
		ThresholdChangedEvent,
		"threshold_bps", strconv.FormatInt(bps, 10),
	)
}

// ---- Valuation math (integer-only, overflow-guarded) -------------------------

// pnlBps is the signed percentage move from entry to current, in basis
// points. Bounds: |diff| <= feedmath.MaxPrice (1e14), diff*1e4 <= 1e18,
// comfortably inside int64 (9.22e18). Both prices are validated (>0) before
// storage, and GetPrice never returns a non-positive price.
func pnlBps(entry, current feedmath.Price) int64 {
	if current >= entry {
		return int64(current-entry) * feedmath.BpsScale / int64(entry)
	}
	return -int64(entry-current) * feedmath.BpsScale / int64(entry)
}

// valueMicroUSD converts a mock ugnot amount to micro-USD at a price, with
// an explicit overflow guard: amount <= 1e9 and price <= 1e14 CAN exceed
// int64 when multiplied, so the product is checked before it happens.
// ok=false means "too large to display", and the render says exactly that
// instead of wrapping around to a negative number.
func valueMicroUSD(amountUGNOT int64, p feedmath.Price) (int64, bool) {
	if amountUGNOT <= 0 || p <= 0 {
		return 0, false
	}
	if int64(p) > maxInt64/amountUGNOT {
		return 0, false
	}
	return amountUGNOT * int64(p) / feedmath.Scale, true
}

// healthPct is current price as an integer percentage of entry (100 = flat).
// current <= 1e14, *100 = 1e16 — inside int64.
func healthPct(entry, current feedmath.Price) int64 {
	return int64(current) * 100 / int64(entry)
}

// isUnderwater reports whether the position has fallen at least
// thresholdBps below entry.
func isUnderwater(entry, current feedmath.Price) bool {
	return pnlBps(entry, current) <= -thresholdBps
}

// getPosition is the read helper used by render.
func getPosition(addr address) *position {
	p, ok := positions.Get(addr.String()).(*position)
	if !ok {
		return nil
	}
	return p
}

package hearthregistry

// HearthRegistry is the demo execution target for HearthCouncil: a tiny
// on-chain parameter store. It proves that a passed DAO proposal can
// change state in another realm.
//
// Only the HearthCouncil DAO realm may write (checked by package path of
// the calling realm). Reads are open to everyone.

import (
	"chain"

	"gno.land/p/nt/avl/v0"
)

// daoPkgPath is the only realm allowed to change parameters.
const daoPkgPath = "gno.land/r/g1utqjz9adrhy5y26hfufgqyua0srsxwkf776vzd/hearthcouncil"

var params avl.Tree // key string -> value string

func init(cur realm) {
	params.Set("greeting", "Welcome to HearthCouncil")
	params.Set("max_proposals_per_day", "10")
	params.Set("tavern_name", "The Hearth Tavern")
}

// GetParam returns the value for key, or "" if unset.
func GetParam(key string) string {
	v := params.Get(key)
	if v == nil {
		return ""
	}
	return v.(string)
}

// HasParam reports whether key exists.
func HasParam(key string) bool {
	return params.Has(key)
}

// ParamCount returns the number of stored parameters.
func ParamCount() int {
	return params.Size()
}

// SetParam writes a parameter. Only callable by the HearthCouncil DAO
// realm (a cross-realm call from the DAO after a passed proposal).
func SetParam(cur realm, key, value string) {
	if cur.Previous().PkgPath() != daoPkgPath {
		panic("only the HearthCouncil DAO can set parameters")
	}
	if key == "" {
		panic("key must not be empty")
	}
	params.Set(key, value)
	chain.Emit("ParamSet", "key", key, "value", value)
}

// Keys returns all parameter keys in sorted order (for Render).
func Keys() []string {
	keys := []string{}
	params.Iterate("", "", func(key string, value any) bool {
		keys = append(keys, key)
		return false // keep iterating
	})
	return keys
}

package hearthregistry

// Render shows the parameter store for gnoweb.

import (
	"gno.land/p/nt/ufmt/v0"
)

func Render(path string) string {
	out := "# HearthRegistry — demo execution target\n\n"
	out += "A tiny on-chain parameter store. Only the HearthCouncil DAO\n"
	out += "realm can change values (after a proposal passes, queues, and\n"
	out += "executes). Anyone can read.\n\n"
	out += "## Parameters\n\n"
	for _, k := range Keys() {
		out += ufmt.Sprintf("- %s: %s\n", k, GetParam(k))
	}
	out += "\nTry it: pass a DAO proposal with action `set_param` and args\n"
	out += "`key=value` — after the timelock, the value above changes.\n"
	return out
}

package hearth

// HEARTH is the HearthCouncil governance token (GRC20, decimals 0).
//
// Distribution model (fixed supply, no admin mint):
//   - The full supply is minted once, at deploy time, into this realm's
//     own reserve.
//   - Claim: one-time airdrop of ClaimAmount per address.
//   - Faucet: demo tap of FaucetAmount per call, until the reserve runs out.
//   - The HearthCouncil DAO pulls deposits from holders via TransferFrom
//     (allowance), so voting power is escrowed HEARTH, never spendable
//     twice: tokens that voted cannot be transferred away while the
//     proposal is active (the DAO locks them, see hearthcouncil).

import (
	"strconv"

	"chain"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/grc20/v0"
	"gno.land/p/nt/seqid/v0"
)

const (
	// InitialSupply is the total HEARTH ever minted (decimals = 0).
	InitialSupply = 1_000_000
	// ClaimAmount is the one-time airdrop per address.
	ClaimAmount = 1_000
	// FaucetAmount is the per-call demo tap amount.
	FaucetAmount = 1_000
)

var (
	token     *grc20.Token
	ledger    *grc20.PrivateLedger
	nextID    seqid.ID
	claimed   avl.Tree // address string -> true (Claim already used)
	realmAddr address  // this realm's own address; holds the reserve
)

func init(cur realm) {
	token, ledger = grc20.NewToken("HEARTH", "HEARTH", 0, nextID.Next(), cur)
	realmAddr = cur.Address()
	ledger.Mint(realmAddr, InitialSupply)
}

// ---- read-only ----

func Name() string {
	return token.GetName()
}

func Symbol() string {
	return token.GetSymbol()
}

func Decimals() int {
	return token.GetDecimals()
}

func TotalSupply() int64 {
	return token.TotalSupply()
}

func BalanceOf(addr address) int64 {
	return token.BalanceOf(addr)
}

func Allowance(owner, spender address) int64 {
	return token.ReadonlyTeller().Allowance(owner, spender)
}

// Reserve returns the HEARTH still held by this realm (undistributed).
func Reserve() int64 {
	return token.BalanceOf(realmAddr)
}

// RealmAddress returns this realm's own address (the reserve holder).
func RealmAddress() address {
	return realmAddr
}

// HasClaimed reports whether addr already took its one-time Claim.
func HasClaimed(addr address) bool {
	return claimed.Has(addr.String())
}

// ---- user token operations (crossing functions) ----

// Transfer moves amount HEARTH from the caller to `to`.
func Transfer(cur realm, to address, amount int64) {
	mustPositive(amount)
	teller := ledger.CallerTeller()
	mustNoErr(teller.Transfer(0, cur, to, amount))
}

// Approve lets `spender` move up to amount HEARTH on the caller's behalf.
func Approve(cur realm, spender address, amount int64) {
	mustNonNegative(amount)
	teller := ledger.CallerTeller()
	mustNoErr(teller.Approve(0, cur, spender, amount))
}

// TransferFrom moves amount HEARTH from `from` to `to`, spending the
// caller's allowance over `from`'s tokens. The DAO uses this to pull
// deposits (the caller must first Approve the DAO realm).
func TransferFrom(cur realm, from, to address, amount int64) {
	mustPositive(amount)
	teller := ledger.CallerTeller()
	mustNoErr(teller.TransferFrom(0, cur, from, to, amount))
}

// Claim gives every address a one-time airdrop of ClaimAmount HEARTH,
// drawn from the realm reserve.
func Claim(cur realm) {
	caller := cur.Previous().Address()
	if claimed.Has(caller.String()) {
		panic("HEARTH already claimed by this address")
	}
	claimed.Set(caller.String(), true)
	disburse(cur, caller, ClaimAmount)
	chain.Emit("Claim", "to", caller.String(), "amount", strconv.Itoa(ClaimAmount))
}

// Faucet is the demo tap: anyone may draw FaucetAmount HEARTH per call
// until the reserve is empty (then the transfer fails and the call
// panics, which is the intended stop condition).
func Faucet(cur realm) {
	caller := cur.Previous().Address()
	disburse(cur, caller, FaucetAmount)
	chain.Emit("Faucet", "to", caller.String(), "amount", strconv.Itoa(FaucetAmount))
}

// disburse moves amount HEARTH from the realm reserve to `to`.
func disburse(cur realm, to address, amount int64) {
	teller := token.RealmTeller(0, cur)
	mustNoErr(teller.Transfer(0, cur, to, amount))
}

func mustPositive(amount int64) {
	if amount <= 0 {
		panic("amount must be positive")
	}
}

func mustNonNegative(amount int64) {
	if amount < 0 {
		panic("amount must not be negative")
	}
}

func mustNoErr(err error) {
	if err != nil {
		panic(err)
	}
}

package hearthcouncil

// HearthCouncil is a DAO voting realm on Gno.land.
//
// Voting model (the core design decision — see DESIGN.md §4–5):
//   - Voting power is ESCROWED HEARTH, not a plain balance read. A voter
//     first Approves this realm on the HEARTH token, then Deposits.
//     Weight = own deposit + deposits of everyone delegating directly
//     to the voter (one level only; chains do not propagate).
//   - Why escrow: a plain balance read lets a voter vote, transfer the
//     tokens to a second address, and vote again with the same tokens.
//     Escrowed tokens sit in this realm, so they cannot move while a
//     vote is active: every vote locks each contributor's deposit until
//     the proposal is finalized, and Withdraw refuses locked funds.
//   - Delegation changes are refused while the delegator's tokens are
//     locked in an active vote, so a delegate can never double-count
//     the same deposit on one proposal via a mid-vote re-delegation.
//
// Lifecycle: Active → (Finalize, after EndHeight) → Succeeded/Defeated
// → (Queue) → Queued → (Execute, after ETA) → Executed.
// Anyone may call Finalize/Queue/Execute: they are permissionless state
// transitions. All failures panic (state reverts, per Gno semantics).
//
// Whitelisted actions (executed cross-realm from Execute):
//   - "set_param" on the hearthregistry realm, args "key=value".
//   - "release" from the DAO treasury, args "recipient:amount".
//     The treasury is the DAO's HEARTH balance minus total deposits:
//     only donated/seeded funds can be released, never deposits.

import (
	"strconv"
	"strings"

	"chain"
	"chain/runtime"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/ufmt/v0"
	"gno.land/r/g1utqjz9adrhy5y26hfufgqyua0srsxwkf776vzd/hearth"
	"gno.land/r/g1utqjz9adrhy5y26hfufgqyua0srsxwkf776vzd/hearthregistry"
)

const (
	// MinProposalBalance is the HEARTH balance a proposer must hold.
	MinProposalBalance = 100
	// VotingPeriod is how long a proposal stays open (blocks).
	// Demo-tuned (~10 min at ~6s/block) so judges can see the full
	// flow in one session; a production deployment would use days.
	VotingPeriod = 100
	// TimelockDelay is the wait between Queue and Execute (blocks).
	// Demo-tuned (~5 min); production would use ~2 days.
	TimelockDelay = 50
	// QuorumBps is the required participation, in basis points of the
	// total supply snapshotted when the proposal is created (400 = 4%).
	QuorumBps = 400
	// RegistryPkgPath is the only allowed target for "set_param".
	RegistryPkgPath = "gno.land/r/g1utqjz9adrhy5y26hfufgqyua0srsxwkf776vzd/hearthregistry"
)

// ProposalStatus tracks a proposal through its lifecycle.
type ProposalStatus int

const (
	StatusActive ProposalStatus = iota
	StatusSucceeded
	StatusDefeated
	StatusQueued
	StatusExecuted
)

func (s ProposalStatus) String() string {
	switch s {
	case StatusActive:
		return "Active"
	case StatusSucceeded:
		return "Succeeded"
	case StatusDefeated:
		return "Defeated"
	case StatusQueued:
		return "Queued"
	case StatusExecuted:
		return "Executed"
	default:
		return "Unknown"
	}
}

// Proposal is one governance proposal. It is stored by value copy in the
// proposals tree; GetProposal returns a copy, never a pointer to state.
type Proposal struct {
	ID           uint64
	Proposer     address
	Title        string
	Description  string
	Target       string // realm path, or "" for treasury actions
	Action       string // "set_param" | "release"
	Args         string // raw args as submitted ("key=value" | "recipient:amount")
	ParamKey     string // parsed from Args for set_param
	ParamValue   string // parsed from Args for set_param
	ReleaseTo    address // parsed from Args for release
	ReleaseAmt   int64   // parsed from Args for release
	StartHeight  int64
	EndHeight    int64
	ForVotes     int64
	AgainstVotes int64
	Status       ProposalStatus
	Quorum       int64 // required participation, snapshotted at creation
	TotalSupply  int64 // snapshotted at creation
	ETA          int64 // first height Execute is allowed (0 until queued)
	ExecutedAt   int64
}

var (
	proposals      avl.Tree // padded ID string -> *Proposal
	nextID         uint64
	deposited      avl.Tree // address string -> int64 escrowed HEARTH
	locked         avl.Tree // address string -> int64 locked in active votes
	delegatedTo    avl.Tree // delegator address string -> delegate address string
	delegatedPower avl.Tree // delegate address string -> int64 (direct delegators' deposits)
	delegators     avl.Tree // "delegate:delegator" -> true (reverse index)
	voteLocks      avl.Tree // "paddedID:address" -> int64 locked by that vote
	voted          avl.Tree // "paddedID:address" -> true
	totalDeposited int64
	daoAddr        address
)

func init(cur realm) {
	daoAddr = cur.Address()
}

// ---- read-only ----

// DAOAddress returns this realm's own address (the deposit + treasury holder).
func DAOAddress() address {
	return daoAddr
}

// ProposalCount returns the number of proposals ever created.
func ProposalCount() int {
	return int(nextID)
}

// GetProposal returns a copy of the proposal, or panics if it does not exist.
func GetProposal(id uint64) Proposal {
	p := mustProposal(id)
	return *p
}

// Deposited returns how much HEARTH addr has escrowed in the DAO.
func Deposited(addr address) int64 {
	return getInt(&deposited, addr.String())
}

// Locked returns how much of addr's deposit is locked in active votes.
func Locked(addr address) int64 {
	return getInt(&locked, addr.String())
}

// Unlocked returns the withdrawable part of addr's deposit.
func Unlocked(addr address) int64 {
	return Deposited(addr) - Locked(addr)
}

// DelegatedTo returns the address addr delegated to, or "" if none.
func DelegatedTo(addr address) address {
	v := delegatedTo.Get(addr.String())
	if v == nil {
		return address("")
	}
	return address(v.(string))
}

// DelegatedPower returns the voting power delegated directly to addr
// (the sum of its direct delegators' deposits).
func DelegatedPower(addr address) int64 {
	return getInt(&delegatedPower, addr.String())
}

// VotingPower returns addr's current voting weight: own deposit (only if
// addr has not delegated it away) plus power delegated directly to addr.
func VotingPower(addr address) int64 {
	power := DelegatedPower(addr)
	if !delegatedTo.Has(addr.String()) {
		power += Deposited(addr)
	}
	return power
}

// HasVoted reports whether addr already voted on proposal id.
func HasVoted(id uint64, addr address) bool {
	return voted.Has(voteKey(id, addr))
}

// TotalDeposited returns all HEARTH currently escrowed by voters.
func TotalDeposited() int64 {
	return totalDeposited
}

// Treasury returns the DAO's spendable HEARTH: its token balance minus
// all deposits (deposits are never spendable by proposals).
func Treasury() int64 {
	return hearth.BalanceOf(daoAddr) - totalDeposited
}

// DelegatorsOf returns the addresses delegating directly to addr.
func DelegatorsOf(addr address) []address {
	prefix := addr.String() + ":"
	out := []address{}
	delegators.Iterate(prefix, prefixEnd(prefix), func(key string, value any) bool {
		parts := strings.SplitN(key, ":", 2)
		if len(parts) == 2 {
			out = append(out, address(parts[1]))
		}
		return false
	})
	return out
}

// ---- deposits ----

// Deposit escrows amount HEARTH into the DAO. The caller must first
// Approve this realm on the HEARTH token for at least amount.
func Deposit(cur realm, amount int64) {
	caller := cur.Previous().Address()
	if amount <= 0 {
		panic("deposit amount must be positive")
	}
	hearth.TransferFrom(cross(cur), caller, daoAddr, amount)
	addInt(&deposited, caller.String(), amount)
	totalDeposited += amount
	if to, ok := delegateOf(caller); ok {
		addInt(&delegatedPower, to, amount)
	}
	chain.Emit("Deposit", "from", caller.String(), "amount", strconv.FormatInt(amount, 10))
}

// Withdraw returns amount of the caller's unlocked deposit.
func Withdraw(cur realm, amount int64) {
	caller := cur.Previous().Address()
	if amount <= 0 {
		panic("withdraw amount must be positive")
	}
	if amount > Unlocked(caller) {
		panic("amount exceeds unlocked deposit")
	}
	addInt(&deposited, caller.String(), -amount)
	totalDeposited -= amount
	if to, ok := delegateOf(caller); ok {
		addInt(&delegatedPower, to, -amount)
	}
	hearth.Transfer(cross(cur), caller, amount)
	chain.Emit("Withdraw", "to", caller.String(), "amount", strconv.FormatInt(amount, 10))
}

// ---- delegation ----

// Delegate moves the caller's voting power to `to` (one level only).
// It is refused while the caller's tokens are locked in an active vote.
func Delegate(cur realm, to address) {
	caller := cur.Previous().Address()
	if to == caller {
		panic("cannot delegate to yourself")
	}
	if delegatedTo.Has(caller.String()) {
		panic("already delegating; undelegate first")
	}
	if Locked(caller) > 0 {
		panic("cannot change delegation while your tokens are locked in an active vote")
	}
	delegatedTo.Set(caller.String(), to.String())
	delegators.Set(to.String()+":"+caller.String(), true)
	addInt(&delegatedPower, to.String(), Deposited(caller))
	chain.Emit("Delegate", "from", caller.String(), "to", to.String())
}

// Undelegate returns the caller's voting power to itself. Refused while
// the caller's tokens are locked in an active vote.
func Undelegate(cur realm) {
	caller := cur.Previous().Address()
	to, ok := delegateOf(caller)
	if !ok {
		panic("not delegating")
	}
	if Locked(caller) > 0 {
		panic("cannot change delegation while your tokens are locked in an active vote")
	}
	addInt(&delegatedPower, to, -Deposited(caller))
	delegatedTo.Remove(caller.String())
	delegators.Remove(to + ":" + caller.String())
	chain.Emit("Undelegate", "from", caller.String(), "to", to)
}

// ---- proposals ----

// CreateProposal opens a new proposal and returns its ID. The proposer
// must have at least MinProposalBalance HEARTH deposited in the DAO
// (escrowed stake is the anti-spam bar — a proposer who deposited
// everything can still propose). Args format depends on Action:
//   - "set_param": target must be the hearthregistry realm, args "key=value"
//   - "release":   target must be "", args "recipient:amount" (g1 address)
func CreateProposal(cur realm, title, desc, target, action, args string) uint64 {
	caller := cur.Previous().Address()
	if Deposited(caller) < MinProposalBalance {
		panic("need at least 100 HEARTH deposited to propose")
	}
	if title == "" || desc == "" {
		panic("title and description must not be empty")
	}
	p := &Proposal{
		ID:          nextID,
		Proposer:    caller,
		Title:       title,
		Description: desc,
		Target:      target,
		Action:      action,
		Args:        args,
		Status:      StatusActive,
	}
	switch action {
	case "set_param":
		if target != RegistryPkgPath {
			panic("set_param target must be the hearthregistry realm")
		}
		k, v, ok := splitKV(args)
		if !ok || k == "" || v == "" {
			panic("set_param args must be key=value")
		}
		p.ParamKey, p.ParamValue = k, v
	case "release":
		if target != "" {
			panic("release target must be empty (treasury is the DAO itself)")
		}
		to, amount, ok := splitRelease(args)
		if !ok {
			panic("release args must be recipient:amount")
		}
		if amount <= 0 {
			panic("release amount must be positive")
		}
		p.ReleaseTo, p.ReleaseAmt = to, amount
	default:
		panic("unknown action; allowed: set_param, release")
	}
	now := runtime.ChainHeight()
	totalSupply := hearth.TotalSupply()
	p.StartHeight = now
	p.EndHeight = now + VotingPeriod
	p.Quorum = totalSupply * QuorumBps / 10000
	p.TotalSupply = totalSupply
	proposals.Set(pkey(p.ID), p)
	nextID++
	chain.Emit("ProposalCreated", "id", strconv.FormatUint(p.ID, 10), "proposer", caller.String(), "action", action)
	return p.ID
}

// Vote casts the caller's full current voting weight for or against a
// proposal, and locks each contributing deposit until finalization.
func Vote(cur realm, id uint64, support bool) {
	caller := cur.Previous().Address()
	p := mustProposal(id)
	if p.Status != StatusActive {
		panic("proposal is not active")
	}
	now := runtime.ChainHeight()
	if now < p.StartHeight || now >= p.EndHeight {
		panic("voting is closed for this proposal")
	}
	if voted.Has(voteKey(id, caller)) {
		panic("already voted on this proposal")
	}
	weight := VotingPower(caller)
	if weight <= 0 {
		panic("no voting power: deposit HEARTH or receive a delegation first")
	}
	voted.Set(voteKey(id, caller), true)
	if support {
		p.ForVotes += weight
	} else {
		p.AgainstVotes += weight
	}
	proposals.Set(pkey(id), p)
	// Lock every deposit that contributed to this vote.
	if !delegatedTo.Has(caller.String()) {
		lockAmount(id, caller, Deposited(caller))
	}
	for _, d := range DelegatorsOf(caller) {
		lockAmount(id, d, Deposited(d))
	}
	chain.Emit("VoteCast", "id", strconv.FormatUint(id, 10), "voter", caller.String(), "weight", strconv.FormatInt(weight, 10))
}

// Finalize closes voting on a proposal once EndHeight has passed and
// sets Succeeded (quorum met and for > against) or Defeated, releasing
// all vote locks for the proposal.
func Finalize(cur realm, id uint64) {
	p := mustProposal(id)
	if p.Status != StatusActive {
		panic("proposal is not active")
	}
	if runtime.ChainHeight() < p.EndHeight {
		panic("voting is still open")
	}
	if p.ForVotes+p.AgainstVotes >= p.Quorum && p.ForVotes > p.AgainstVotes {
		p.Status = StatusSucceeded
	} else {
		p.Status = StatusDefeated
	}
	proposals.Set(pkey(id), p)
	releaseLocks(id)
	chain.Emit("ProposalFinalized", "id", strconv.FormatUint(id, 10), "status", p.Status.String())
}

// Queue moves a succeeded proposal into the timelock. Execute is allowed
// from ETA = current height + TimelockDelay.
func Queue(cur realm, id uint64) {
	p := mustProposal(id)
	if p.Status != StatusSucceeded {
		panic("only a succeeded proposal can be queued")
	}
	p.Status = StatusQueued
	p.ETA = runtime.ChainHeight() + TimelockDelay
	proposals.Set(pkey(id), p)
	chain.Emit("ProposalQueued", "id", strconv.FormatUint(id, 10), "eta", strconv.FormatInt(p.ETA, 10))
}

// Execute runs a queued proposal after its timelock expired. The action
// is executed cross-realm (set_param) or from the treasury (release).
func Execute(cur realm, id uint64) {
	p := mustProposal(id)
	if p.Status != StatusQueued {
		panic("only a queued proposal can be executed")
	}
	if runtime.ChainHeight() < p.ETA {
		panic("timelock has not expired")
	}
	switch p.Action {
	case "set_param":
		hearthregistry.SetParam(cross(cur), p.ParamKey, p.ParamValue)
	case "release":
		if p.ReleaseAmt > Treasury() {
			panic("treasury cannot cover this release")
		}
		hearth.Transfer(cross(cur), p.ReleaseTo, p.ReleaseAmt)
	default:
		panic("unknown action")
	}
	p.Status = StatusExecuted
	p.ExecutedAt = runtime.ChainHeight()
	proposals.Set(pkey(id), p)
	chain.Emit("ProposalExecuted", "id", strconv.FormatUint(id, 10), "action", p.Action)
}

// ---- internals ----

func mustProposal(id uint64) *Proposal {
	v := proposals.Get(pkey(id))
	if v == nil {
		panic("proposal not found")
	}
	return v.(*Proposal)
}

func getInt(tree *avl.Tree, key string) int64 {
	v := tree.Get(key)
	if v == nil {
		return 0
	}
	return v.(int64)
}

func addInt(tree *avl.Tree, key string, delta int64) {
	tree.Set(key, getInt(tree, key)+delta)
}

func delegateOf(addr address) (string, bool) {
	v := delegatedTo.Get(addr.String())
	if v == nil {
		return "", false
	}
	return v.(string), true
}

// lockAmount records that amount of addr's deposit is committed to the
// vote on proposal id until finalization.
func lockAmount(id uint64, addr address, amount int64) {
	if amount <= 0 {
		return
	}
	voteLocks.Set(lockKey(id, addr), amount)
	addInt(&locked, addr.String(), amount)
}

// releaseLocks frees every deposit locked by votes on proposal id.
func releaseLocks(id uint64) {
	prefix := pkey(id) + ":"
	keys := []string{}
	voteLocks.Iterate(prefix, prefixEnd(prefix), func(key string, value any) bool {
		keys = append(keys, key)
		return false
	})
	for _, key := range keys {
		amount := voteLocks.Get(key).(int64)
		addr := key[len(prefix):]
		addInt(&locked, addr, -amount)
		voteLocks.Remove(key)
	}
}

// pkey pads the proposal ID so avl iteration order is numeric.
func pkey(id uint64) string {
	return ufmt.Sprintf("%020d", id)
}

// voteKey / lockKey share the "paddedID:address" scheme.
func voteKey(id uint64, addr address) string {
	return pkey(id) + ":" + addr.String()
}

func lockKey(id uint64, addr address) string {
	return pkey(id) + ":" + addr.String()
}

// prefixEnd returns the smallest string greater than every string with
// the given prefix (for avl range iteration).
func prefixEnd(prefix string) string {
	b := []byte(prefix)
	b[len(b)-1]++
	return string(b)
}

// splitKV parses "key=value".
func splitKV(args string) (string, string, bool) {
	i := strings.Index(args, "=")
	if i < 0 {
		return "", "", false
	}
	return args[:i], args[i+1:], true
}

// splitRelease parses "recipient:amount" with a g1 recipient address.
func splitRelease(args string) (address, int64, bool) {
	i := strings.Index(args, ":")
	if i < 0 {
		return address(""), 0, false
	}
	to := args[:i]
	if len(to) != 40 || !strings.HasPrefix(to, "g1") {
		return address(""), 0, false
	}
	amount, err := strconv.ParseInt(args[i+1:], 10, 64)
	if err != nil {
		return address(""), 0, false
	}
	return address(to), amount, true
}

package hearthcouncil

// Render is the DAO's UI for gnoweb: proposal list, per-proposal detail,
// and the delegation overview. All user-supplied text (titles,
// descriptions) is sanitized before being printed.

import (
	"strconv"
	"strings"

	"gno.land/p/nt/markdown/sanitize/v0"
	"gno.land/p/nt/ufmt/v0"
	"gno.land/r/g1utqjz9adrhy5y26hfufgqyua0srsxwkf776vzd/hearth"
	"chain/runtime"
)

func Render(path string) string {
	// Detail view: the proposal id arrives as the URL args after ":",
	// e.g. /r/.../hearthcouncil:0 . A leading "/" is tolerated.
	idStr := strings.TrimPrefix(path, "/")
	if idStr != "" {
		if id, err := strconv.Atoi(idStr); err == nil && id >= 0 {
			return renderProposal(uint64(id))
		}
	}
	return renderList()
}

func renderList() string {
	out := "# HearthCouncil — DAO voting realm\n\n"
	out += "Vote weight comes from HEARTH escrowed in this realm (Deposit\n"
	out += "after Approving the DAO on the HEARTH token). Delegation is one\n"
	out += "level: your delegate votes with your deposit.\n\n"
	out += ufmt.Sprintf("- HEARTH total supply: %d\n", hearth.TotalSupply())
	out += ufmt.Sprintf("- Escrowed in the DAO: %d HEARTH\n", TotalDeposited())
	out += ufmt.Sprintf("- Treasury (spendable): %d HEARTH\n", Treasury())
	out += ufmt.Sprintf("- Proposals: %d\n", ProposalCount())
	out += ufmt.Sprintf("- Quorum: %d%% of supply at proposal creation\n", QuorumBps/100)
	out += ufmt.Sprintf("- Voting period: %d blocks, timelock: %d blocks\n", VotingPeriod, TimelockDelay)
	out += ufmt.Sprintf("- Current height: %d\n", runtime.ChainHeight())
	out += "\n## Proposals\n\n"
	if ProposalCount() == 0 {
		out += "No proposals yet. Hold at least 100 HEARTH and call\n"
		out += "CreateProposal to open the first one.\n"
		return out
	}
	out += "| ID | Title | Status | For | Against | Quorum |\n"
	out += "|----|-------|--------|-----|---------|--------|\n"
	proposals.Iterate("", "", func(key string, value any) bool {
		p := value.(*Proposal)
		quorum := "—"
		if p.Quorum > 0 {
			quorum = ufmt.Sprintf("%d%%", (p.ForVotes+p.AgainstVotes)*100/p.Quorum)
		}
		out += ufmt.Sprintf("| %d | %s | %s | %d | %d | %s |\n",
			p.ID, sanitize.InlineText(p.Title), p.Status.String(),
			p.ForVotes, p.AgainstVotes, quorum)
		return false
	})
	out += "\nOpen a proposal's detail page by appending :<id> to this realm's URL (e.g. .../hearthcouncil:0).\n"
	return out
}

func renderProposal(id uint64) string {
	if !proposals.Has(pkey(id)) {
		return ufmt.Sprintf("# Proposal #%d — not found\n\nNo proposal with this ID exists yet.\n", id)
	}
	p := mustProposal(id)
	out := ufmt.Sprintf("# Proposal #%d — %s\n\n", p.ID, sanitize.InlineText(p.Title))
	out += ufmt.Sprintf("- Status: **%s**\n", p.Status.String())
	out += ufmt.Sprintf("- Proposer: %s\n", p.Proposer.String())
	out += ufmt.Sprintf("- Action: %s (target: %s)\n", p.Action, p.Target)
	out += ufmt.Sprintf("- Args: %s\n", sanitize.InlineText(p.Args))
	out += ufmt.Sprintf("- Voting: heights %d–%d (now: %d)\n", p.StartHeight, p.EndHeight, runtime.ChainHeight())
	out += ufmt.Sprintf("- For: %d, Against: %d, Quorum needed: %d\n", p.ForVotes, p.AgainstVotes, p.Quorum)
	if p.Status == StatusQueued {
		out += ufmt.Sprintf("- Timelock ETA: height %d (now: %d)\n", p.ETA, runtime.ChainHeight())
	}
	if p.Status == StatusExecuted {
		out += ufmt.Sprintf("- Executed at height: %d\n", p.ExecutedAt)
	}
	out += "\n## Description\n\n"
	out += sanitize.Block(p.Description)
	out += "\n\n## How to vote\n\n"
	out += "1. Get HEARTH from the hearth realm (Claim or Faucet).\n"
	out += "2. Approve this realm on the HEARTH token, then Deposit.\n"
	out += "3. Call Vote with this proposal's ID and your support (true/false).\n"
	out += "4. After voting ends, anyone may call Finalize, then Queue,\n"
	out += "   then Execute once the timelock expires.\n"
	return out
}

// Package fpmm implements a deterministic, zero-float, overflow-safe
// binary Fixed-Product Market Maker (Constant-Product Market Maker)
// for prediction markets on Gno.land.
//
// # Model
//
// Each unit of collateral backs one complete set of outcome shares
// (1 YES + 1 NO). The market maker maintains reserves (ReserveYes, ReserveNo)
// subject to the constant-product invariant:
//
//	ReserveYes * ReserveNo >= k
//
// Implied probability of YES in basis points is:
//
//	ReserveNo * 10_000 / (ReserveYes + ReserveNo)
//
// # Arithmetic & Rounding Invariants
//
// All intermediate products use exact 128-bit unsigned arithmetic (via math/bits)
// and all rounding favors the pool:
//   - Fees and required pool reserves round UP (ceil).
//   - Share outputs, collateral payouts, LP shares minted, and withdrawn
//     reserves round DOWN (floor).
//   - LP fee debt rounds UP on entry and LP fee entitlement rounds DOWN,
//     preventing retroactive fee extraction and ensuring sum(payouts) <= fees.
//
// All exported functions are pure and stateless. Callers handle coin custody
// and storage persistence.
package fpmm

package fpmm

import (
	"errors"
	"math/overflow"
)

const (
	// BpsScale is 100.00% expressed in basis points.
	BpsScale int64 = 10_000

	// MaxFeeBps caps swap fees at 10.00% (1,000 bps).
	MaxFeeBps int64 = 1_000

	// MinReserve is the minimum reserve per outcome side after pool init
	// or liquidity removal so odds never collapse into degenerate dust.
	MinReserve int64 = 100

	// MaxReserve caps individual reserves and inputs at 10^15 ugnot
	// (1 billion GNOT), preventing intermediate arithmetic overflow.
	MaxReserve int64 = 1_000_000_000_000_000

	// FeeAccScale scales per-LP-share fee accruals by 10^12 for sub-ugnot precision.
	FeeAccScale uint64 = 1_000_000_000_000

	maxInt64 = int64(1<<63 - 1)
)

// Side identifies an outcome share in a binary market.
type Side uint8

const (
	SideYes Side = 1
	SideNo  Side = 2
)

// Valid reports whether s is SideYes or SideNo.
func (s Side) Valid() bool {
	return s == SideYes || s == SideNo
}

// String returns the human-readable outcome label.
func (s Side) String() string {
	switch s {
	case SideYes:
		return "YES"
	case SideNo:
		return "NO"
	default:
		return "UNKNOWN"
	}
}

var (
	ErrInvalidReserve        = errors.New("fpmm: invalid reserve")
	ErrInvalidAmount         = errors.New("fpmm: invalid amount")
	ErrInvalidFeeBps         = errors.New("fpmm: invalid fee bps")
	ErrInvalidSide           = errors.New("fpmm: invalid side")
	ErrZeroOutput            = errors.New("fpmm: output is zero")
	ErrSlippage              = errors.New("fpmm: slippage limit exceeded")
	ErrOverflow              = errors.New("fpmm: arithmetic overflow")
	ErrInsufficientLiquidity = errors.New("fpmm: insufficient liquidity")
)

// Pool holds the constant-product state for a binary prediction market.
type Pool struct {
	ReserveYes int64
	ReserveNo  int64
	TotalLP    int64
	FeeBps     int64
}

// BuyQuote describes the state transition for buying outcome shares.
type BuyQuote struct {
	SharesOut     int64
	Fee           int64
	NetCollateral int64
	NewReserveYes int64
	NewReserveNo  int64
	NewYesProbBps int64
}

// SellQuote describes the state transition for selling outcome shares.
type SellQuote struct {
	CollateralOut   int64
	Fee             int64
	GrossCollateral int64
	NewReserveYes   int64
	NewReserveNo    int64
	NewYesProbBps   int64
}

// AddLiquidityQuote describes a proportional liquidity deposit.
// For skewed pools, excess shares on the scarcer side are returned as RefundShares.
type AddLiquidityQuote struct {
	LPMinted      int64
	AddedYes      int64
	AddedNo       int64
	RefundSide    Side
	RefundShares  int64
	NewReserveYes int64
	NewReserveNo  int64
}

// RemoveLiquidityQuote describes a proportional liquidity withdrawal.
// Equal YES/NO reserves are merged into CollateralOut; excess skew is returned as shares.
type RemoveLiquidityQuote struct {
	CollateralOut int64
	YesOut        int64
	NoOut         int64
	NewReserveYes int64
	NewReserveNo  int64
}

// FeeAccumulator stores a 128-bit magnified fee-per-LP-share accumulator.
type FeeAccumulator struct {
	AccHi uint64
	AccLo uint64
}

// NewPool initializes a balanced 50/50 binary CPMM pool backed by initialCollateral.
func NewPool(initialCollateral, feeBps int64) (Pool, error) {
	if initialCollateral < MinReserve || initialCollateral > MaxReserve {
		return Pool{}, ErrInvalidReserve
	}
	if feeBps < 0 || feeBps > MaxFeeBps {
		return Pool{}, ErrInvalidFeeBps
	}
	return Pool{
		ReserveYes: initialCollateral,
		ReserveNo:  initialCollateral,
		TotalLP:    initialCollateral,
		FeeBps:     feeBps,
	}, nil
}

// Validate checks that pool reserves, LP supply, and fee parameters are well-formed.
func (p Pool) Validate() error {
	if p.ReserveYes < 1 || p.ReserveYes > MaxReserve {
		return ErrInvalidReserve
	}
	if p.ReserveNo < 1 || p.ReserveNo > MaxReserve {
		return ErrInvalidReserve
	}
	if p.TotalLP < 1 || p.TotalLP > MaxReserve {
		return ErrInsufficientLiquidity
	}
	if p.FeeBps < 0 || p.FeeBps > MaxFeeBps {
		return ErrInvalidFeeBps
	}
	return nil
}

// YesProbBps returns the implied YES probability in [0, 10000] basis points.
func (p Pool) YesProbBps() int64 {
	if p.ReserveYes <= 0 || p.ReserveNo <= 0 {
		return 0
	}
	sum := uint64(p.ReserveYes) + uint64(p.ReserveNo)
	prob, ok := mulDivFloor(uint64(p.ReserveNo), uint64(BpsScale), sum)
	if !ok {
		return 0
	}
	return int64(prob)
}

// NoProbBps returns the implied NO probability in [0, 10000] basis points.
func (p Pool) NoProbBps() int64 {
	if p.ReserveYes <= 0 || p.ReserveNo <= 0 {
		return 0
	}
	return BpsScale - p.YesProbBps()
}

// InvariantHiLo returns the exact 128-bit product ReserveYes * ReserveNo.
func (p Pool) InvariantHiLo() (hi, lo uint64) {
	if p.ReserveYes <= 0 || p.ReserveNo <= 0 {
		return 0, 0
	}
	k := u128Mul64(uint64(p.ReserveYes), uint64(p.ReserveNo))
	return k.hi, k.lo
}

// QuoteBuy calculates the exact outcome shares received for grossCollateral ugnot.
func (p Pool) QuoteBuy(side Side, grossCollateral int64) (BuyQuote, error) {
	if err := p.Validate(); err != nil {
		return BuyQuote{}, err
	}
	if !side.Valid() {
		return BuyQuote{}, ErrInvalidSide
	}
	if grossCollateral <= 0 || grossCollateral > MaxReserve {
		return BuyQuote{}, ErrInvalidAmount
	}

	var fee int64
	if p.FeeBps > 0 {
		f, ok := mulDivCeil(uint64(grossCollateral), uint64(p.FeeBps), uint64(BpsScale))
		if !ok || f > uint64(maxInt64) {
			return BuyQuote{}, ErrOverflow
		}
		fee = int64(f)
	}
	net := grossCollateral - fee
	if net <= 0 {
		return BuyQuote{}, ErrZeroOutput
	}

	rTarget, rOther := p.ReserveYes, p.ReserveNo
	if side == SideNo {
		rTarget, rOther = p.ReserveNo, p.ReserveYes
	}

	newOther, ok := overflow.Add64(rOther, net)
	if !ok || newOther > MaxReserve {
		return BuyQuote{}, ErrOverflow
	}
	poolPlusNet, ok := overflow.Add64(rTarget, net)
	if !ok {
		return BuyQuote{}, ErrOverflow
	}

	newTargetU64, ok := mulDivCeil(uint64(rTarget), uint64(rOther), uint64(newOther))
	if !ok || newTargetU64 > uint64(MaxReserve) {
		return BuyQuote{}, ErrOverflow
	}
	newTarget := int64(newTargetU64)
	if newTarget < 1 {
		newTarget = 1
	}
	if newTarget >= poolPlusNet {
		return BuyQuote{}, ErrZeroOutput
	}
	sharesOut := poolPlusNet - newTarget

	newYes, newNo := newTarget, newOther
	if side == SideNo {
		newYes, newNo = newOther, newTarget
	}

	nextPool := Pool{
		ReserveYes: newYes,
		ReserveNo:  newNo,
		TotalLP:    p.TotalLP,
		FeeBps:     p.FeeBps,
	}

	return BuyQuote{
		SharesOut:     sharesOut,
		Fee:           fee,
		NetCollateral: net,
		NewReserveYes: newYes,
		NewReserveNo:  newNo,
		NewYesProbBps: nextPool.YesProbBps(),
	}, nil
}

// ApplyBuy executes a buy quote against slippage protection minSharesOut.
func (p Pool) ApplyBuy(side Side, grossCollateral, minSharesOut int64) (Pool, BuyQuote, error) {
	if minSharesOut < 0 {
		return Pool{}, BuyQuote{}, ErrInvalidAmount
	}
	q, err := p.QuoteBuy(side, grossCollateral)
	if err != nil {
		return Pool{}, BuyQuote{}, err
	}
	if q.SharesOut < minSharesOut {
		return Pool{}, BuyQuote{}, ErrSlippage
	}
	next := Pool{
		ReserveYes: q.NewReserveYes,
		ReserveNo:  q.NewReserveNo,
		TotalLP:    p.TotalLP,
		FeeBps:     p.FeeBps,
	}
	return next, q, nil
}

// QuoteSell calculates exact net collateral returned when selling sharesIn back to the pool.
func (p Pool) QuoteSell(side Side, sharesIn int64) (SellQuote, error) {
	if err := p.Validate(); err != nil {
		return SellQuote{}, err
	}
	if !side.Valid() {
		return SellQuote{}, ErrInvalidSide
	}
	if sharesIn <= 0 || sharesIn > MaxReserve {
		return SellQuote{}, ErrInvalidAmount
	}

	rTarget, rOther := p.ReserveYes, p.ReserveNo
	if side == SideNo {
		rTarget, rOther = p.ReserveNo, p.ReserveYes
	}

	lhs, ok := overflow.Add64(rTarget, sharesIn)
	if !ok || lhs > MaxReserve {
		return SellQuote{}, ErrOverflow
	}

	// Solve c^2 - B*c + rOther*sharesIn >= 0 with B = rTarget + rOther + sharesIn.
	// Discriminant: B^2 - 4*rOther*sharesIn = (lhs - rOther)^2 + 4*rTarget*rOther.
	bCoeff := uint64(lhs) + uint64(rOther)
	var absDiff uint64
	if lhs >= rOther {
		absDiff = uint64(lhs - rOther)
	} else {
		absDiff = uint64(rOther - lhs)
	}

	term1 := u128Mul64(absDiff, absDiff)
	k := u128Mul64(uint64(rTarget), uint64(rOther))
	twoK, ok := u128Add(k, k)
	if !ok {
		return SellQuote{}, ErrOverflow
	}
	fourK, ok := u128Add(twoK, twoK)
	if !ok {
		return SellQuote{}, ErrOverflow
	}
	disc, ok := u128Add(term1, fourK)
	if !ok {
		return SellQuote{}, ErrOverflow
	}

	// Ceiling sqrt guarantees grossCollateral rounds down so k' >= k holds strictly.
	sqrtCeil, ok := u128SqrtCeil(disc)
	if !ok {
		return SellQuote{}, ErrOverflow
	}
	if sqrtCeil >= bCoeff {
		return SellQuote{}, ErrZeroOutput
	}
	grossU64 := (bCoeff - sqrtCeil) / 2
	if grossU64 == 0 {
		return SellQuote{}, ErrZeroOutput
	}
	if grossU64 > uint64(maxInt64) {
		return SellQuote{}, ErrOverflow
	}
	gross := int64(grossU64)

	newTarget := lhs - gross
	newOther := rOther - gross
	if newTarget < 1 || newOther < 1 {
		return SellQuote{}, ErrZeroOutput
	}
	if newTarget > MaxReserve {
		return SellQuote{}, ErrOverflow
	}

	var fee int64
	if p.FeeBps > 0 {
		f, ok := mulDivCeil(uint64(gross), uint64(p.FeeBps), uint64(BpsScale))
		if !ok || f > uint64(maxInt64) {
			return SellQuote{}, ErrOverflow
		}
		fee = int64(f)
	}
	netOut := gross - fee
	if netOut <= 0 {
		return SellQuote{}, ErrZeroOutput
	}

	newYes, newNo := newTarget, newOther
	if side == SideNo {
		newYes, newNo = newOther, newTarget
	}

	nextPool := Pool{
		ReserveYes: newYes,
		ReserveNo:  newNo,
		TotalLP:    p.TotalLP,
		FeeBps:     p.FeeBps,
	}

	return SellQuote{
		CollateralOut:   netOut,
		Fee:             fee,
		GrossCollateral: gross,
		NewReserveYes:   newYes,
		NewReserveNo:    newNo,
		NewYesProbBps:   nextPool.YesProbBps(),
	}, nil
}

// ApplySell executes a sell quote against slippage protection minCollateralOut.
func (p Pool) ApplySell(side Side, sharesIn, minCollateralOut int64) (Pool, SellQuote, error) {
	if minCollateralOut < 0 {
		return Pool{}, SellQuote{}, ErrInvalidAmount
	}
	q, err := p.QuoteSell(side, sharesIn)
	if err != nil {
		return Pool{}, SellQuote{}, err
	}
	if q.CollateralOut < minCollateralOut {
		return Pool{}, SellQuote{}, ErrSlippage
	}
	next := Pool{
		ReserveYes: q.NewReserveYes,
		ReserveNo:  q.NewReserveNo,
		TotalLP:    p.TotalLP,
		FeeBps:     p.FeeBps,
	}
	return next, q, nil
}

// QuoteAddLiquidity calculates LP shares minted and excess skew shares returned
// when depositing collateralIn ugnot proportionally to current reserves.
func (p Pool) QuoteAddLiquidity(collateralIn int64) (AddLiquidityQuote, error) {
	if err := p.Validate(); err != nil {
		return AddLiquidityQuote{}, err
	}
	if collateralIn <= 0 || collateralIn > MaxReserve {
		return AddLiquidityQuote{}, ErrInvalidAmount
	}

	var (
		addedYes     int64
		addedNo      int64
		refundSide   Side
		refundShares int64
		lpMintedU64  uint64
		ok           bool
	)

	if p.ReserveYes >= p.ReserveNo {
		addedYes = collateralIn
		addedNoU64, mulOk := mulDivFloor(uint64(collateralIn), uint64(p.ReserveNo), uint64(p.ReserveYes))
		if !mulOk || addedNoU64 > uint64(MaxReserve) {
			return AddLiquidityQuote{}, ErrOverflow
		}
		addedNo = int64(addedNoU64)
		refundShares = collateralIn - addedNo
		if refundShares > 0 {
			refundSide = SideNo
		}
		lpMintedU64, ok = mulDivFloor(uint64(addedNo), uint64(p.TotalLP), uint64(p.ReserveNo))
	} else {
		addedNo = collateralIn
		addedYesU64, mulOk := mulDivFloor(uint64(collateralIn), uint64(p.ReserveYes), uint64(p.ReserveNo))
		if !mulOk || addedYesU64 > uint64(MaxReserve) {
			return AddLiquidityQuote{}, ErrOverflow
		}
		addedYes = int64(addedYesU64)
		refundShares = collateralIn - addedYes
		if refundShares > 0 {
			refundSide = SideYes
		}
		lpMintedU64, ok = mulDivFloor(uint64(addedYes), uint64(p.TotalLP), uint64(p.ReserveYes))
	}

	if !ok || lpMintedU64 > uint64(MaxReserve) {
		return AddLiquidityQuote{}, ErrOverflow
	}
	lpMinted := int64(lpMintedU64)
	if lpMinted <= 0 {
		return AddLiquidityQuote{}, ErrZeroOutput
	}

	newYes, ok := overflow.Add64(p.ReserveYes, addedYes)
	if !ok || newYes > MaxReserve {
		return AddLiquidityQuote{}, ErrOverflow
	}
	newNo, ok := overflow.Add64(p.ReserveNo, addedNo)
	if !ok || newNo > MaxReserve {
		return AddLiquidityQuote{}, ErrOverflow
	}
	newTotalLP, ok := overflow.Add64(p.TotalLP, lpMinted)
	if !ok || newTotalLP > MaxReserve {
		return AddLiquidityQuote{}, ErrOverflow
	}

	return AddLiquidityQuote{
		LPMinted:      lpMinted,
		AddedYes:      addedYes,
		AddedNo:       addedNo,
		RefundSide:    refundSide,
		RefundShares:  refundShares,
		NewReserveYes: newYes,
		NewReserveNo:  newNo,
	}, nil
}

// ApplyAddLiquidity executes a liquidity deposit against slippage protection minLPMinted.
func (p Pool) ApplyAddLiquidity(collateralIn, minLPMinted int64) (Pool, AddLiquidityQuote, error) {
	if minLPMinted < 0 {
		return Pool{}, AddLiquidityQuote{}, ErrInvalidAmount
	}
	q, err := p.QuoteAddLiquidity(collateralIn)
	if err != nil {
		return Pool{}, AddLiquidityQuote{}, err
	}
	if q.LPMinted < minLPMinted {
		return Pool{}, AddLiquidityQuote{}, ErrSlippage
	}
	next := Pool{
		ReserveYes: q.NewReserveYes,
		ReserveNo:  q.NewReserveNo,
		TotalLP:    p.TotalLP + q.LPMinted,
		FeeBps:     p.FeeBps,
	}
	return next, q, nil
}

// QuoteRemoveLiquidity calculates merged collateral and excess shares withdrawn
// for burning lpBurn LP shares while keeping at least MinReserve on both sides.
func (p Pool) QuoteRemoveLiquidity(lpBurn int64) (RemoveLiquidityQuote, error) {
	if err := p.Validate(); err != nil {
		return RemoveLiquidityQuote{}, err
	}
	if lpBurn <= 0 || lpBurn > MaxReserve {
		return RemoveLiquidityQuote{}, ErrInvalidAmount
	}
	if lpBurn >= p.TotalLP {
		return RemoveLiquidityQuote{}, ErrInsufficientLiquidity
	}

	rawYesU64, ok := mulDivFloor(uint64(p.ReserveYes), uint64(lpBurn), uint64(p.TotalLP))
	if !ok {
		return RemoveLiquidityQuote{}, ErrOverflow
	}
	rawNoU64, ok := mulDivFloor(uint64(p.ReserveNo), uint64(lpBurn), uint64(p.TotalLP))
	if !ok {
		return RemoveLiquidityQuote{}, ErrOverflow
	}
	rawYes := int64(rawYesU64)
	rawNo := int64(rawNoU64)

	newYes := p.ReserveYes - rawYes
	newNo := p.ReserveNo - rawNo
	if newYes < MinReserve || newNo < MinReserve {
		return RemoveLiquidityQuote{}, ErrInsufficientLiquidity
	}

	merged := rawYes
	if rawNo < merged {
		merged = rawNo
	}
	yesOut := rawYes - merged
	noOut := rawNo - merged
	if merged == 0 && yesOut == 0 && noOut == 0 {
		return RemoveLiquidityQuote{}, ErrZeroOutput
	}

	return RemoveLiquidityQuote{
		CollateralOut: merged,
		YesOut:        yesOut,
		NoOut:         noOut,
		NewReserveYes: newYes,
		NewReserveNo:  newNo,
	}, nil
}

// ApplyRemoveLiquidity executes a proportional liquidity withdrawal.
func (p Pool) ApplyRemoveLiquidity(lpBurn int64) (Pool, RemoveLiquidityQuote, error) {
	q, err := p.QuoteRemoveLiquidity(lpBurn)
	if err != nil {
		return Pool{}, RemoveLiquidityQuote{}, err
	}
	next := Pool{
		ReserveYes: q.NewReserveYes,
		ReserveNo:  q.NewReserveNo,
		TotalLP:    p.TotalLP - lpBurn,
		FeeBps:     p.FeeBps,
	}
	return next, q, nil
}

// QuoteSettleLP computes floor-rounded pro-rata YES and NO reserves due to an LP
// upon market resolution so the sum across all LPs never exceeds settlement reserves.
func QuoteSettleLP(settlementYes, settlementNo, settlementLP, lpShares int64) (yesOut, noOut int64, err error) {
	if settlementLP <= 0 || settlementYes < 0 || settlementNo < 0 {
		return 0, 0, ErrInvalidReserve
	}
	if lpShares <= 0 || lpShares > settlementLP {
		return 0, 0, ErrInvalidAmount
	}
	yU64, ok := mulDivFloor(uint64(settlementYes), uint64(lpShares), uint64(settlementLP))
	if !ok || yU64 > uint64(maxInt64) {
		return 0, 0, ErrOverflow
	}
	nU64, ok := mulDivFloor(uint64(settlementNo), uint64(lpShares), uint64(settlementLP))
	if !ok || nU64 > uint64(maxInt64) {
		return 0, 0, ErrOverflow
	}
	return int64(yU64), int64(nU64), nil
}

// UpdateFeeAccumulator adds fee / totalLP (scaled by FeeAccScale, floored) to acc.
func UpdateFeeAccumulator(acc FeeAccumulator, fee, totalLP int64) (FeeAccumulator, error) {
	if fee < 0 {
		return FeeAccumulator{}, ErrInvalidAmount
	}
	if totalLP <= 0 {
		return FeeAccumulator{}, ErrInsufficientLiquidity
	}
	if fee == 0 {
		return acc, nil
	}
	delta, _ := u128Div64(u128Mul64(uint64(fee), FeeAccScale), uint64(totalLP))
	next, ok := u128Add(u128{hi: acc.AccHi, lo: acc.AccLo}, delta)
	if !ok {
		return FeeAccumulator{}, ErrOverflow
	}
	return FeeAccumulator{AccHi: next.hi, AccLo: next.lo}, nil
}

// ComputeLPFeeDebt calculates ceil(acc * lpShares / FeeAccScale) so newly
// minted LP shares cannot claim fees earned prior to their deposit.
func ComputeLPFeeDebt(acc FeeAccumulator, lpShares int64) (int64, error) {
	if lpShares < 0 {
		return 0, ErrInvalidAmount
	}
	if lpShares == 0 {
		return 0, nil
	}
	debt, ok := mulAccDiv(u128{hi: acc.AccHi, lo: acc.AccLo}, uint64(lpShares), FeeAccScale, true)
	if !ok {
		return 0, ErrOverflow
	}
	return debt, nil
}

// ComputePendingLPFee calculates floor(acc * lpShares / FeeAccScale) - feeDebt.
func ComputePendingLPFee(acc FeeAccumulator, lpShares, feeDebt int64) int64 {
	if lpShares <= 0 {
		return 0
	}
	entitled, ok := mulAccDiv(u128{hi: acc.AccHi, lo: acc.AccLo}, uint64(lpShares), FeeAccScale, false)
	if !ok || entitled <= feeDebt {
		return 0
	}
	return entitled - feeDebt
}

package fpmm

import "testing"

func invariantProduct(p Pool) u128 {
	return u128Mul64(uint64(p.ReserveYes), uint64(p.ReserveNo))
}

func TestU128Arithmetic(t *testing.T) {
	max64 := ^uint64(0)
	max128 := u128{hi: max64, lo: max64}

	// Add carry and overflow.
	s, ok := u128Add(u128{hi: 0, lo: max64}, u128{hi: 0, lo: 1})
	if !ok || s.hi != 1 || s.lo != 0 {
		t.Fatalf("expected carry to hi=1 lo=0, got %+v ok=%v", s, ok)
	}
	if _, ok := u128Add(max128, u128{hi: 0, lo: 1}); ok {
		t.Fatalf("expected 128-bit overflow")
	}

	// Sub borrow and underflow.
	d, ok := u128Sub(u128{hi: 1, lo: 0}, u128{hi: 0, lo: 1})
	if !ok || d.hi != 0 || d.lo != max64 {
		t.Fatalf("expected borrow diff lo=max64, got %+v ok=%v", d, ok)
	}
	if _, ok := u128Sub(u128{hi: 0, lo: 5}, u128{hi: 0, lo: 6}); ok {
		t.Fatalf("expected underflow")
	}

	// Mul64 and Div64 when hi >= d.
	p := u128Mul64(max64, max64)
	if p.hi != max64-1 || p.lo != 1 {
		t.Fatalf("unexpected max64^2: %+v", p)
	}
	q, rem := u128Div64(u128{hi: 100, lo: 17}, 3)
	// Verify q*3 + rem == {100, 17}.
	p1 := u128Mul64(q.lo, 3)
	p2 := u128{hi: q.hi * 3, lo: 0}
	recon, ok := u128Add(p1, p2)
	if !ok {
		t.Fatalf("reconstruct overflow")
	}
	recon, ok = u128Add(recon, u128From64(rem))
	if !ok || recon.hi != 100 || recon.lo != 17 || rem >= 3 {
		t.Fatalf("div reconstruction mismatch: recon=%+v rem=%d", recon, rem)
	}

	// mulDivFloor / mulDivCeil exactness.
	qf, ok := mulDivFloor(10, 10, 3)
	if !ok || qf != 33 {
		t.Fatalf("mulDivFloor(10,10,3) = %d, want 33", qf)
	}
	qc, ok := mulDivCeil(10, 10, 3)
	if !ok || qc != 34 {
		t.Fatalf("mulDivCeil(10,10,3) = %d, want 34", qc)
	}
	qcExact, ok := mulDivCeil(10, 9, 3)
	if !ok || qcExact != 30 {
		t.Fatalf("mulDivCeil(10,9,3) = %d, want 30", qcExact)
	}
}

func TestU128SqrtExact(t *testing.T) {
	cases := []u128{
		{0, 0},
		{0, 1},
		{0, 2},
		{0, 3},
		{0, 4},
		{0, 15},
		{0, 16},
		{0, 17},
		{0, ^uint64(0)},
		{1, 0},
		{1, 1},
		u128Mul64(1_000_000_000_000, 1_000_000_000_000),
		{^uint64(0) - 1, 1}, // max64^2
		{^uint64(0), ^uint64(0)},
	}
	// Add k^2-1 and k^2+1 around large values.
	sq := u128Mul64(1_234_567_890_123, 1_234_567_890_123)
	sqMinus, _ := u128Sub(sq, u128From64(1))
	sqPlus, _ := u128Add(sq, u128From64(1))
	cases = append(cases, sq, sqMinus, sqPlus)

	for i, n := range cases {
		fl := u128SqrtFloor(n)
		flSq := u128Mul64(fl, fl)
		if u128Cmp(flSq, n) > 0 {
			t.Fatalf("case %d: floor^2 > n (%+v > %+v)", i, flSq, n)
		}
		if fl < ^uint64(0) {
			nextSq := u128Mul64(fl+1, fl+1)
			if u128Cmp(nextSq, n) <= 0 {
				t.Fatalf("case %d: (floor+1)^2 <= n (%+v <= %+v)", i, nextSq, n)
			}
		}

		cl, ok := u128SqrtCeil(n)
		if n.hi == ^uint64(0) && n.lo == ^uint64(0) {
			// sqrt(2^128 - 1) is between 2^64 - 1 and 2^64, so ceil overflows uint64.
			if ok {
				t.Fatalf("expected ceil overflow for max uint128")
			}
			continue
		}
		if !ok {
			t.Fatalf("case %d: unexpected sqrtCeil failure", i)
		}
		clSq := u128Mul64(cl, cl)
		if u128Cmp(clSq, n) < 0 {
			t.Fatalf("case %d: ceil^2 < n", i)
		}
		if cl > 0 {
			prevSq := u128Mul64(cl-1, cl-1)
			if u128Cmp(prevSq, n) >= 0 {
				t.Fatalf("case %d: (ceil-1)^2 >= n", i)
			}
		}
	}
}

func TestNewPoolAndValidation(t *testing.T) {
	if _, err := NewPool(MinReserve-1, 100); err != ErrInvalidReserve {
		t.Fatalf("expected ErrInvalidReserve, got %v", err)
	}
	if _, err := NewPool(MaxReserve+1, 100); err != ErrInvalidReserve {
		t.Fatalf("expected ErrInvalidReserve above max, got %v", err)
	}
	if _, err := NewPool(10_000, -1); err != ErrInvalidFeeBps {
		t.Fatalf("expected ErrInvalidFeeBps <0, got %v", err)
	}
	if _, err := NewPool(10_000, MaxFeeBps+1); err != ErrInvalidFeeBps {
		t.Fatalf("expected ErrInvalidFeeBps >max, got %v", err)
	}

	p, err := NewPool(1_000_000, 100)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if p.YesProbBps() != 5_000 || p.NoProbBps() != 5_000 {
		t.Fatalf("expected 5000/5000 bps, got %d/%d", p.YesProbBps(), p.NoProbBps())
	}
	if _, err := p.QuoteBuy(Side(99), 1_000); err != ErrInvalidSide {
		t.Fatalf("expected ErrInvalidSide, got %v", err)
	}
	if _, err := p.QuoteBuy(SideYes, 0); err != ErrInvalidAmount {
		t.Fatalf("expected ErrInvalidAmount, got %v", err)
	}
	if _, err := p.QuoteBuy(SideYes, 1); err != ErrZeroOutput {
		t.Fatalf("expected ErrZeroOutput when 1 ugnot is consumed by ceil fee, got %v", err)
	}
	if _, _, err := p.ApplyBuy(SideYes, 1_000, 1_000_000); err != ErrSlippage {
		t.Fatalf("expected ErrSlippage on buy, got %v", err)
	}
	if _, _, err := p.ApplySell(SideYes, 1_000, 1_000_000); err != ErrSlippage {
		t.Fatalf("expected ErrSlippage on sell, got %v", err)
	}
	if _, _, err := p.ApplyAddLiquidity(10_000, 100_000); err != ErrSlippage {
		t.Fatalf("expected ErrSlippage on add liquidity, got %v", err)
	}
	if _, _, err := p.ApplyRemoveLiquidity(p.TotalLP); err != ErrInsufficientLiquidity {
		t.Fatalf("expected ErrInsufficientLiquidity removing all LP, got %v", err)
	}
	if _, _, err := p.ApplyBuy(SideYes, MaxReserve+1, 0); err != ErrInvalidAmount {
		t.Fatalf("expected ErrInvalidAmount above MaxReserve, got %v", err)
	}
	pLarge, err := NewPool(MaxReserve/2, 100)
	if err != nil {
		t.Fatalf("unexpected error creating large pool: %v", err)
	}
	if _, _, err := pLarge.ApplyBuy(SideYes, MaxReserve, 0); err != ErrOverflow {
		t.Fatalf("expected ErrOverflow, got %v", err)
	}
}

func TestBuySellBasicsAndSlippage(t *testing.T) {
	p, err := NewPool(1_000_000, 100) // 1% fee
	if err != nil {
		t.Fatal(err)
	}
	p2, bq, err := p.ApplyBuy(SideYes, 100_000, 1)
	if err != nil {
		t.Fatalf("buy failed: %v", err)
	}
	if bq.Fee != 1_000 || bq.NetCollateral != 99_000 {
		t.Fatalf("unexpected fee/net: %+v", bq)
	}
	if bq.SharesOut <= 99_000 {
		t.Fatalf("expected >99000 YES shares from balanced pool, got %d", bq.SharesOut)
	}
	if p2.YesProbBps() <= 5_000 {
		t.Fatalf("buying YES should raise YES prob > 5000, got %d", p2.YesProbBps())
	}

	p3, sq, err := p2.ApplySell(SideYes, bq.SharesOut, 1)
	if err != nil {
		t.Fatalf("sell failed: %v", err)
	}
	if sq.CollateralOut >= 100_000 {
		t.Fatalf("round-trip extracted value: %d >= 100000", sq.CollateralOut)
	}
	if p3.YesProbBps() >= p2.YesProbBps() {
		t.Fatalf("selling YES should reduce YES prob: before=%d after=%d", p2.YesProbBps(), p3.YesProbBps())
	}
}

func TestRoundTripArbitrageImpossible(t *testing.T) {
	fees := []int64{0, 50, 200, 500}
	poolSizes := []int64{1_000, 100_000, 10_000_000, 10_000_000_000_000}
	tradeSizes := []int64{10, 500, 25_000, 5_000_000, 5_000_000_000_000}

	for _, fee := range fees {
		for _, poolSz := range poolSizes {
			p, err := NewPool(poolSz, fee)
			if err != nil {
				t.Fatalf("NewPool(%d, %d): %v", poolSz, fee, err)
			}
			for _, tradeSz := range tradeSizes {
				if tradeSz > poolSz*10 {
					continue
				}
				k0 := invariantProduct(p)
				pBuy, bq, err := p.ApplyBuy(SideYes, tradeSz, 0)
				if err != nil {
					continue
				}
				k1 := invariantProduct(pBuy)
				if u128Cmp(k1, k0) < 0 {
					t.Fatalf("buy shrank k: pool=%d fee=%d trade=%d", poolSz, fee, tradeSz)
				}
				pSell, sq, err := pBuy.ApplySell(SideYes, bq.SharesOut, 0)
				if err != nil {
					continue
				}
				k2 := invariantProduct(pSell)
				if u128Cmp(k2, k1) < 0 {
					t.Fatalf("sell shrank k: pool=%d fee=%d trade=%d", poolSz, fee, tradeSz)
				}
				if sq.CollateralOut > tradeSz {
					t.Fatalf("round-trip profit! pool=%d fee=%d in=%d out=%d", poolSz, fee, tradeSz, sq.CollateralOut)
				}
			}
		}
	}
}

func TestDeterministicFuzzInvariants(t *testing.T) {
	p, err := NewPool(10_000_000, 100)
	if err != nil {
		t.Fatal(err)
	}
	collateral := int64(10_000_000)
	userYes := int64(0)
	userNo := int64(0)

	seed := uint64(0x9e3779b97f4a7c15)
	nextRand := func() uint64 {
		seed ^= seed << 13
		seed ^= seed >> 7
		seed ^= seed << 17
		return seed
	}

	assertState := func(step int, prevK u128, checkK bool) {
		if p.ReserveYes < 1 || p.ReserveNo < 1 {
			t.Fatalf("step %d: collapsed reserve (%d, %d)", step, p.ReserveYes, p.ReserveNo)
		}
		if p.ReserveYes+userYes != collateral {
			t.Fatalf("step %d: YES conservation broken: %d + %d != %d", step, p.ReserveYes, userYes, collateral)
		}
		if p.ReserveNo+userNo != collateral {
			t.Fatalf("step %d: NO conservation broken: %d + %d != %d", step, p.ReserveNo, userNo, collateral)
		}
		if p.YesProbBps()+p.NoProbBps() != BpsScale {
			t.Fatalf("step %d: probs do not sum to 10000", step)
		}
		if checkK {
			curK := invariantProduct(p)
			if u128Cmp(curK, prevK) < 0 {
				t.Fatalf("step %d: invariant k decreased", step)
			}
		}
	}

	for step := 0; step < 250; step++ {
		r := nextRand()
		op := r % 6
		kBefore := invariantProduct(p)

		switch op {
		case 0, 1: // Buy YES / NO
			side := SideYes
			if op == 1 {
				side = SideNo
			}
			amt := int64(1_000 + (nextRand() % 500_000))
			nextP, bq, err := p.ApplyBuy(side, amt, 0)
			if err != nil {
				continue
			}
			p = nextP
			collateral += bq.NetCollateral
			if side == SideYes {
				userYes += bq.SharesOut
			} else {
				userNo += bq.SharesOut
			}
			assertState(step, kBefore, true)

		case 2, 3: // Sell YES / NO
			side := SideYes
			held := userYes
			if op == 3 {
				side = SideNo
				held = userNo
			}
			if held < 100 {
				continue
			}
			amt := int64(uint64(1 + nextRand()%uint64(held)))
			nextP, sq, err := p.ApplySell(side, amt, 0)
			if err != nil {
				continue
			}
			p = nextP
			collateral -= sq.GrossCollateral
			if side == SideYes {
				userYes -= amt
			} else {
				userNo -= amt
			}
			assertState(step, kBefore, true)

		case 4: // Add liquidity
			amt := int64(10_000 + (nextRand() % 1_000_000))
			nextP, aq, err := p.ApplyAddLiquidity(amt, 0)
			if err != nil {
				continue
			}
			p = nextP
			collateral += amt
			if aq.RefundShares > 0 {
				if aq.RefundSide == SideYes {
					userYes += aq.RefundShares
				} else if aq.RefundSide == SideNo {
					userNo += aq.RefundShares
				}
			}
			assertState(step, kBefore, false)

		case 5: // Remove liquidity
			if p.TotalLP <= MinReserve*2 {
				continue
			}
			burn := int64(1_000 + (nextRand() % uint64(p.TotalLP/4)))
			nextP, rq, err := p.ApplyRemoveLiquidity(burn)
			if err != nil {
				continue
			}
			p = nextP
			collateral -= rq.CollateralOut
			userYes += rq.YesOut
			userNo += rq.NoOut
			assertState(step, kBefore, false)
		}
	}
}

func TestExtremeSkewAndMaxReserves(t *testing.T) {
	// Near MaxReserve pool and heavy skew.
	p, err := NewPool(100_000_000_000_000, 100) // 10^14 ugnot
	if err != nil {
		t.Fatal(err)
	}
	k0 := invariantProduct(p)
	pSkew, bq, err := p.ApplyBuy(SideYes, 50_000_000_000_000, 0)
	if err != nil {
		t.Fatalf("large buy failed: %v", err)
	}
	if u128Cmp(invariantProduct(pSkew), k0) < 0 {
		t.Fatalf("large buy violated k")
	}
	if pSkew.YesProbBps() <= 6000 {
		t.Fatalf("expected strong skew >60%%, got %d", pSkew.YesProbBps())
	}

	pBack, sq, err := pSkew.ApplySell(SideYes, bq.SharesOut, 0)
	if err != nil {
		t.Fatalf("large sell failed: %v", err)
	}
	if sq.CollateralOut >= 50_000_000_000_000 {
		t.Fatalf("large round trip profitable")
	}
	if u128Cmp(invariantProduct(pBack), invariantProduct(pSkew)) < 0 {
		t.Fatalf("large sell violated k")
	}
}

func TestLiquiditySkewAddRemoveConservation(t *testing.T) {
	p, err := NewPool(1_000_000, 0)
	if err != nil {
		t.Fatal(err)
	}
	// Skew pool by buying YES.
	p, bq, err := p.ApplyBuy(SideYes, 500_000, 0)
	if err != nil {
		t.Fatal(err)
	}
	collateral := int64(1_000_000 + 500_000)
	userYes := bq.SharesOut
	userNo := int64(0)

	// Add liquidity to skewed pool: ReserveNo > ReserveYes, so excess is YES shares.
	p, aq, err := p.ApplyAddLiquidity(500_000, 1)
	if err != nil {
		t.Fatalf("skew add failed: %v", err)
	}
	if aq.RefundSide != SideYes || aq.RefundShares <= 0 {
		t.Fatalf("expected YES refund on skewed add, got %+v", aq)
	}
	collateral += 500_000
	userYes += aq.RefundShares

	if p.ReserveYes+userYes != collateral || p.ReserveNo+userNo != collateral {
		t.Fatalf("conservation mismatch after skew add")
	}

	// Remove half LP shares.
	burn := p.TotalLP / 2
	p, rq, err := p.ApplyRemoveLiquidity(burn)
	if err != nil {
		t.Fatalf("skew remove failed: %v", err)
	}
	collateral -= rq.CollateralOut
	userYes += rq.YesOut
	userNo += rq.NoOut
	if p.ReserveYes+userYes != collateral || p.ReserveNo+userNo != collateral {
		t.Fatalf("conservation mismatch after skew remove")
	}
}

func TestFeeAccumulatorConservation(t *testing.T) {
	acc := FeeAccumulator{}
	lp1 := int64(1_000_000)
	lp2 := int64(0)
	lp3 := int64(0)
	totalLP := lp1

	var debt1, debt2, debt3 int64
	var pending1, pending2, pending3 int64
	var totalFees int64

	// Trade 1: small 1 ugnot fee, then 50,000 ugnot fee (only LP1 is in pool).
	for _, f := range []int64{1, 50_000} {
		var err error
		acc, err = UpdateFeeAccumulator(acc, f, totalLP)
		if err != nil {
			t.Fatal(err)
		}
		totalFees += f
	}

	// LP2 enters with 2,000,000 LP shares.
	lp2 = 2_000_000
	totalLP += lp2
	var err error
	debt2, err = ComputeLPFeeDebt(acc, lp2)
	if err != nil {
		t.Fatal(err)
	}
	// Immediately after entry, LP2 pending MUST be 0.
	if p := ComputePendingLPFee(acc, lp2, debt2); p != 0 {
		t.Fatalf("newcomer LP2 claimed prior fees: %d", p)
	}

	// Trade 2: large fee 123,456 ugnot + tiny fee 3 ugnot.
	for _, f := range []int64{123_456, 3} {
		acc, err = UpdateFeeAccumulator(acc, f, totalLP)
		if err != nil {
			t.Fatal(err)
		}
		totalFees += f
	}

	// LP3 enters with 500,000 shares.
	lp3 = 500_000
	totalLP += lp3
	debt3, err = ComputeLPFeeDebt(acc, lp3)
	if err != nil {
		t.Fatal(err)
	}
	if p := ComputePendingLPFee(acc, lp3, debt3); p != 0 {
		t.Fatalf("newcomer LP3 claimed prior fees: %d", p)
	}

	// Trade 3: 10^10 ugnot fee.
	bigFee := int64(10_000_000_000)
	acc, err = UpdateFeeAccumulator(acc, bigFee, totalLP)
	if err != nil {
		t.Fatal(err)
	}
	totalFees += bigFee

	pending1 += ComputePendingLPFee(acc, lp1, debt1)
	pending2 += ComputePendingLPFee(acc, lp2, debt2)
	pending3 += ComputePendingLPFee(acc, lp3, debt3)

	sumPaid := pending1 + pending2 + pending3
	if sumPaid > totalFees {
		t.Fatalf("fee over-distribution: paid=%d > collected=%d", sumPaid, totalFees)
	}
	if totalFees-sumPaid > 10 {
		t.Fatalf("unexpected fee precision loss: collected=%d paid=%d", totalFees, sumPaid)
	}
}

func TestQuoteSettleLPConservation(t *testing.T) {
	settYes := int64(1_234_567)
	settNo := int64(987_655)
	settLP := int64(100_001)
	slices := []int64{33_333, 33_333, 33_335}

	var sumYes, sumNo int64
	for _, s := range slices {
		y, n, err := QuoteSettleLP(settYes, settNo, settLP, s)
		if err != nil {
			t.Fatal(err)
		}
		sumYes += y
		sumNo += n
	}
	if sumYes > settYes || sumNo > settNo {
		t.Fatalf("settlement exceeded reserves: yes=%d/%d no=%d/%d", sumYes, settYes, sumNo, settNo)
	}
	if settYes-sumYes > 3 || settNo-sumNo > 3 {
		t.Fatalf("unexpected settlement dust: yes=%d/%d no=%d/%d", sumYes, settYes, sumNo, settNo)
	}
}

package fpmm

import "math/bits"

// u128 represents an unsigned 128-bit integer for overflow-free
// fixed-point intermediate arithmetic.
type u128 struct {
	hi uint64
	lo uint64
}

func u128From64(x uint64) u128 {
	return u128{lo: x}
}

func u128Add(a, b u128) (u128, bool) {
	lo, carry := bits.Add64(a.lo, b.lo, 0)
	hi, carryOut := bits.Add64(a.hi, b.hi, carry)
	if carryOut != 0 {
		return u128{}, false
	}
	return u128{hi: hi, lo: lo}, true
}

func u128Sub(a, b u128) (u128, bool) {
	lo, borrow := bits.Sub64(a.lo, b.lo, 0)
	hi, borrowOut := bits.Sub64(a.hi, b.hi, borrow)
	if borrowOut != 0 {
		return u128{}, false
	}
	return u128{hi: hi, lo: lo}, true
}

func u128Cmp(a, b u128) int {
	if a.hi < b.hi {
		return -1
	}
	if a.hi > b.hi {
		return 1
	}
	if a.lo < b.lo {
		return -1
	}
	if a.lo > b.lo {
		return 1
	}
	return 0
}

func u128Mul64(a, b uint64) u128 {
	hi, lo := bits.Mul64(a, b)
	return u128{hi: hi, lo: lo}
}

func u128Div64(a u128, d uint64) (u128, uint64) {
	if d == 0 {
		panic("fpmm: division by zero")
	}
	qHi := a.hi / d
	rHi := a.hi % d
	qLo, rem := bits.Div64(rHi, a.lo, d)
	return u128{hi: qHi, lo: qLo}, rem
}

func mulDivFloor(a, b, d uint64) (uint64, bool) {
	if d == 0 {
		return 0, false
	}
	prod := u128Mul64(a, b)
	q, _ := u128Div64(prod, d)
	if q.hi != 0 {
		return 0, false
	}
	return q.lo, true
}

func mulDivCeil(a, b, d uint64) (uint64, bool) {
	if d == 0 {
		return 0, false
	}
	prod := u128Mul64(a, b)
	q, rem := u128Div64(prod, d)
	if q.hi != 0 {
		return 0, false
	}
	if rem > 0 {
		if q.lo == ^uint64(0) {
			return 0, false
		}
		q.lo++
	}
	return q.lo, true
}

func u128BitLen(n u128) int {
	if n.hi > 0 {
		return 64 + bits.Len64(n.hi)
	}
	return bits.Len64(n.lo)
}

func u128SqrtFloor(n u128) uint64 {
	if n.hi == 0 && n.lo <= 1 {
		return n.lo
	}
	bitLen := u128BitLen(n)
	shiftLo := uint((bitLen - 1) / 2)
	shiftHi := uint((bitLen + 1) / 2)

	lo := uint64(1) << shiftLo
	var hi uint64
	if shiftHi >= 64 {
		hi = ^uint64(0)
	} else {
		hi = (uint64(1) << shiftHi) - 1
	}

	for lo < hi {
		mid := lo + (hi-lo+1)/2
		sq := u128Mul64(mid, mid)
		if u128Cmp(sq, n) <= 0 {
			lo = mid
		} else {
			hi = mid - 1
		}
	}
	return lo
}

func u128SqrtCeil(n u128) (uint64, bool) {
	r := u128SqrtFloor(n)
	sq := u128Mul64(r, r)
	if u128Cmp(sq, n) < 0 {
		if r == ^uint64(0) {
			return 0, false
		}
		r++
	}
	return r, true
}

// mulAccDiv computes floor(acc * shares / scale) or ceil(acc * shares / scale)
// using exact 192-bit intermediate multiplication and 3-limb division.
func mulAccDiv(acc u128, shares, scale uint64, ceil bool) (int64, bool) {
	if scale == 0 {
		return 0, false
	}
	p0Hi, w0 := bits.Mul64(acc.lo, shares)
	p1Hi, p1Lo := bits.Mul64(acc.hi, shares)

	w1, c1 := bits.Add64(p1Lo, p0Hi, 0)
	w2, c2 := bits.Add64(p1Hi, 0, c1)
	if c2 != 0 {
		return 0, false
	}

	q2 := w2 / scale
	r2 := w2 % scale
	if q2 != 0 {
		return 0, false
	}
	q1, r1 := bits.Div64(r2, w1, scale)
	if q1 != 0 {
		return 0, false
	}
	q0, rem := bits.Div64(r1, w0, scale)
	if ceil && rem > 0 {
		if q0 == ^uint64(0) {
			return 0, false
		}
		q0++
	}
	if q0 > uint64(maxInt64) {
		return 0, false
	}
	return int64(q0), true
}

