	sb.WriteString(`{"address":"` + bs_core.EscapeJSON(addr.String()) + `","sponsoredQuests":[`)
	sqStart, sqEnd := pageBounds(len(sponsoredQ), page, limit)
	for i := sqStart; i < sqEnd; i++ {
