			sb.WriteString(",")
		}
		sb.WriteString(contestSummaryJSON(sponsoredC[i], now))
	}
	sb.WriteString(`],"submittedContests":[`)
	subStart, subEnd := pageBounds(len(submittedC), page, limit)
	for i := subStart; i < subEnd; i++ {
