func pageBounds(total, page, limit int) (int, int) {
	start := (page - 1) * limit
	if start > total {
		start = total
	}
	end := start + limit
	if end > total {
		end = total
	}
	return start, end
}

func parseID(s string) (uint64, bool) {
	id, err := strconv.ParseUint(s, 10, 64)
	return id, err == nil
}

func splitPathQuery(p string) (string, string) {
	idx := strings.Index(p, "?")
	if idx == -1 {
		return p, ""
	}
	return p[:idx], p[idx+1:]
}

func parseQueryParam(query, key string) string {
	if query == "" {
		return ""
	}
	for _, kv := range strings.Split(query, "&") {
		eq := strings.Index(kv, "=")
		if eq > 0 && kv[:eq] == key {
			return kv[eq+1:]
		}
	}
	return ""
}

func parsePageLimit(query string) (int, int) {
	page := 1
	limit := bs_core.DefaultPageLimit
	if v := parseQueryParam(query, "page"); v != "" {
		if n, err := strconv.Atoi(v); err == nil {
			page = n
		}
	}
	if v := parseQueryParam(query, "limit"); v != "" {
		if n, err := strconv.Atoi(v); err == nil {
			limit = n
		}
	}
	return bs_core.ClampPageLimit(page, limit)
}

// Package bountysiege is the core escrow, mission lifecycle (Quest, Contest,
// Raid), Q&A, and Treasury realm for BountySiege on Gno.land.
package bountysiege

import (
	"chain"
	"chain/banker"
	"chain/runtime/unsafe"
	"strconv"
	"time"

	"gno.land/p/g1fn0l3ms5puafp37r7v67mx2msjl0ztnyq3a9yv/bs_core"
)

var (
	// Strictly separated 3-role governance (owner != arbiter != treasury).
	owner              address
	realmAddr          address
	arbiter            address
	pendingArbiter     address
	arbiterEffectiveAt int64
	treasury           address
	pendingTreasury    address
	rolesInitialized   bool

	// Opsi A circuit breaker: owner may ONLY toggle cross-realm reputation
	// recording in an emergency. Owner has ZERO access to escrow or treasury.
	repRecordingEnabled bool = true

	// Explicit accounting ledgers for global fund invariant:
	// banker.NewReadonlyBanker().GetCoin(realmAddr, "ugnot") >= totalActiveEscrow + treasuryBalance
	totalActiveEscrow int64
	treasuryBalance   int64
	totalPaidOut      int64
)

func init(cur realm) {
	owner = cur.Previous().Address()
	if owner == "" {
		// Fallback only hit when imported lazily by gno filetest (Context == nil);
		// on-chain AddPackage always sets OriginCaller = creator.Bech32().
		owner = address("g1fn0l3ms5puafp37r7v67mx2msjl0ztnyq3a9yv")
	}
	realmAddr = cur.Address()
	repRecordingEnabled = true
}

// InitRoles sets the distinct arbiter and treasury addresses once after deploy.
func InitRoles(cur realm, arbiterAddr, treasuryAddr address) {
	requireNonPayableEOA(0, cur)
	if cur.Previous().Address() != owner {
		panic("unauthorized: only owner can initialize roles")
	}
	if rolesInitialized {
		panic("protocol roles already initialized")
	}
	if arbiterAddr == "" || treasuryAddr == "" {
		panic("arbiter and treasury addresses are required")
	}
	if owner == arbiterAddr || owner == treasuryAddr || arbiterAddr == treasuryAddr {
		panic("owner, arbiter, and treasury must be 3 distinct addresses")
	}
	arbiter = arbiterAddr
	treasury = treasuryAddr
	rolesInitialized = true
}

// ProposeArbiter starts a 48-hour timelock to rotate the arbiter address.
// Existing disputes keep their lockedArbiter permanently.
func ProposeArbiter(cur realm, next address) {
	requireNonPayableEOA(0, cur)
	requireRolesInitialized()
	if cur.Previous().Address() != owner {
		panic("unauthorized: only owner can propose arbiter rotation")
	}
	if next == "" {
		panic("new arbiter address is required")
	}
	if next == owner || next == treasury || next == pendingTreasury || next == arbiter {
		panic("new arbiter must be distinct from owner, treasury, and current arbiter")
	}
	pendingArbiter = next
	arbiterEffectiveAt = time.Now().Unix() + bs_core.ArbiterTimelockSec
}

// ExecuteArbiterRotation activates pendingArbiter after the 48-hour timelock.
func ExecuteArbiterRotation(cur realm) {
	requireNonPayableEOA(0, cur)
	requireRolesInitialized()
	if cur.Previous().Address() != owner {
		panic("unauthorized: only owner can execute arbiter rotation")
	}
	if pendingArbiter == "" {
		panic("no pending arbiter rotation")
	}
	if time.Now().Unix() < arbiterEffectiveAt {
		panic("arbiter rotation timelock (48h) has not elapsed")
	}
	arbiter = pendingArbiter
	pendingArbiter = ""
	arbiterEffectiveAt = 0
}

// ProposeTreasury starts a 2-step treasury address rotation (callable ONLY by treasury).
func ProposeTreasury(cur realm, next address) {
	requireNonPayableEOA(0, cur)
	requireRolesInitialized()
	if cur.Previous().Address() != treasury {
		panic("unauthorized: only current treasury can propose treasury rotation")
	}
	if next == "" {
		panic("new treasury address is required")
	}
	if next == owner || next == arbiter || next == pendingArbiter || next == treasury {
		panic("new treasury must be distinct from owner, arbiter, and current treasury")
	}
	pendingTreasury = next
}

// AcceptTreasury completes the 2-step treasury rotation (callable ONLY by pendingTreasury).
func AcceptTreasury(cur realm) {
	requireNonPayableEOA(0, cur)
	requireRolesInitialized()
	if pendingTreasury == "" || cur.Previous().Address() != pendingTreasury {
		panic("unauthorized: only pending treasury can accept rotation")
	}
	treasury = pendingTreasury
	pendingTreasury = ""
}

// WithdrawTreasury transfers up to treasuryBalance exclusively to the treasury address.
// Never touches totalActiveEscrow.
func WithdrawTreasury(cur realm, amount int64) {
	requireNonPayableEOA(0, cur)
	requireRolesInitialized()
	if cur.Previous().Address() != treasury {
		panic("unauthorized: only treasury can withdraw")
	}
	if amount <= 0 {
		panic("withdraw amount must be > 0")
	}
	if amount > treasuryBalance {
		panic("withdraw amount exceeds treasuryBalance")
	}
	// Checks-Effects-Interactions: debit ledger before sending coins.
	treasuryBalance -= amount
	sendUgnot(treasury, amount, cur)
}

// SetRepRecordingEnabled is the Opsi A emergency circuit breaker.
// Owner can ONLY toggle cross-realm siege_rep recording and has zero fund access.
func SetRepRecordingEnabled(cur realm, enabled bool) {
	requireNonPayableEOA(0, cur)
	if cur.Previous().Address() != owner {
		panic("unauthorized: only owner can toggle reputation circuit breaker")
	}
	repRecordingEnabled = enabled
}

//----------------------------------------
// Shared Coin, Role & Accounting Guards
// (NOTE: non-crossing helpers NEVER take `realm` as parameter #1!)
//----------------------------------------

func requireRolesInitialized() {
	if !rolesInitialized {
		panic("protocol roles not initialized")
	}
}

// requireNonPayableEOA enforces direct EOA call and empty OriginSend.
func requireNonPayableEOA(_ int, rlm realm) {
	if !rlm.Previous().IsUserCall() {
		panic("must be called directly by an EOA")
	}
	if len(unsafe.OriginSend()) != 0 {
		panic("non-payable function: do not send coins")
	}
}

// requireExactUgnot enforces direct EOA call and a single ugnot coin of exact amount.
func requireExactUgnot(expected int64, rlm realm) {
	if !rlm.Previous().IsUserCall() {
		panic("must be called directly by an EOA")
	}
	if expected <= 0 {
		panic("expected payment must be > 0")
	}
	sent := unsafe.OriginSend()
	if len(sent) != 1 {
		panic("must send exactly one ugnot coin")
	}
	if sent[0].Denom != bs_core.DenomUgnot {
		panic("invalid coin denom: only ugnot is accepted")
	}
	if sent[0].Amount != expected {
		panic("exact amount mismatch: expected " + strconv.FormatInt(expected, 10) +
			"ugnot, got " + strconv.FormatInt(sent[0].Amount, 10) + "ugnot")
	}
}

func isExcludedWorkerRole(addr address) bool {
	if addr == "" {
		return true
	}
	return addr == arbiter || addr == pendingArbiter || addr == treasury || addr == pendingTreasury
}

func sendUgnot(to address, amount int64, rlm realm) {
	if amount <= 0 {
		return
	}
	b := banker.NewBanker(banker.BankerTypeRealmSend, rlm)
	b.SendCoins(rlm.Address(), to, chain.NewCoins(chain.NewCoin(bs_core.DenomUgnot, amount)))
}

//----------------------------------------
// Public Read-Only Accounting & Role Getters
//----------------------------------------

func GetOwner() address           { return owner }
func GetArbiter() address         { return arbiter }
func GetPendingArbiter() address  { return pendingArbiter }
func GetTreasury() address        { return treasury }
func GetTreasuryBalance() int64   { return treasuryBalance }
func GetActiveEscrow() int64      { return totalActiveEscrow }
func GetTotalPaidOut() int64      { return totalPaidOut }
func IsRepRecordingEnabled() bool { return repRecordingEnabled }

// RealmUgnotBalance returns the live ugnot balance of this realm using GetCoin
// (never GetCoins, avoiding denom-spam DoS).
func RealmUgnotBalance() int64 {
	return banker.NewReadonlyBanker().GetCoin(realmAddr, bs_core.DenomUgnot)
}

package slotswitch

import (
	"chain/runtime"
	"chain/runtime/unsafe"
	"strconv"
	"strings"
	"time"
)

const (
	appointmentSeconds = 15 * 60
	maxClinicSeconds   = 24 * 60 * 60
	maxMembers         = 12
	maxIssuedSlots     = 32
)

type slot struct {
	issuer   address
	holder   address
	start    int64
	revision int
	active   bool
}

type plan struct {
	expiry      int64
	size        int
	slots       [3]int
	old         [3]slot
	approved    [3]bool
	settled     bool
	height      int64
	confirmedAt int64
}

type clinic struct {
	id                   int
	issuers              [2]address
	accepted             bool
	draftRevision        int
	startsAt             int64
	endsAt               int64
	cutoff               int64
	members              map[address]string
	enrolled             []address
	slots                map[int]slot
	activeSlots          map[int]bool
	activeByHolder       map[address]int
	bookingGeneration    map[address]int
	pendingMembers       map[int]pendingMember
	nextMemberProposalID int
	plans                map[int]*plan
	openByProposer       map[address]int
	nextPlanID           int
}

var clinics = make(map[int]*clinic)

func signer(cur realm) address {
	caller := cur.Previous()
	if !caller.IsUserCall() || len(unsafe.OriginSend()) != 0 {
		panic("use a direct wallet call with no attached funds")
	}
	return caller.Address()
}

// Create opens a draft clinic for the two desks to review.
func Create(cur realm, other address, startsAt, endsAt, cutoff int64) int {
	runtime.AssertOriginCall()
	issuer := signer(cur)
	if issuer == "" || other == "" || issuer == other {
		panic("distinct issuers required")
	}
	if now := time.Now().Unix(); cutoff <= now || cutoff > startsAt ||
		endsAt <= startsAt || endsAt-startsAt < appointmentSeconds || endsAt-startsAt > maxClinicSeconds {
		panic("invalid clinic window or cutoff")
	}
	id := len(clinics) + 1
	clinics[id] = &clinic{
		id:                   id,
		issuers:              [2]address{issuer, other},
		draftRevision:        1,
		startsAt:             startsAt,
		endsAt:               endsAt,
		cutoff:               cutoff,
		members:              make(map[address]string),
		slots:                make(map[int]slot),
		activeSlots:          make(map[int]bool),
		activeByHolder:       make(map[address]int),
		bookingGeneration:    make(map[address]int),
		pendingMembers:       make(map[int]pendingMember),
		nextMemberProposalID: 1,
		plans:                make(map[int]*plan),
		openByProposer:       make(map[address]int),
		nextPlanID:           1,
	}
	return id
}

func Enroll(cur realm, clinicID int, member address, alias string) {
	runtime.AssertOriginCall()
	caller := signer(cur)
	c := requireClinic(clinicID)
	if caller != c.issuers[0] || c.accepted || time.Now().Unix() >= c.cutoff {
		panic("only the first issuer may enroll in an open draft")
	}
	insertMember(c, member, validatedMemberAlias(c, member, alias))
}

func validatedMemberAlias(c *clinic, member address, alias string) string {
	alias = strings.TrimSpace(alias)
	if member == "" || c.members[member] != "" || len(c.enrolled) >= maxMembers ||
		len(alias) == 0 || len(alias) > 24 {
		panic("invalid team enrollment")
	}
	for _, ch := range alias {
		if !((ch >= 'A' && ch <= 'Z') || (ch >= 'a' && ch <= 'z') || (ch >= '0' && ch <= '9') || ch == ' ' || ch == '-') {
			panic("use a short public alias")
		}
	}
	for _, enrolled := range c.enrolled {
		if strings.EqualFold(c.members[enrolled], alias) {
			panic("public alias already in use")
		}
	}
	return alias
}

func insertMember(c *clinic, member address, alias string) {
	c.members[member] = alias
	c.enrolled = append(c.enrolled, member)
	c.draftRevision++
}

func Accept(cur realm, clinicID, expectedRevision int) {
	runtime.AssertOriginCall()
	caller := signer(cur)
	c := requireClinic(clinicID)
	if caller != c.issuers[1] {
		panic("invited issuer required")
	}
	if c.draftRevision != expectedRevision {
		panic("clinic draft changed since preview")
	}
	if time.Now().Unix() >= c.cutoff || len(c.enrolled) < 2 {
		panic("clinic draft expired or has fewer than two teams")
	}
	c.accepted = true
}

func Issue(cur realm, clinicID int, start int64, member address) int {
	runtime.AssertOriginCall()
	issuer := signer(cur)
	c := requireAcceptedClinic(clinicID)
	if c.members[member] == "" {
		panic("enrolled team required")
	}
	return issueSlot(c, issuer, start, member)
}

// OfferSlot reserves an unassigned appointment on the caller's desk calendar.
func OfferSlot(cur realm, clinicID int, start int64) int {
	runtime.AssertOriginCall()
	return issueSlot(requireAcceptedClinic(clinicID), signer(cur), start, "")
}

func issueSlot(c *clinic, issuer address, start int64, holder address) int {
	if issuer != c.issuers[0] && issuer != c.issuers[1] {
		panic("issuer required")
	}
	if start <= time.Now().Unix() || start < c.startsAt || start > c.endsAt-appointmentSeconds ||
		len(c.activeSlots) >= maxIssuedSlots {
		panic("invalid slot")
	}
	if c.activeByHolder[holder] != 0 || scheduleConflict(holderSchedule, holder, start, bookingRef{}) ||
		scheduleConflict(issuerSchedule, issuer, start, bookingRef{}) {
		panic("active reservation conflicts with slot or holder")
	}
	id := len(c.slots) + 1
	c.slots[id] = slot{issuer: issuer, holder: holder, start: start, revision: 1, active: true}
	c.activeSlots[id] = true
	addSchedule(issuerSchedule, issuer, bookingRef{c.id, id, start})
	addHolderBooking(c, id, c.slots[id])
	return id
}

// AssignSlot gives an explicitly vacant appointment to an enrolled member.
func AssignSlot(cur realm, clinicID, slotID, expectedRevision int, member address) {
	runtime.AssertOriginCall()
	caller := signer(cur)
	c := requireAcceptedClinic(clinicID)
	s := c.slots[slotID]
	if !s.active || s.issuer != caller || s.holder != "" {
		panic("active vacancy issuer required")
	}
	if s.revision != expectedRevision {
		panic("appointment changed since preview")
	}
	if time.Now().Unix() >= s.start {
		panic("appointment already started")
	}
	if c.members[member] == "" {
		panic("enrolled team required")
	}
	if c.activeByHolder[member] != 0 || scheduleConflict(holderSchedule, member, s.start, bookingRef{}) {
		panic("active reservation conflicts with slot or holder")
	}
	s.holder = member
	s.revision++
	c.slots[slotID] = s
	addHolderBooking(c, slotID, s)
}

func CancelSlot(cur realm, clinicID, slotID, expectedRevision int) {
	runtime.AssertOriginCall()
	caller := signer(cur)
	c := requireAcceptedClinic(clinicID)
	s := c.slots[slotID]
	if !s.active || s.issuer != caller {
		panic("active slot issuer required")
	}
	if s.revision != expectedRevision {
		panic("appointment changed since preview")
	}
	if time.Now().Unix() >= s.start {
		panic("appointment already started")
	}
	removeHolderBooking(c, s)
	removeSchedule(issuerSchedule, s.issuer, s.start)
	delete(c.activeSlots, slotID)
	s.active = false
	s.revision++
	c.slots[slotID] = s
}

func Propose(cur realm, clinicID, first, second, third, firstRevision, secondRevision, thirdRevision int, expiry int64) int {
	runtime.AssertOriginCall()
	caller := signer(cur)
	c := requireAcceptedClinic(clinicID)
	now := time.Now().Unix()
	if now >= expiry || expiry > c.cutoff || expiry > now+maxClinicSeconds {
		panic("invalid expiry")
	}
	p := &plan{expiry: expiry, size: 2, slots: [3]int{first, second, third}}
	if third != 0 {
		p.size = 3
	}
	if first <= 0 || second <= 0 || first == second || first == third || second == third {
		panic("distinct slots required")
	}
	expected := [3]int{firstRevision, secondRevision, thirdRevision}
	for i := 0; i < p.size; i++ {
		s := c.slots[p.slots[i]]
		if !s.active || s.holder == "" || expiry >= s.start {
			panic("active future slots required")
		}
		if s.revision != expected[i] {
			panic("slot changed since preview")
		}
		p.old[i] = s
	}
	if p.old[0].holder != caller {
		panic("first holder must propose")
	}
	if planTimeConflict(c, p) {
		panic("holder has overlapping appointment")
	}
	previousID := c.openByProposer[caller]
	if previousID != 0 {
		state := planState(c, c.plans[previousID], now)
		if state == "open" || state == "blocked" {
			panic("withdraw or complete your open proposal")
		}
		delete(c.plans, previousID)
	}
	id := c.nextPlanID
	c.nextPlanID++
	c.plans[id] = p
	c.openByProposer[caller] = id
	return id
}

func Approve(cur realm, clinicID, planID int, approved bool) {
	runtime.AssertOriginCall()
	caller := signer(cur)
	c := requireAcceptedClinic(clinicID)
	p := c.plans[planID]
	state := planState(c, p, time.Now().Unix())
	if state != "open" && (approved || (state != "blocked" && state != "stale")) {
		panic("proposal is " + state)
	}
	for i := 0; i < p.size; i++ {
		if p.old[i].holder == caller {
			p.approved[i] = approved
			return
		}
	}
	panic("holder required")
}

func Withdraw(cur realm, clinicID, planID int) {
	runtime.AssertOriginCall()
	caller := signer(cur)
	c := requireAcceptedClinic(clinicID)
	if c.openByProposer[caller] != planID || planID == 0 {
		panic("open proposal owner required")
	}
	delete(c.openByProposer, caller)
	delete(c.plans, planID)
}

func Settle(cur realm, clinicID, planID int) {
	runtime.AssertOriginCall()
	caller := signer(cur)
	c := requireAcceptedClinic(clinicID)
	p := readyPlan(c, planID)
	isHolder := false
	for i := 0; i < p.size; i++ {
		if p.old[i].holder == caller {
			isHolder = true
		}
		if !p.approved[i] {
			panic("all holders must approve")
		}
	}
	if !isHolder {
		panic("holder required")
	}
	for i := 0; i < p.size; i++ {
		removeHolderBooking(c, p.old[i])
	}
	for i := 0; i < p.size; i++ {
		slotID := p.slots[i]
		updated := rotatedSlot(p, i)
		c.slots[slotID] = updated
		addHolderBooking(c, slotID, updated)
	}
	p.settled = true
	p.height = runtime.ChainHeight()
	p.confirmedAt = time.Now().Unix()
	delete(c.openByProposer, p.old[0].holder)
}

func rotatedSlot(p *plan, destination int) slot {
	s := p.old[destination]
	source := (destination + p.size - 1) % p.size
	s.holder = p.old[source].holder
	s.revision++
	return s
}

func requireClinic(id int) *clinic {
	c := clinics[id]
	if c == nil {
		panic("unknown clinic")
	}
	return c
}

func requireAcceptedClinic(id int) *clinic {
	c := requireClinic(id)
	if !c.accepted {
		panic("second issuer has not accepted")
	}
	return c
}

func planState(c *clinic, p *plan, now int64) string {
	if p == nil {
		return "closed"
	}
	if p.settled {
		return "settled"
	}
	if now >= p.expiry {
		return "expired"
	}
	for i := 0; i < p.size; i++ {
		if c.slots[p.slots[i]] != p.old[i] {
			return "stale"
		}
	}
	if planTimeConflict(c, p) {
		return "blocked"
	}
	return "open"
}

func readyPlan(c *clinic, id int) *plan {
	p := c.plans[id]
	state := planState(c, p, time.Now().Unix())
	if state != "open" {
		panic("proposal is " + state)
	}
	return p
}

func Reservation(clinicID, slotID int) string {
	s := requireClinic(clinicID).slots[slotID]
	return s.issuer.String() + "," + s.holder.String() + "," + strconv.Itoa(s.revision) + "," + strconv.FormatBool(s.active)
}

package slotswitch

import (
	"chain/runtime"
	"sort"
	"strings"
	"time"
)

type pendingMember struct {
	member   address
	alias    string
	proposer address
}

type PendingMemberView struct {
	ID       int
	Member   address
	Alias    string
	Proposer address
}

// ProposeMember records one desk's approval of the exact wallet and alias.
func ProposeMember(cur realm, clinicID int, member address, alias string) int {
	runtime.AssertOriginCall()
	caller := signer(cur)
	c := requireAcceptedClinic(clinicID)
	if (caller != c.issuers[0] && caller != c.issuers[1]) || time.Now().Unix() >= c.endsAt {
		panic("issuer of an active clinic required")
	}
	if len(c.enrolled)+len(c.pendingMembers) >= maxMembers {
		panic("clinic enrollment capacity reached")
	}
	alias = validatedMemberAlias(c, member, alias)
	for _, pending := range c.pendingMembers {
		if pending.member == member || strings.EqualFold(pending.alias, alias) {
			panic("wallet or public alias already proposed")
		}
	}
	id := c.nextMemberProposalID
	c.nextMemberProposalID++
	c.pendingMembers[id] = pendingMember{member: member, alias: alias, proposer: caller}
	return id
}

// ApproveMember enrolls the proposed wallet only when the other desk confirms it.
func ApproveMember(cur realm, clinicID, proposalID int) {
	runtime.AssertOriginCall()
	caller := signer(cur)
	c := requireAcceptedClinic(clinicID)
	pending, exists := c.pendingMembers[proposalID]
	if !exists {
		panic("unknown member proposal")
	}
	if (caller != c.issuers[0] && caller != c.issuers[1]) || caller == pending.proposer {
		panic("other issuer must approve member")
	}
	if time.Now().Unix() >= c.endsAt {
		panic("clinic has ended")
	}
	alias := validatedMemberAlias(c, pending.member, pending.alias)
	insertMember(c, pending.member, alias)
	delete(c.pendingMembers, proposalID)
}

// WithdrawMember clears a pending proposal and releases its enrollment capacity.
func WithdrawMember(cur realm, clinicID, proposalID int) {
	runtime.AssertOriginCall()
	caller := signer(cur)
	c := requireAcceptedClinic(clinicID)
	pending, exists := c.pendingMembers[proposalID]
	if !exists || caller != pending.proposer {
		panic("member proposal owner required")
	}
	delete(c.pendingMembers, proposalID)
}

func PendingMembers(clinicID int) []PendingMemberView {
	c := requireClinic(clinicID)
	ids := make([]int, 0, len(c.pendingMembers))
	for id := range c.pendingMembers {
		ids = append(ids, id)
	}
	sort.Ints(ids)
	out := make([]PendingMemberView, 0, len(ids))
	for _, id := range ids {
		pending := c.pendingMembers[id]
		out = append(out, PendingMemberView{ID: id, Member: pending.member, Alias: pending.alias, Proposer: pending.proposer})
	}
	return out
}

package slotswitch

type bookingRef struct {
	clinicID int
	slotID   int
	start    int64
}

type schedule map[address]map[int64]bookingRef

var holderSchedule = make(schedule)
var issuerSchedule = make(schedule)

// All appointments have equal duration. A non-overlapping calendar can
// contain at most one appointment beginning in each duration-sized bucket.
func scheduleConflict(index schedule, account address, start int64, released bookingRef) bool {
	calendar := index[account]
	bucket := start / appointmentSeconds
	for candidate := bucket - 1; candidate <= bucket+1; candidate++ {
		existing := calendar[candidate]
		if existing.slotID != 0 && existing != released &&
			start > existing.start-appointmentSeconds && existing.start > start-appointmentSeconds {
			return true
		}
	}
	return false
}

func addSchedule(index schedule, account address, ref bookingRef) {
	calendar := index[account]
	if calendar == nil {
		calendar = make(map[int64]bookingRef)
		index[account] = calendar
	}
	calendar[ref.start/appointmentSeconds] = ref
}

func removeSchedule(index schedule, account address, start int64) {
	calendar := index[account]
	delete(calendar, start/appointmentSeconds)
	if len(calendar) == 0 {
		delete(index, account)
	}
}

func addHolderBooking(c *clinic, slotID int, s slot) {
	if s.holder == "" {
		return
	}
	addSchedule(holderSchedule, s.holder, bookingRef{c.id, slotID, s.start})
	c.activeByHolder[s.holder] = slotID
	c.bookingGeneration[s.holder]++
}

func removeHolderBooking(c *clinic, s slot) {
	if s.holder == "" {
		return
	}
	removeSchedule(holderSchedule, s.holder, s.start)
	delete(c.activeByHolder, s.holder)
	c.bookingGeneration[s.holder]++
}

func planTimeConflict(c *clinic, p *plan) bool {
	for i := 0; i < p.size; i++ {
		destination := (i + 1) % p.size
		old := p.old[i]
		released := bookingRef{c.id, p.slots[i], old.start}
		if scheduleConflict(holderSchedule, old.holder, p.old[destination].start, released) {
			return true
		}
	}
	return false
}

package slotswitch

import (
	"chain/runtime"
	"time"
)

type transfer struct {
	clinics               [2]int
	slots                 [2]int
	before                [2]slot
	destinationGeneration [2]int
	approved              [4]bool
	expiry                int64
	terminal              string
	height                int64
	time                  int64
}

var transfers = make(map[int]*transfer)
var openTransfers = make(map[address][]int)
var nextTransferID = 1

const maxOpenTransfers = 4

// ProposeTransfer swaps two appointments across clinics. If the destination
// is vacant, the source holder moves there and the source becomes vacant.
func ProposeTransfer(cur realm, fromClinic, fromSlot, fromRevision, toClinic, toSlot, toRevision int, expiry int64) int {
	runtime.AssertOriginCall()
	caller := signer(cur)
	if fromClinic == toClinic {
		panic("distinct clinics required")
	}
	from := requireAcceptedClinic(fromClinic)
	to := requireAcceptedClinic(toClinic)
	first := from.slots[fromSlot]
	second := to.slots[toSlot]
	if !first.active || !second.active {
		panic("active appointments required")
	}
	if first.revision != fromRevision || second.revision != toRevision {
		panic("appointment changed since preview")
	}
	if first.holder == "" || first.holder != caller {
		panic("source holder must propose")
	}
	if first.issuer == second.issuer || first.holder == second.holder {
		panic("distinct issuing desks and holders required")
	}
	now := time.Now().Unix()
	if expiry <= now || expiry > now+maxClinicSeconds || expiry > from.cutoff || expiry > to.cutoff ||
		expiry >= first.start || expiry >= second.start {
		panic("invalid transfer expiry")
	}
	p := &transfer{clinics: [2]int{fromClinic, toClinic}, slots: [2]int{fromSlot, toSlot},
		before: [2]slot{first, second}, expiry: expiry}
	for i, c := range [2]*clinic{from, to} {
		incoming := p.before[1-i].holder
		if incoming == "" {
			continue
		}
		if c.members[incoming] == "" {
			panic("every incoming holder must be enrolled in the destination clinic")
		}
		if c.activeByHolder[incoming] != 0 {
			panic("holder already has an active appointment in destination clinic")
		}
		p.destinationGeneration[i] = c.bookingGeneration[incoming]
	}
	if transferTimeConflict(p) {
		panic("holder has overlapping appointment")
	}
	open := keepOpenTransfers(caller, now)
	if len(open) >= maxOpenTransfers {
		panic("withdraw or complete an open transfer")
	}
	id := nextTransferID
	nextTransferID++
	transfers[id] = p
	openTransfers[caller] = append(open, id)
	return id
}

func keepOpenTransfers(proposer address, now int64) []int {
	previous := openTransfers[proposer]
	open := make([]int, 0, len(previous))
	for _, id := range previous {
		state := transferState(transfers[id], now)
		switch state {
		case "open", "blocked":
			open = append(open, id)
		case "settled":
		default:
			delete(transfers, id)
		}
	}
	return open
}

// ApproveTransfer records or revokes consent for one exact role. A wallet
// serving more than one role must send a separate approval for each role.
// Roles 0 and 1 are the current holders. Roles 2 and 3 are the slot issuers.
func ApproveTransfer(cur realm, id, role int, approved bool) {
	runtime.AssertOriginCall()
	caller := signer(cur)
	p := requireTransfer(id, !approved)
	participants := transferAccounts(p)
	if role < 0 || role >= len(participants) || participants[role] == "" || participants[role] != caller {
		panic("transfer role signer required")
	}
	p.approved[role] = approved
}

func WithdrawTransfer(cur realm, id int) {
	runtime.AssertOriginCall()
	caller := signer(cur)
	p := requireTransfer(id, true)
	if p.before[0].holder != caller {
		panic("transfer proposer required")
	}
	p.terminal = "withdrawn"
}

func CancelTransfer(cur realm, id int) {
	runtime.AssertOriginCall()
	caller := signer(cur)
	p := requireTransfer(id, true)
	if p.before[0].issuer != caller && p.before[1].issuer != caller {
		panic("transfer issuer required")
	}
	p.terminal = "canceled"
}

func SettleTransfer(cur realm, id int) {
	runtime.AssertOriginCall()
	caller := signer(cur)
	p := requireTransfer(id, false)
	participating := false
	for role, account := range transferAccounts(p) {
		if account == "" {
			continue
		}
		if account == caller {
			participating = true
		}
		if !p.approved[role] {
			panic("all transfer participants must approve")
		}
	}
	if !participating {
		panic("transfer participant required")
	}
	for i, clinicID := range p.clinics {
		removeHolderBooking(clinics[clinicID], p.before[i])
	}
	// Both calendars have been rechecked. Issuers and times stay unchanged.
	for i, clinicID := range p.clinics {
		c := clinics[clinicID]
		slotID := p.slots[i]
		updated := transferredSlot(p, i)
		c.slots[slotID] = updated
		addHolderBooking(c, slotID, updated)
	}
	p.terminal = "settled"
	p.height = runtime.ChainHeight()
	p.time = time.Now().Unix()
}

func transferAccounts(p *transfer) [4]address {
	return [4]address{p.before[0].holder, p.before[1].holder, p.before[0].issuer, p.before[1].issuer}
}

func transferredSlot(p *transfer, index int) slot {
	s := p.before[index]
	s.holder = p.before[1-index].holder
	s.revision++
	return s
}

func transferTimeConflict(p *transfer) bool {
	for i, old := range p.before {
		released := bookingRef{p.clinics[i], p.slots[i], old.start}
		if old.holder != "" && scheduleConflict(holderSchedule, old.holder, p.before[1-i].start, released) {
			return true
		}
	}
	return false
}

func transferState(p *transfer, now int64) string {
	if p == nil {
		return "closed"
	}
	if p.terminal != "" {
		return p.terminal
	}
	if now >= p.expiry {
		return "expired"
	}
	for i, clinicID := range p.clinics {
		c := clinics[clinicID]
		if c == nil || !c.accepted || c.slots[p.slots[i]] != p.before[i] {
			return "stale"
		}
		incoming := p.before[1-i].holder
		if incoming != "" && (c.members[incoming] == "" || c.activeByHolder[incoming] != 0 ||
			c.bookingGeneration[incoming] != p.destinationGeneration[i]) {
			return "stale"
		}
	}
	if transferTimeConflict(p) {
		return "blocked"
	}
	return "open"
}

func requireTransfer(id int, closing bool) *transfer {
	p := transfers[id]
	state := transferState(p, time.Now().Unix())
	if state != "open" && (!closing || (state != "blocked" && state != "stale")) {
		panic("transfer is " + state)
	}
	return p
}

package slotswitch

import (
	"strconv"
	"strings"
	"time"
)

type TransferLegView struct {
	ClinicID int
	Before   ReservationView
	After    ReservationView
}

type TransferParticipantView struct {
	Role     int
	Account  address
	Approved bool
}

type TransferView struct {
	ID           int
	State        string
	Expiry       int64
	Proposer     address
	Legs         []TransferLegView
	Participants []TransferParticipantView
}

type TransferReceiptView struct {
	ProposalID int
	Height     int64
	Time       int64
	Legs       []TransferLegView
}

func Transfer(id int) TransferView {
	p := transfers[id]
	result := TransferView{ID: id, State: transferState(p, time.Now().Unix())}
	if p == nil {
		return result
	}
	result.Expiry = p.expiry
	result.Proposer = p.before[0].holder
	result.Legs = transferLegs(p)
	for role, account := range transferAccounts(p) {
		if account != "" {
			result.Participants = append(result.Participants, TransferParticipantView{Role: role, Account: account, Approved: p.approved[role]})
		}
	}
	return result
}

func TransferReceipt(id int) TransferReceiptView {
	p := transfers[id]
	if p == nil || p.terminal != "settled" {
		panic("settled transfer required")
	}
	return TransferReceiptView{ProposalID: id, Height: p.height, Time: p.time, Legs: transferLegs(p)}
}

func transferLegs(p *transfer) []TransferLegView {
	result := make([]TransferLegView, 0, len(p.clinics))
	for i, clinicID := range p.clinics {
		c := clinics[clinicID]
		result = append(result, TransferLegView{ClinicID: clinicID,
			Before: view(c, p.slots[i], p.before[i]), After: view(c, p.slots[i], transferredSlot(p, i))})
	}
	return result
}

func renderTransfer(path []string) string {
	if len(path) != 2 && len(path) != 3 {
		return "# Transfer unavailable"
	}
	id, err := strconv.Atoi(path[1])
	if err != nil || id <= 0 || transfers[id] == nil {
		return "# Transfer unavailable"
	}
	transfer := Transfer(id)
	var page strings.Builder
	if len(path) == 3 {
		if path[2] != "receipt" || transfer.State != "settled" {
			return "# Transfer receipt unavailable"
		}
		receipt := TransferReceipt(id)
		page.WriteString("# Transfer confirmed\n\nBlock " + strconv.FormatInt(receipt.Height, 10) + " at " + dateTime(receipt.Time) + ".")
	} else {
		page.WriteString("# Transfer " + strconv.Itoa(id) + "\n\nStatus: " + transfer.State + ".")
	}
	page.WriteString("\n\n| Clinic | Appointment | Original holder | ")
	if transfer.State == "settled" {
		page.WriteString("Confirmed holder")
	} else {
		page.WriteString("Proposed holder")
	}
	page.WriteString(" |\n|---|---|---|---|\n")
	for _, leg := range transfer.Legs {
		page.WriteString("| " + strconv.Itoa(leg.ClinicID) + " | " + dateTime(leg.Before.Start))
		page.WriteString(" | " + appointmentLabel(leg.Before) + " | " + appointmentLabel(leg.After) + " |\n")
	}
	return page.String()
}

func appointmentLabel(reservation ReservationView) string {
	if reservation.Holder == "" {
		return "Unassigned"
	}
	return reservation.Alias
}

package slotswitch

import (
	"sort"
	"strconv"
	"strings"
	"time"
)

type ReservationView struct {
	ID       int
	Issuer   address
	Holder   address
	Alias    string
	Start    int64
	Revision int
	Active   bool
}

type TeamView struct {
	Account address
	Alias   string
}

type ClinicView struct {
	ID            int
	Issuers       [2]address
	Accepted      bool
	DraftRevision int
	StartsAt      int64
	EndsAt        int64
	Cutoff        int64
	Teams         []TeamView
}

type ReceiptView struct {
	ClinicID   int
	ProposalID int
	Height     int64
	Time       int64
	Before     []ReservationView
	After      []ReservationView
}

type MoveView struct {
	Holder   address
	Gives    ReservationView
	Receives ReservationView
	Approved bool
}

type ProposalView struct {
	ClinicID   int
	ProposalID int
	State      string
	Expiry     int64
	Moves      []MoveView
}

func Clinic(clinicID int) ClinicView {
	c := requireClinic(clinicID)
	result := ClinicView{
		ID: clinicID, Issuers: c.issuers, Accepted: c.accepted, DraftRevision: c.draftRevision,
		StartsAt: c.startsAt, EndsAt: c.endsAt, Cutoff: c.cutoff,
	}
	for _, account := range c.enrolled {
		result.Teams = append(result.Teams, TeamView{Account: account, Alias: c.members[account]})
	}
	return result
}

func view(c *clinic, id int, s slot) ReservationView {
	return ReservationView{
		ID: id, Issuer: s.issuer, Holder: s.holder, Alias: c.members[s.holder], Start: s.start,
		Revision: s.revision, Active: s.active,
	}
}

func Roster(clinicID int) []ReservationView {
	c := requireClinic(clinicID)
	ids := make([]int, 0, len(c.activeSlots))
	for id := range c.activeSlots {
		ids = append(ids, id)
	}
	sort.Ints(ids)
	result := make([]ReservationView, 0, len(ids))
	for _, id := range ids {
		result = append(result, view(c, id, c.slots[id]))
	}
	return result
}

// RosterPage reads the retained historical slots after the given ID.
func RosterPage(clinicID, afterID, limit int) []ReservationView {
	if afterID < 0 || limit <= 0 || limit > maxIssuedSlots {
		panic("invalid roster page")
	}
	c := requireClinic(clinicID)
	result := make([]ReservationView, 0, limit)
	for id := afterID; id < len(c.slots) && len(result) < limit; {
		id++
		result = append(result, view(c, id, c.slots[id]))
	}
	return result
}

func Accepted(clinicID int) bool {
	return requireClinic(clinicID).accepted
}

func ProposalState(clinicID, proposalID int) string {
	c := requireClinic(clinicID)
	return planState(c, c.plans[proposalID], time.Now().Unix())
}

func Proposal(clinicID, proposalID int) ProposalView {
	c := requireClinic(clinicID)
	p := c.plans[proposalID]
	result := ProposalView{
		ClinicID: clinicID, ProposalID: proposalID, State: planState(c, p, time.Now().Unix()),
	}
	if p == nil {
		return result
	}
	result.Expiry = p.expiry
	for source := 0; source < p.size; source++ {
		destination := (source + 1) % p.size
		result.Moves = append(result.Moves, MoveView{
			Holder:   p.old[source].holder,
			Gives:    view(c, p.slots[source], p.old[source]),
			Receives: view(c, p.slots[destination], rotatedSlot(p, destination)),
			Approved: p.approved[source],
		})
	}
	return result
}

func Receipt(clinicID, proposalID int) ReceiptView {
	c := requireClinic(clinicID)
	p := c.plans[proposalID]
	if p == nil || !p.settled {
		panic("settled proposal required")
	}
	receipt := ReceiptView{ClinicID: clinicID, ProposalID: proposalID, Height: p.height, Time: p.confirmedAt}
	for i := 0; i < p.size; i++ {
		receipt.Before = append(receipt.Before, view(c, p.slots[i], p.old[i]))
		receipt.After = append(receipt.After, view(c, p.slots[i], rotatedSlot(p, i)))
	}
	return receipt
}

func Render(path string) string {
	if path == "" {
		return "# SlotSwitch v3\n\nOpen a clinic by its numeric ID or a cross-clinic exchange at `transfer/ID`."
	}
	segments := strings.Split(path, "/")
	if segments[0] == "transfer" {
		return renderTransfer(segments)
	}
	id, err := strconv.Atoi(segments[0])
	if err != nil || clinics[id] == nil {
		return "# Clinic unavailable"
	}
	if len(segments) == 3 && segments[1] == "proposal" {
		proposalID, err := strconv.Atoi(segments[2])
		if err != nil || proposalID <= 0 {
			return "# Proposal unavailable"
		}
		return renderProposal(Proposal(id, proposalID))
	}
	if len(segments) == 3 && segments[1] == "receipt" {
		proposalID, err := strconv.Atoi(segments[2])
		if err != nil || ProposalState(id, proposalID) != "settled" {
			return "# Receipt unavailable"
		}
		return renderReceipt(Receipt(id, proposalID))
	}
	if len(segments) != 1 {
		return "# Clinic page unavailable"
	}
	if !Accepted(id) {
		draft := Clinic(id)
		var page strings.Builder
		page.WriteString("# Clinic awaiting acceptance\n\n")
		page.WriteString("Draft revision " + strconv.Itoa(draft.DraftRevision))
		page.WriteString("\n\nClinic starts " + dateTime(draft.StartsAt))
		page.WriteString(" and ends " + dateTime(draft.EndsAt) + ".")
		page.WriteString("\n\nExchange cutoff " + dateTime(draft.Cutoff) + ".")
		page.WriteString("\n\nThe second desk must accept before either desk can issue bookings.\n")
		for _, team := range draft.Teams {
			page.WriteString("\n- " + team.Alias + " (" + team.Account.String() + ")")
		}
		return page.String()
	}
	var page strings.Builder
	page.WriteString("# Clinic ")
	page.WriteString(strconv.Itoa(id))
	page.WriteString("\n\n| Appointment | Issuer | Current holder | Status |\n|---|---|---|---|\n")
	for _, reservation := range Roster(id) {
		status := "Confirmed"
		holder := reservation.Alias + " (" + reservation.Holder.String() + ")"
		if reservation.Holder == "" {
			status = "Vacant"
			holder = "Unassigned"
		}
		page.WriteString("| ")
		page.WriteString(dateTime(reservation.Start))
		page.WriteString(" | ")
		page.WriteString(reservation.Issuer.String())
		page.WriteString(" | ")
		page.WriteString(holder)
		page.WriteString(" | ")
		page.WriteString(status)
		page.WriteString(" |\n")
	}
	return page.String()
}

func renderProposal(proposal ProposalView) string {
	var page strings.Builder
	page.WriteString("# Proposal ")
	page.WriteString(strconv.Itoa(proposal.ProposalID))
	page.WriteString("\n\nStatus: ")
	page.WriteString(proposal.State)
	page.WriteString("\n")
	if len(proposal.Moves) == 0 {
		return page.String()
	}
	page.WriteString("\nApproval cutoff: ")
	page.WriteString(dateTime(proposal.Expiry))
	page.WriteString("\n\n| Participant | Gives appointment | Receives appointment | Approval |\n|---|---|---|---|\n")
	for _, move := range proposal.Moves {
		approval := "Pending"
		if move.Approved {
			approval = "Approved"
		}
		page.WriteString("| " + move.Holder.String())
		page.WriteString(" | #" + strconv.Itoa(move.Gives.ID))
		page.WriteString(" | #" + strconv.Itoa(move.Receives.ID))
		page.WriteString(" | " + approval + " |\n")
	}
	return page.String()
}

func renderReceipt(receipt ReceiptView) string {
	var page strings.Builder
	page.WriteString("# Exchange confirmed\n\nBlock " + strconv.FormatInt(receipt.Height, 10))
	page.WriteString(" at " + dateTime(receipt.Time) + ".")
	page.WriteString("\n\n| Appointment | Previous holder | Confirmed holder |\n|---|---|---|\n")
	for index, before := range receipt.Before {
		after := receipt.After[index]
		page.WriteString("| " + dateTime(before.Start) + " | " + before.Alias + " | " + after.Alias + " |\n")
	}
	return page.String()
}

func dateTime(epochSeconds int64) string {
	return time.Unix(epochSeconds, 0).UTC().Format("02 Jan 15:04:05 UTC")
}

// Dragonhearth — a dragon-progression game realm for the Gnome Tavern hackathon.
//
// Loop: hatch a free soulbound dragon, train + feed it daily, win wild dragons
// on adventure, evolve with adventure shards, merge duplicates up a rarity.
// Dragons are canonical GRC721 tokens (gno.land/p/nt/grc721/v0); the starter
// is soulbound, wild dragons are tradeable. Food, shards and gear are realm
// balances, not tokens. No true randomness: every roll derives from block
// height + caller address. All cooldowns and daily limits use block height
// (1 day = 17280 blocks).
package dragonhearth

import (
	"chain/runtime"
	"strconv"
	"strings"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/grc721/v0"
	"gno.land/p/nt/markdown/sanitize/v0"
	"gno.land/p/nt/ufmt/v0"
)

// ---------------------------------------------------------------------------
// Constants
// ---------------------------------------------------------------------------

const (
	maxLevel            = 30
	maxDragonsPerWallet = 5
	blocksPerDay        = 17280
	trainCooldown       = 50 // blocks between trains of the same dragon
	maxTrainsPerDay     = 3
	maxDuelsPerDay      = 3
	maxAdventuresPerDay = 3
)

var (
	rarityNames = []string{"Hatchling", "Drake", "Wyrm", "Ancient", "Mythic"}
	// Per-stat cap per rarity.
	rarityCaps = []int64{50, 70, 90, 110, 130}
	// Power multiplier per rarity, x100 (1.00, 1.10, 1.25, 1.45, 1.70).
	rarityMult = []int64{100, 110, 125, 145, 170}
	// Evolve cost to reach rarity r+1 (index = current rarity).
	evolveLevels = []int64{5, 10, 15, 20}
	evolveCosts  = []int64{5, 8, 12, 10}
	evolveShards = []string{"Ember", "Frost", "Storm", "Mystery"}
	elements     = []string{"Ember", "Frost", "Storm", "Stone"}
	traits       = []string{"Brave", "Swift", "Hardy", "Stubborn"}
)

// ---------------------------------------------------------------------------
// State
// ---------------------------------------------------------------------------

// Dragon is one dragon. Stored by value in the dragons tree; always
// saveDragon after mutating a local copy.
type Dragon struct {
	ID              int64
	Owner           address
	Name            string
	Element         string
	Trait           string
	Rarity          int64 // 0 Hatchling .. 4 Mythic
	Soulbound       bool
	Power           int64
	Speed           int64
	Vitality        int64
	Level           int64
	XP              int64
	Hunger          int64 // 0..100, -10 per action, +30 per feed
	Growth          int64
	FeedCount       int64
	Bond            int64 // bond level: +1 per 7-day feed streak
	Streak          int64 // consecutive days fed
	LastFeedDay     int64
	LastTrainHeight int64
	TrainDay        int64
	TrainsToday     int64
}

// Wallet is one player's inventory and daily counters.
type Wallet struct {
	Food          int64
	Ember         int64 // Ember shards
	Frost         int64 // Frost shards
	Storm         int64 // Storm shards
	Mystery       int64 // Mystery shards
	Blades        int64 // Ember Blade gear
	Shields       int64 // Frost Shield gear
	Charms        int64 // Swift Charm gear
	HasStarter    bool
	LastForageDay int64
	DuelDay       int64
	DuelsToday    int64
	DuelWins      int64
	AdvDay        int64
	AdvsToday     int64
	ArmedItem     string // "", "Ember Blade", "Frost Shield", "Swift Charm"
	ArmedDragon   int64
}

var (
	// Token is the canonical GRC721 collection; ledger is its private ledger.
	// Only this realm holds the ledger, so only this realm can mint/burn.
	Token  *grc721.Token
	ledger *grc721.PrivateLedger

	dragons      avl.Tree // dragonID (decimal string) -> Dragon
	wallets      avl.Tree // owner address string -> Wallet
	nextDragonID int64
)

func init(cur realm) {
	Token, ledger = grc721.NewToken("Dragonhearth", "DRGN", 0, cur)
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

func checkErr(err error) {
	if err != nil {
		panic(err.Error())
	}
}

// dayNow is the current in-game day, derived from block height.
func dayNow() int64 {
	return runtime.ChainHeight() / blocksPerDay
}

// seedFrom mixes a caller address with a salt into a small positive seed.
// All "randomness" in this realm derives from block height + caller address.
func seedFrom(addr address, salt int64) int64 {
	s := int64(0)
	str := addr.String()
	for i := 0; i < len(str); i++ {
		s = (s*31 + int64(str[i])) % 1000003
	}
	s = (s + salt*7919) % 1000003
	if s < 0 {
		s = -s
	}
	return s
}

// roll returns a deterministic pseudo-random number in [0, n).
func roll(seed int64, n int64) int64 {
	if n <= 0 {
		return 0
	}
	x := seed % 1000003
	if x < 0 {
		x = -x
	}
	x = (x*1103515245 + 12345) % 2147483647
	return x % n
}

func dragonKey(id int64) string {
	return strconv.FormatInt(id, 10)
}

func getDragon(id int64) Dragon {
	v, ok := dragons.Get(dragonKey(id)).(Dragon)
	if !ok {
		panic("dragon not found")
	}
	return v
}

func saveDragon(d Dragon) {
	dragons.Set(dragonKey(d.ID), d)
}

func getWallet(addr address) Wallet {
	w, ok := wallets.Get(addr.String()).(Wallet)
	if !ok {
		w = Wallet{
			LastForageDay: -1,
			DuelDay:       -1,
			AdvDay:        -1,
			ArmedDragon:   -1,
		}
	}
	return w
}

func saveWallet(addr address, w Wallet) {
	wallets.Set(addr.String(), w)
}

func allDragons() []Dragon {
	out := []Dragon{}
	dragons.Iterate("", "", func(key string, value any) bool {
		d, ok := value.(Dragon)
		if ok {
			out = append(out, d)
		}
		return false
	})
	return out
}

func dragonsOf(owner address) []Dragon {
	out := []Dragon{}
	for _, d := range allDragons() {
		if d.Owner == owner {
			out = append(out, d)
		}
	}
	return out
}

func rarityName(r int64) string {
	if r < 0 || r >= int64(len(rarityNames)) {
		return "Unknown"
	}
	return rarityNames[r]
}

func rarityCap(r int64) int64 {
	return rarityCaps[r]
}

func rarityMultOf(r int64) int64 {
	return rarityMult[r]
}

// fightScore is the combat value of a dragon: all three stats matter, so
// every equipment item (+(15 + 2 x Level) to one stat) helps in a fight.
func fightScore(d Dragon) int64 {
	base := d.Power*2 + d.Speed + d.Vitality
	return base * rarityMultOf(d.Rarity) / 100
}

// equipmentBonus is the stat boost one consumable item gives in a Hard
// adventure: +15 flat + 2 per Level of the dragon using it. Level 1 -> +17,
// Level 10 -> +35, Level 20 -> +55, Level 30 -> +75. Scaling keeps gear
// relevant as dragons level up; a flat +15 would matter less and less,
// making Hard harder the stronger you get.
func equipmentBonus(d Dragon) int64 {
	return 15 + 2*d.Level
}

// addXP grants XP and applies level-ups (50 x level XP per level, max 30).
func addXP(d *Dragon, amount int64) {
	if amount <= 0 {
		return
	}
	d.XP += amount
	for d.Level < maxLevel && d.XP >= 50*d.Level {
		d.XP -= 50 * d.Level
		d.Level++
	}
}

func shardOf(w Wallet, kind string) int64 {
	switch kind {
	case "Ember":
		return w.Ember
	case "Frost":
		return w.Frost
	case "Storm":
		return w.Storm
	case "Mystery":
		return w.Mystery
	}
	return 0
}

func addShard(w *Wallet, kind string, n int64) {
	switch kind {
	case "Ember":
		w.Ember += n
	case "Frost":
		w.Frost += n
	case "Storm":
		w.Storm += n
	case "Mystery":
		w.Mystery += n
	}
}

func gearOf(w Wallet, item string) int64 {
	switch item {
	case "Ember Blade":
		return w.Blades
	case "Frost Shield":
		return w.Shields
	case "Swift Charm":
		return w.Charms
	}
	return 0
}

func addGear(w *Wallet, item string, n int64) {
	switch item {
	case "Ember Blade":
		w.Blades += n
	case "Frost Shield":
		w.Shields += n
	case "Swift Charm":
		w.Charms += n
	}
}

func gearItems() []string {
	return []string{"Ember Blade", "Frost Shield", "Swift Charm"}
}

// elementStat is the stat that earns +5 bonus XP when trained: the dragon's
// element stat. Ember -> Power, Storm -> Speed, Frost/Stone -> Vitality.
func elementStat(element string) string {
	switch element {
	case "Ember":
		return "Power"
	case "Storm":
		return "Speed"
	default:
		return "Vitality"
	}
}

func validName(name string) bool {
	if len(name) == 0 || len(name) > 24 {
		return false
	}
	for i := 0; i < len(name); i++ {
		c := name[i]
		ok := (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') ||
			(c >= '0' && c <= '9') || c == ' ' || c == '-' || c == '\''
		if !ok {
			return false
		}
	}
	return true
}

func validElement(element string) bool {
	for _, e := range elements {
		if e == element {
			return true
		}
	}
	return false
}

// mintDragon creates a dragon, mints its GRC721 token to the owner, and
// returns its ID.
func mintDragon(owner address, name, element, trait string, rarity, power, speed, vitality int64, soulbound bool) int64 {
	id := nextDragonID
	nextDragonID++
	d := Dragon{
		ID:              id,
		Owner:           owner,
		Name:            name,
		Element:         element,
		Trait:           trait,
		Rarity:          rarity,
		Soulbound:       soulbound,
		Power:           power,
		Speed:           speed,
		Vitality:        vitality,
		Level:           1,
		XP:              0,
		Hunger:          100,
		Growth:          0,
		FeedCount:       0,
		Bond:            0,
		Streak:          0,
		LastFeedDay:     -1,
		LastTrainHeight: -1000000,
		TrainDay:        -1,
		TrainsToday:     0,
	}
	checkErr(ledger.Mint(owner, grc721.TokenID(dragonKey(id))))
	saveDragon(d)
	return id
}

// ---------------------------------------------------------------------------
// Crossing functions — the game
// ---------------------------------------------------------------------------

// Hatch mints the caller's one free soulbound Hatchling. Name is chosen by
// the owner; the trait is rolled from block height + caller address.
func Hatch(cur realm, name, element string) int64 {
	caller := cur.Previous().Address()
	if !validName(name) {
		panic("invalid name: 1-24 chars, letters, digits, spaces, - and ' only")
	}
	if !validElement(element) {
		panic("invalid element: Ember, Frost, Storm or Stone")
	}
	w := getWallet(caller)
	if w.HasStarter {
		panic("you already hatched your starter dragon")
	}
	if len(dragonsOf(caller)) >= maxDragonsPerWallet {
		panic("dragon cap reached (5 per wallet)")
	}
	seed := seedFrom(caller, runtime.ChainHeight())
	power := int64(20) + roll(seed+1, 11)
	speed := int64(20) + roll(seed+2, 11)
	vitality := int64(20) + roll(seed+3, 11)
	trait := traits[roll(seed+4, 4)]
	switch trait {
	case "Brave":
		power += 5
	case "Swift":
		speed += 5
	case "Hardy":
		vitality += 5
	}
	id := mintDragon(caller, name, element, trait, 0, power, speed, vitality, true)
	w.HasStarter = true
	saveWallet(caller, w)
	return id
}

// Train gives +2 to one stat and +10 XP (+5 bonus XP when training the
// dragon's element stat). Instant, but 50-block cooldown per dragon and max
// 3/day. Costs 10 Hunger; below 30 Hunger training XP is halved.
func Train(cur realm, dragonID int64, stat string) string {
	caller := cur.Previous().Address()
	d := getDragon(dragonID)
	if d.Owner != caller {
		panic("not your dragon")
	}
	if stat != "Power" && stat != "Speed" && stat != "Vitality" {
		panic("stat must be Power, Speed or Vitality")
	}
	height := runtime.ChainHeight()
	if height-d.LastTrainHeight < trainCooldown {
		panic("training cooldown: wait 50 blocks between trains")
	}
	day := dayNow()
	if d.TrainDay != day {
		d.TrainDay = day
		d.TrainsToday = 0
	}
	if d.TrainsToday >= maxTrainsPerDay {
		panic("already trained 3 times today")
	}
	hungry := d.Hunger < 30
	xp := int64(10)
	if stat == elementStat(d.Element) {
		xp += 5
	}
	if hungry {
		xp = xp / 2
	}
	statCap := rarityCap(d.Rarity)
	switch stat {
	case "Power":
		d.Power += 2
		if d.Power  > statCap {
			d.Power = statCap
		}
	case "Speed":
		d.Speed += 2
		if d.Speed  > statCap {
			d.Speed = statCap
		}
	case "Vitality":
		d.Vitality += 2
		if d.Vitality  > statCap {
			d.Vitality = statCap
		}
	}
	d.Hunger -= 10
	if d.Hunger < 0 {
		d.Hunger = 0
	}
	addXP(&d, xp)
	d.LastTrainHeight = height
	d.TrainsToday++
	saveDragon(d)
	return ufmt.Sprintf("Trained %s (+2 %s, +%d XP). Level %d, Hunger %d.",
		d.Name, stat, xp, d.Level, d.Hunger)
}

// ClaimFood forages 1 Food per day, free.
func ClaimFood(cur realm) int64 {
	caller := cur.Previous().Address()
	w := getWallet(caller)
	day := dayNow()
	if w.LastForageDay == day {
		panic("already foraged today")
	}
	w.Food++
	w.LastForageDay = day
	saveWallet(caller, w)
	return w.Food
}

// Feed spends 1 Food: +15 XP (+5 more with the Stubborn trait), +1 Growth,
// +30 Hunger. Every 5 feeds +1 Vitality. Feeding the same dragon 7 days in
// a row raises its Bond level (+2 bonus Growth); missing a day resets the streak.
func Feed(cur realm, dragonID int64) string {
	caller := cur.Previous().Address()
	d := getDragon(dragonID)
	if d.Owner != caller {
		panic("not your dragon")
	}
	w := getWallet(caller)
	if w.Food < 1 {
		panic("no food: forage (ClaimFood) or win an adventure first")
	}
	w.Food--
	xp := int64(15)
	if d.Trait == "Stubborn" {
		xp += 5
	}
	d.Hunger += 30
	if d.Hunger > 100 {
		d.Hunger = 100
	}
	d.Growth++
	d.FeedCount++
	if d.FeedCount%5 == 0 {
		d.Vitality++
		if d.Vitality > rarityCap(d.Rarity) {
			d.Vitality = rarityCap(d.Rarity)
		}
	}
	day := dayNow()
	bondMsg := ""
	if d.LastFeedDay != day {
		if d.LastFeedDay == day-1 {
			d.Streak++
		} else {
			d.Streak = 1
		}
		d.LastFeedDay = day
		if d.Streak%7 == 0 {
			d.Bond++
			d.Growth += 2
			bondMsg = ufmt.Sprintf(" Bond up! Bond level %d.", d.Bond)
		}
	}
	addXP(&d, xp)
	saveDragon(d)
	saveWallet(caller, w)
	return ufmt.Sprintf("Fed %s (+%d XP, Hunger %d, streak %d days).%s",
		d.Name, xp, d.Hunger, d.Streak, bondMsg)
}

// pickOpponent picks a realm-picked duel opponent: another player's dragon
// within Level +/-2 of d. Your own dragons are never valid opponents (a
// player must not be able to farm easy wins against their own weak wild
// dragon). found=false means no such dragon exists and the caller should
// use the sparring phantom instead.
func pickOpponent(caller address, d Dragon, candidates []Dragon, seed int64) (Dragon, bool) {
	others := []Dragon{}
	for _, o := range candidates {
		if o.ID != d.ID && o.Owner != caller && o.Level >= d.Level-2 && o.Level <= d.Level+2 {
			others = append(others, o)
		}
	}
	if len(others) == 0 {
		return Dragon{}, false
	}
	return others[roll(seed+10, int64(len(others)))], true
}

// Duel fights a realm-picked opponent dragon (Level +/-2 when other dragons
// exist, otherwise a sparring phantom near your own strength). Win +20 XP,
// lose +5 XP. Every 3rd win earns 1 Food. Costs 10 Hunger.
func Duel(cur realm, dragonID int64) string {
	caller := cur.Previous().Address()
	d := getDragon(dragonID)
	if d.Owner != caller {
		panic("not your dragon")
	}
	w := getWallet(caller)
	day := dayNow()
	if w.DuelDay != day {
		w.DuelDay = day
		w.DuelsToday = 0
	}
	if w.DuelsToday >= maxDuelsPerDay {
		panic("already dueled 3 times today")
	}
	seed := seedFrom(caller, runtime.ChainHeight()+dragonID)
	// Pick an opponent: another player's dragon within Level +/-2 if one
	// exists (never your own dragon). Otherwise a sparring phantom.
	opp, found := pickOpponent(caller, d, allDragons(), seed)
	if !found {
		// Sparring phantom, 95% of your own stats.
		opp = Dragon{
			Name:     "Sparring Phantom",
			Element:  d.Element,
			Rarity:   d.Rarity,
			Power:    d.Power * 95 / 100,
			Speed:    d.Speed * 95 / 100,
			Vitality: d.Vitality * 95 / 100,
		}
	}
	ownScore := fightScore(d)
	if d.Hunger < 30 {
		ownScore = ownScore * 80 / 100
	}
	ownScore = ownScore * (100 + roll(seed+20, 21) - 10) / 100
	oppScore := fightScore(opp)
	win := ownScore >= oppScore
	d.Hunger -= 10
	if d.Hunger < 0 {
		d.Hunger = 0
	}
	msg := ""
	if win {
		addXP(&d, 20)
		w.DuelWins++
		if w.DuelWins%3 == 0 {
			w.Food++
			msg = ufmt.Sprintf("WIN vs %s! +20 XP. 3rd win: +1 Food.", opp.Name)
		} else {
			msg = ufmt.Sprintf("WIN vs %s! +20 XP.", opp.Name)
		}
	} else {
		addXP(&d, 5)
		msg = ufmt.Sprintf("LOSS vs %s. +5 XP.", opp.Name)
	}
	w.DuelsToday++
	saveDragon(d)
	saveWallet(caller, w)
	return msg
}

// Adventure fights a wild dragon. Tiers:
//   - Easy: wild at ~50% of your Power. Reward: wild Hatchling + 1 Ember shard + 10 XP + 1 Food.
//   - Normal: wild at 90-100%. Reward: wild Hatchling/Drake + 2 Frost shards + 20 XP + 2 Food, 40% gear drop.
//   - Hard: wild at 130-150%. Reward: wild Drake/Wyrm + 4 Storm shards + 40 XP + 3 Food, gear guaranteed.
//     Equipment may be used (see UseEquipment).
//   - Mystery: tier rolled at entry (30% Easy, 40% Normal, 30% Hard), rewards x1.5,
//     plus 2 Mystery shards. Only place Mystery shards drop.
// Win captures the wild dragon (unless you are at the 5-dragon cap). Lose:
// no dragon is lost, only Hunger.
func Adventure(cur realm, dragonID int64, tier string) string {
	caller := cur.Previous().Address()
	d := getDragon(dragonID)
	if d.Owner != caller {
		panic("not your dragon")
	}
	if tier != "Easy" && tier != "Normal" && tier != "Hard" && tier != "Mystery" {
		panic("tier must be Easy, Normal, Hard or Mystery")
	}
	w := getWallet(caller)
	day := dayNow()
	if w.AdvDay != day {
		w.AdvDay = day
		w.AdvsToday = 0
	}
	if w.AdvsToday >= maxAdventuresPerDay {
		panic("already adventured 3 times today")
	}
	seed := seedFrom(caller, runtime.ChainHeight()+dragonID*7)
	resolved := tier
	if tier == "Mystery" {
		r := roll(seed+1, 100)
		if r < 30 {
			resolved = "Easy"
		} else if r < 70 {
			resolved = "Normal"
		} else {
			resolved = "Hard"
		}
	}
	// Wild dragon strength as a percentage of your Power.
	ratio := int64(50)
	wildRarity := int64(0)
	shardKind := "Ember"
	shardN := int64(1)
	xpReward := int64(10)
	foodReward := int64(1)
	if resolved == "Normal" {
		ratio = 90 + roll(seed+2, 11) // 90-100
		wildRarity = roll(seed+3, 2)  // Hatchling or Drake
		shardKind = "Frost"
		shardN = 2
		xpReward = 20
		foodReward = 2
	} else if resolved == "Hard" {
		ratio = 130 + roll(seed+4, 21) // 130-150
		wildRarity = 1 + roll(seed+5, 2) // Drake or Wyrm
		shardKind = "Storm"
		shardN = 4
		xpReward = 40
		foodReward = 3
	}
	if tier == "Mystery" {
		// Rewards x1.5 (rounded up).
		shardN = (shardN*3 + 1) / 2
		xpReward = (xpReward*3 + 1) / 2
		foodReward = (foodReward*3 + 1) / 2
	}
	// Build the wild dragon.
	wildElement := elements[roll(seed+6, 4)]
	wild := Dragon{
		Name:     "Wild " + wildElement,
		Element:  wildElement,
		Trait:    traits[roll(seed+7, 4)],
		Rarity:   wildRarity,
		Power:    d.Power * ratio / 100,
		Speed:    d.Speed * ratio / 100,
		Vitality: d.Vitality * ratio / 100,
	}
	if wild.Power < 1 {
		wild.Power = 1
	}
	if wild.Speed < 1 {
		wild.Speed = 1
	}
	if wild.Vitality < 1 {
		wild.Vitality = 1
	}
	// Equipment: Hard only, 1 consumable item armed via UseEquipment, burned
	// on this run whether you win or lose. The bonus (+(15 + 2 x Level))
	// applies to a copy used only for this fight's score — it never changes
	// the stored dragon.
	usedItem := ""
	fd := d
	if resolved == "Hard" && w.ArmedItem != "" && w.ArmedDragon == dragonID {
		usedItem = w.ArmedItem
		bonus := equipmentBonus(d)
		switch usedItem {
		case "Ember Blade":
			fd.Power += bonus
		case "Frost Shield":
			fd.Vitality += bonus
		case "Swift Charm":
			fd.Speed += bonus
		}
		addGear(&w, usedItem, -1)
		w.ArmedItem = ""
		w.ArmedDragon = -1
	}
	ownScore := fightScore(fd)
	if d.Hunger < 30 {
		ownScore = ownScore * 80 / 100
	}
	ownScore = ownScore * (100 + roll(seed+8, 21) - 10) / 100
	wildScore := fightScore(wild)
	win := ownScore >= wildScore
	d.Hunger -= 10
	if d.Hunger < 0 {
		d.Hunger = 0
	}
	w.AdvsToday++
	if !win {
		saveDragon(d)
		saveWallet(caller, w)
		if usedItem != "" {
			return ufmt.Sprintf("LOSS in %s adventure (used %s). Your dragon is safe, only Hunger lost.", resolved, usedItem)
		}
		return ufmt.Sprintf("LOSS in %s adventure. Your dragon is safe, only Hunger lost.", resolved)
	}
	// Win: rewards.
	addXP(&d, xpReward)
	addShard(&w, shardKind, shardN)
	w.Food += foodReward
	gearMsg := ""
	if resolved == "Normal" {
		if roll(seed+9, 100) < 40 {
			item := gearItems()[roll(seed+11, 3)]
			addGear(&w, item, 1)
			gearMsg = " Found 1 " + item + "!"
		}
	} else if resolved == "Hard" {
		item := gearItems()[roll(seed+11, 3)]
		addGear(&w, item, 1)
		gearMsg = " Found 1 " + item + "!"
	}
	if tier == "Mystery" {
		addShard(&w, "Mystery", 2)
	}
	captureMsg := ""
	if len(dragonsOf(caller)) < maxDragonsPerWallet {
		wildName := wild.Name + " #" + strconv.FormatInt(nextDragonID, 10)
		mintDragon(caller, wildName, wild.Element, wild.Trait, wild.Rarity,
			wild.Power, wild.Speed, wild.Vitality, false)
		captureMsg = " Captured a wild " + rarityName(wild.Rarity) + "!"
	} else {
		captureMsg = " Dragon cap (5) reached: no capture, rewards kept."
	}
	saveDragon(d)
	saveWallet(caller, w)
	return ufmt.Sprintf("WIN in %s adventure! +%d XP, +%d %s shards, +%d Food.%s%s",
		resolved, xpReward, shardN, shardKind, foodReward, gearMsg, captureMsg)
}

// UseEquipment arms one consumable item for the dragon's next Hard adventure.
// The item is burned on that Hard run, win or lose. Hard mode only.
func UseEquipment(cur realm, dragonID int64, item string) string {
	caller := cur.Previous().Address()
	d := getDragon(dragonID)
	if d.Owner != caller {
		panic("not your dragon")
	}
	if item != "Ember Blade" && item != "Frost Shield" && item != "Swift Charm" {
		panic("item must be Ember Blade, Frost Shield or Swift Charm")
	}
	w := getWallet(caller)
	if gearOf(w, item) < 1 {
		panic("you do not own that item: win Normal/Hard adventures to earn gear")
	}
	w.ArmedItem = item
	w.ArmedDragon = dragonID
	saveWallet(caller, w)
	return ufmt.Sprintf("%s armed %s (+%d) for its next Hard adventure. It will be consumed on that run.",
		d.Name, item, equipmentBonus(d))
}

// Evolve raises a dragon one rarity, guaranteed once the Level threshold and
// shard cost are paid. Stats are kept; caps and the Power multiplier rise.
func Evolve(cur realm, dragonID int64) string {
	caller := cur.Previous().Address()
	d := getDragon(dragonID)
	if d.Owner != caller {
		panic("not your dragon")
	}
	if d.Rarity >= 4 {
		panic("already Mythic: the highest rarity")
	}
	needLevel := evolveLevels[d.Rarity]
	needShards := evolveCosts[d.Rarity]
	kind := evolveShards[d.Rarity]
	if d.Level < needLevel {
		panic(ufmt.Sprintf("needs Level %d to evolve (currently %d)", needLevel, d.Level))
	}
	w := getWallet(caller)
	if shardOf(w, kind) < needShards {
		panic(ufmt.Sprintf("needs %d %s shards (you have %d): adventure to earn them",
			needShards, kind, shardOf(w, kind)))
	}
	addShard(&w, kind, -needShards)
	d.Rarity++
	saveDragon(d)
	saveWallet(caller, w)
	return ufmt.Sprintf("%s evolved into a %s! Stat cap now %d.",
		d.Name, rarityName(d.Rarity), rarityCap(d.Rarity))
}

// Merge burns two dragons of the same rarity (both yours, neither the
// soulbound starter) and mints one of the next rarity at Level 1, with stats
// averaged +5.
func Merge(cur realm, id1, id2 int64) int64 {
	caller := cur.Previous().Address()
	if id1 == id2 {
		panic("merge needs two different dragons")
	}
	d1 := getDragon(id1)
	d2 := getDragon(id2)
	if d1.Owner != caller || d2.Owner != caller {
		panic("both dragons must be yours")
	}
	if d1.Rarity != d2.Rarity {
		panic("merge needs two dragons of the same rarity")
	}
	if d1.Rarity >= 4 {
		panic("cannot merge Mythic dragons")
	}
	if d1.Soulbound || d2.Soulbound {
		panic("the soulbound starter dragon cannot be merged away")
	}
	newRarity := d1.Rarity + 1
	statCap := rarityCap(newRarity)
	power := (d1.Power+d2.Power)/2 + 5
	speed := (d1.Speed+d2.Speed)/2 + 5
	vitality := (d1.Vitality+d2.Vitality)/2 + 5
	if power  > statCap {
		power = statCap
	}
	if speed  > statCap {
		speed = statCap
	}
	if vitality  > statCap {
		vitality = statCap
	}
	name := "Heir of " + d1.Name
	if len(name) > 24 {
		name = name[:24]
	}
	checkErr(ledger.Burn(grc721.TokenID(dragonKey(id1))))
	checkErr(ledger.Burn(grc721.TokenID(dragonKey(id2))))
	dragons.Remove(dragonKey(id1))
	dragons.Remove(dragonKey(id2))
	seed := seedFrom(caller, runtime.ChainHeight()+id1+id2)
	trait := traits[roll(seed, 4)]
	return mintDragon(caller, name, d1.Element, trait, newRarity, power, speed, vitality, false)
}

// Transfer moves a wild dragon to another address. The soulbound starter
// can never be transferred.
func Transfer(cur realm, dragonID int64, to address) string {
	caller := cur.Previous().Address()
	d := getDragon(dragonID)
	if d.Owner != caller {
		panic("not your dragon")
	}
	if d.Soulbound {
		panic("the starter dragon is soulbound and cannot be transferred")
	}
	if !to.IsValid() {
		panic("invalid address")
	}
	if to != caller && len(dragonsOf(to)) >= maxDragonsPerWallet {
		panic("recipient already has 5 dragons")
	}
	checkErr(ledger.TransferFrom(caller, caller, to, grc721.TokenID(dragonKey(dragonID))))
	d.Owner = to
	saveDragon(d)
	return ufmt.Sprintf("Transferred %s (#%d) to %s.", d.Name, d.ID, to.String())
}

// ---------------------------------------------------------------------------
// Read-only helpers
// ---------------------------------------------------------------------------

// TotalDragons returns the number of dragons ever minted.
func TotalDragons() int64 {
	return nextDragonID
}

// DragonInfo returns a one-line summary of a dragon.
func DragonInfo(id int64) string {
	d := getDragon(id)
	return ufmt.Sprintf("#%d %s [%s %s, %s] Lv%d XP%d P%d/S%d/V%d Hunger%d Bond%d",
		d.ID, d.Name, rarityName(d.Rarity), d.Element, d.Trait,
		d.Level, d.XP, d.Power, d.Speed, d.Vitality, d.Hunger, d.Bond)
}

// WalletInfo returns a one-line summary of a wallet's inventory.
func WalletInfo(addr address) string {
	w := getWallet(addr)
	return ufmt.Sprintf("Food %d | Shards Ember %d Frost %d Storm %d Mystery %d | Gear Blade %d Shield %d Charm %d | Dragons %d",
		w.Food, w.Ember, w.Frost, w.Storm, w.Mystery,
		w.Blades, w.Shields, w.Charms, int64(len(dragonsOf(addr))))
}

// xpText describes progress to the next level. At Max Level there is no
// next level, so it says so instead of showing a bogus "XP x / 1500 to next".
func xpText(d Dragon) string {
	if d.Level >= maxLevel {
		return "MAX LEVEL"
	}
	return ufmt.Sprintf("XP %d / %d to next", d.XP, 50*d.Level)
}

func nextEvolveText(d Dragon, w Wallet) string {
	if d.Rarity >= 4 {
		return "Max rarity (Mythic)."
	}
	needLevel := evolveLevels[d.Rarity]
	needShards := evolveCosts[d.Rarity]
	kind := evolveShards[d.Rarity]
	return ufmt.Sprintf("Next evolve: %s at Level %d + %d %s shards (you have Level %d, %d %s shards).",
		rarityName(d.Rarity+1), needLevel, needShards, kind,
		d.Level, shardOf(w, kind), kind)
}

// ---------------------------------------------------------------------------
// Render — the playable UI
// ---------------------------------------------------------------------------

// Render serves the game page. "" is the home page (leaderboard + all
// dragons), "dragon/<id>" is one dragon's sheet, "wallet/<addr>" is one
// wallet's hearth. gnoweb calls Render with the path after the ":" in the
// URL (no leading slash), e.g. /r/velt/dragonhearth:dragon/0.
// Names are user-supplied and sanitized before output.
func Render(path string) string {
	if path == "" {
		return renderHome()
	}
	path = strings.TrimPrefix(path, "/")
	parts := strings.Split(path, "/")
	if len(parts) == 2 && parts[0] == "dragon" {
		id, err := strconv.Atoi(parts[1])
		if err != nil {
			return "404\n"
		}
		return renderDragon(int64(id))
	}
	if len(parts) == 2 && parts[0] == "wallet" {
		addr := parts[1]
		if len(addr) != 40 || !strings.HasPrefix(addr, "g1") {
			return "404\n"
		}
		return renderWallet(address(addr))
	}
	return "404\n"
}

func renderHome() string {
	all := allDragons()
	// Leaderboard: top 5 by fight score (simple sort, n is small).
	sorted := make([]Dragon, len(all))
	for i, d := range all {
		sorted[i] = d
	}
	for i := 0; i < len(sorted); i++ {
		for j := i + 1; j < len(sorted); j++ {
			if fightScore(sorted[j]) > fightScore(sorted[i]) {
				tmp := sorted[i]
				sorted[i] = sorted[j]
				sorted[j] = tmp
			}
		}
	}
	s := "# Dragonhearth\n\n"
	s += "Hatch a dragon, train and feed it daily, win wild dragons on adventure, evolve and merge it up.\n\n"
	s += ufmt.Sprintf("**Dragons hatched:** %d | **Total supply (DRGN):** %d\n\n", len(all), Token.TotalSupply())
	s += "## Hall of Ancients — Top 5\n\n"
	if len(sorted) == 0 {
		s += "No dragons yet. Hatch the first one!\n\n"
	} else {
		for i := 0; i < len(sorted) && i < 5; i++ {
			d := sorted[i]
			s += ufmt.Sprintf("%d. **%s** (#%d, %s %s, Lv%d) — score %d, owner %s\n",
				i+1, sanitize.InlineText(d.Name), d.ID, rarityName(d.Rarity),
				d.Element, d.Level, fightScore(d), d.Owner.String())
		}
		s += "\n"
	}
	s += "## All Dragons\n\n"
	if len(all) == 0 {
		s += "None yet.\n"
	} else {
		shown := 0
		for _, d := range all {
			if shown >= 50 {
				break
			}
			s += ufmt.Sprintf("- #%d **%s** (%s %s, %s) Lv%d P%d/S%d/V%d — :dragon/%d\n",
				d.ID, sanitize.InlineText(d.Name), rarityName(d.Rarity),
				d.Element, d.Trait, d.Level, d.Power, d.Speed, d.Vitality, d.ID)
			shown++
		}
	}
	s += "\n## How to play\n\n"
	s += "1. `Hatch(name, element)` — one free soulbound Hatchling per wallet.\n"
	s += "2. `Train(id, stat)` — 3/day, +2 stat, +10 XP. `ClaimFood()` daily, `Feed(id)` to restore Hunger.\n"
	s += "3. `Adventure(id, tier)` — Easy/Normal/Hard/Mystery, 3/day. Win a wild dragon + shards.\n"
	s += "4. `Evolve(id)` — Level + shards. `Merge(id1, id2)` — two same-rarity dragons into one stronger.\n"
	s += "5. `Duel(id)` — 3/day vs a realm-picked opponent. `UseEquipment(id, item)` arms gear for Hard runs.\n"
	return s
}

func renderDragon(id int64) string {
	v, ok := dragons.Get(dragonKey(id)).(Dragon)
	if !ok {
		return "404\n"
	}
	d := v
	w := getWallet(d.Owner)
	s := ufmt.Sprintf("# %s (#%d)\n\n", sanitize.InlineText(d.Name), d.ID)
	s += ufmt.Sprintf("**%s %s** — Trait: %s | Owner: %s\n\n",
		rarityName(d.Rarity), d.Element, d.Trait, d.Owner.String())
	if d.Soulbound {
		s += "Soulbound starter dragon — cannot be transferred or merged.\n\n"
	}
	s += ufmt.Sprintf("**Level %d** (%s) | **Power %d / Speed %d / Vitality %d** (cap %d)\n\n",
		d.Level, xpText(d), d.Power, d.Speed, d.Vitality, rarityCap(d.Rarity))
	s += ufmt.Sprintf("**Hunger %d** | Growth %d | Bond level %d (feed streak %d days)\n\n",
		d.Hunger, d.Growth, d.Bond, d.Streak)
	s += nextEvolveText(d, w) + "\n\n"
	s += "## Owner inventory\n\n"
	s += WalletInfo(d.Owner) + "\n"
	return s
}

func renderWallet(addr address) string {
	ds := dragonsOf(addr)
	s := ufmt.Sprintf("# Hearth of %s\n\n", addr.String())
	s += WalletInfo(addr) + "\n\n"
	if len(ds) == 0 {
		s += "No dragons yet. Hatch one with `Hatch(name, element)`.\n"
		return s
	}
	for _, d := range ds {
		s += ufmt.Sprintf("- #%d **%s** (%s %s, %s) Lv%d P%d/S%d/V%d Hunger%d — :dragon/%d\n",
			d.ID, sanitize.InlineText(d.Name), rarityName(d.Rarity),
			d.Element, d.Trait, d.Level, d.Power, d.Speed, d.Vitality, d.Hunger, d.ID)
	}
	return s
}

package dragonhearth

import (
	"strings"
	"testing"

	"gno.land/p/nt/testutils/v0"
	"gno.land/p/nt/uassert/v0"
	"gno.land/p/nt/urequire/v0"
)

func TestHatch(cur realm, t *testing.T) {
	alice := testutils.TestAddress("alice")
	testing.SetOriginCaller(alice)
	id := Hatch(cross(cur), "Ember", "Ember")
	d := getDragon(id)
	uassert.Equal(t, int64(1), d.Level)
	uassert.Equal(t, int64(0), d.XP)
	uassert.Equal(t, int64(100), d.Hunger)
	uassert.True(t, d.Soulbound)
	uassert.True(t, d.Power >= 20 && d.Power <= 35)
	uassert.True(t, d.Speed >= 20 && d.Speed <= 35)
	uassert.True(t, d.Vitality >= 20 && d.Vitality <= 35)
	uassert.True(t, d.Trait == "Brave" || d.Trait == "Swift" || d.Trait == "Hardy" || d.Trait == "Stubborn")
	// One starter per wallet.
	urequire.AbortsContains(t, cur, "already hatched", func() {
		Hatch(cross(cur), "Second", "Storm")
	})
}

func TestHatchInvalid(cur realm, t *testing.T) {
	alice := testutils.TestAddress("alice2")
	testing.SetOriginCaller(alice)
	urequire.AbortsContains(t, cur, "invalid element", func() {
		Hatch(cross(cur), "Bad", "Water")
	})
	urequire.AbortsContains(t, cur, "invalid name", func() {
		Hatch(cross(cur), "Bad[Name]", "Ember")
